// Prevent known late Playwright lifecycle events from crashing the server while
// preserving fail-fast behavior for every unrelated exception/rejection.
function handleProcessFailure(label, failure) {
  const error = failure instanceof Error ? failure : Object.assign(
    new Error(String(failure?.message || failure)),
    failure && typeof failure === 'object' ? failure : {},
  );
  if (isIgnorablePlaywrightLifecycleError(error)) {
    console.warn(`[playwright] Ignoring stale lifecycle error (${label}):`, error.message);
    return;
  }
  console.error(`${label}:`, failure);
  process.exit(1);
}

process.on('uncaughtException', (error) => handleProcessFailure('Uncaught exception', error));
process.on('unhandledRejection', (reason) => handleProcessFailure('Unhandled rejection', reason));

