// --- UI State Persistence (replaces browser localStorage) ---

const UI_STATE_PATH = resolve(DATA_HOME, 'data', 'ui-state.json');

// ui-state.json is multi-MB; synchronously re-reading and rewriting it on every
// PATCH stalls the event loop (and every streaming WebSocket) for tens of ms.
// Serve from an in-memory cache and persist with a debounced async atomic write.
// Callers mutate the object returned by loadUiState() and pass it back to
// saveUiState(), so the cache must hand out the live object, never a copy.
let _uiStateCache = null;
let _uiStateDirty = false;
let _uiStateFlushTimer = null;
let _uiStateWriteChain = Promise.resolve();
const UI_STATE_FLUSH_MS = 1000;

function loadUiState() {
  if (_uiStateCache) return _uiStateCache;
  try {
    _uiStateCache = JSON.parse(readFileSync(UI_STATE_PATH, 'utf-8'));
  } catch {
    _uiStateCache = { _version: 1, _updated: new Date().toISOString() };
  }
  return _uiStateCache;
}

function saveUiState(data) {
  _uiStateCache = data;
  data._updated = new Date().toISOString();
  _uiStateDirty = true;
  if (!_uiStateFlushTimer) {
    _uiStateFlushTimer = setTimeout(() => {
      _uiStateFlushTimer = null;
      flushUiStateAsync();
    }, UI_STATE_FLUSH_MS);
    _uiStateFlushTimer.unref?.();
  }
}

function flushUiStateAsync() {
  if (!_uiStateDirty || !_uiStateCache) return _uiStateWriteChain;
  _uiStateDirty = false;
  const json = JSON.stringify(_uiStateCache, null, 2) + '\n';
  _uiStateWriteChain = _uiStateWriteChain.then(async () => {
    const dir = resolve(UI_STATE_PATH, '..');
    if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
    const tmp = UI_STATE_PATH + '.tmp';
    await fsp.writeFile(tmp, json, 'utf-8');
    await fsp.rename(tmp, UI_STATE_PATH);
  }).catch((err) => {
    console.error('[ui-state] async flush failed:', err.message);
    _uiStateDirty = true;
  });
  return _uiStateWriteChain;
}

// For exit paths only — process.on('exit') cannot await.
function flushUiStateSync() {
  if (!_uiStateDirty || !_uiStateCache) return;
  try {
    const dir = resolve(UI_STATE_PATH, '..');
    if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
    const tmp = UI_STATE_PATH + '.tmp';
    writeFileSync(tmp, JSON.stringify(_uiStateCache, null, 2) + '\n', 'utf-8');
    renameSync(tmp, UI_STATE_PATH);
    _uiStateDirty = false;
  } catch (err) {
    console.error('[ui-state] sync flush failed:', err.message);
  }
}

// ── Whiteboard store ──────────────────────────────────────────────
// The whiteboard (with base64 images) used to live inside ui-state.json,
// fattening it to multiple MB so every unrelated ui-state write re-stringified
// the board. It now persists to its own file with the same in-memory-cache +
// debounced async atomic write as ui-state. Every server-side consumer (REST
// endpoints, MCP tools, the WS state:sync handler) goes through
// loadWhiteboard()/saveWhiteboard(); loadWhiteboard() hands out the live object
// (mutate it and pass back), mirroring loadUiState()/saveUiState().
const WHITEBOARD_PATH = resolve(DATA_HOME, 'data', 'whiteboard.json');
let _whiteboardCache = null;
let _whiteboardDirty = false;
let _whiteboardFlushTimer = null;
let _whiteboardWriteChain = Promise.resolve();
const WHITEBOARD_FLUSH_MS = 1000;

function loadWhiteboard() {
  if (_whiteboardCache) return _whiteboardCache;
  try {
    _whiteboardCache = JSON.parse(readFileSync(WHITEBOARD_PATH, 'utf-8'));
  } catch {
    // No file yet — one-time migrate the board out of ui-state.json if present.
    const ui = loadUiState();
    const legacy = ui['neural-whiteboard'];
    if (legacy && Array.isArray(legacy.elements)) {
      _whiteboardCache = { elements: legacy.elements, nextZIndex: legacy.nextZIndex || 1 };
      _whiteboardDirty = true;
      flushWhiteboardSync();          // persist to whiteboard.json BEFORE dropping it from ui-state
      delete ui['neural-whiteboard'];
      saveUiState(ui);                // shrink ui-state.json (debounced)
      console.log('[whiteboard] migrated neural-whiteboard out of ui-state.json');
    } else {
      _whiteboardCache = { elements: [], nextZIndex: 1 };
    }
  }
  if (!Array.isArray(_whiteboardCache.elements)) _whiteboardCache.elements = [];
  if (!_whiteboardCache.nextZIndex) _whiteboardCache.nextZIndex = 1;
  return _whiteboardCache;
}

function saveWhiteboard(data) {
  _whiteboardCache = data;
  _whiteboardDirty = true;
  if (!_whiteboardFlushTimer) {
    _whiteboardFlushTimer = setTimeout(() => {
      _whiteboardFlushTimer = null;
      flushWhiteboardAsync();
    }, WHITEBOARD_FLUSH_MS);
    _whiteboardFlushTimer.unref?.();
  }
}

function flushWhiteboardAsync() {
  if (!_whiteboardDirty || !_whiteboardCache) return _whiteboardWriteChain;
  _whiteboardDirty = false;
  const json = JSON.stringify(_whiteboardCache) + '\n';
  _whiteboardWriteChain = _whiteboardWriteChain.then(async () => {
    const dir = resolve(WHITEBOARD_PATH, '..');
    if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
    const tmp = WHITEBOARD_PATH + '.tmp';
    await fsp.writeFile(tmp, json, 'utf-8');
    await fsp.rename(tmp, WHITEBOARD_PATH);
  }).catch((err) => {
    console.error('[whiteboard] async flush failed:', err.message);
    _whiteboardDirty = true;
  });
  return _whiteboardWriteChain;
}

// For exit paths only — process.on('exit') cannot await.
function flushWhiteboardSync() {
  if (!_whiteboardDirty || !_whiteboardCache) return;
  try {
    const dir = resolve(WHITEBOARD_PATH, '..');
    if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
    const tmp = WHITEBOARD_PATH + '.tmp';
    writeFileSync(tmp, JSON.stringify(_whiteboardCache) + '\n', 'utf-8');
    renameSync(tmp, WHITEBOARD_PATH);
    _whiteboardDirty = false;
  } catch (err) {
    console.error('[whiteboard] sync flush failed:', err.message);
  }
}

// Fat keys that historically lived inside ui-state.json. They now reside in
// the blob store (lib/ui-blob-store.js) — split:true maps are exploded into
// one row per entry. mergeUiState routes incoming writes from stale clients
// (open tabs from before the migration) into the store so the main file can
// never re-fatten.
const FAT_KEY_ROUTES = {
  'synabun-claude-panel-session-snapshots': { ns: 'claude-snapshots', split: true },
  'synabun-codex-panel-thread-snapshots':   { ns: 'codex-snapshots',  split: true },
  'synabun-ocp-session-snapshots':          { ns: 'ocp-snapshots',    split: true },
  'synabun-node-positions':                 { ns: 'kv', split: false },
  'synabun-node-positions-2d':              { ns: 'kv', split: false },
};
const BLOB_NS_ALLOWLIST = new Set(['claude-snapshots', 'codex-snapshots', 'ocp-snapshots', 'kv']);

function routeFatKeyToBlobStore(key, value) {
  const fat = FAT_KEY_ROUTES[key];
  if (!fat || value === null || value === undefined) return;
  // storage.js values arrive JSON-encoded as strings; tolerate both forms.
  if (fat.split) {
    const map = typeof value === 'string' ? JSON.parse(value) : value;
    if (map && typeof map === 'object' && !Array.isArray(map)) {
      for (const [id, entry] of Object.entries(map)) blobPut(fat.ns, id, entry);
    }
  } else {
    blobPut(fat.ns, key, value);
  }
}

// Shared merge logic for PATCH and POST (sendBeacon)
function mergeUiState(updates) {
  const current = loadUiState();
  for (const [key, value] of Object.entries(updates)) {
    if (key.startsWith('_')) continue; // protect metadata keys
    if (FAT_KEY_ROUTES[key]) {
      try { routeFatKeyToBlobStore(key, value); } catch (err) { console.warn(`[ui-blobs] shim for ${key} failed:`, err.message); }
      continue;
    }
    if (value === null) {
      delete current[key];
    } else {
      current[key] = value;
    }
  }
  saveUiState(current);
  return current;
}

// One-time idempotent migration: move fat keys out of ui-state.json into the
// blob store. Shrinks the file (and every boot GET) from multi-MB to ~30KB.
function migrateFatKeysToBlobStore() {
  const state = loadUiState();
  const fatKeys = Object.keys(FAT_KEY_ROUTES).filter(k => state[k] !== undefined);
  if (!fatKeys.length) return;
  const bak = resolve(DATA_HOME, 'data', 'ui-state.pre-blob-migration.bak.json');
  try { if (!existsSync(bak) && existsSync(UI_STATE_PATH)) copyFileSync(UI_STATE_PATH, bak); } catch {}
  for (const key of fatKeys) {
    try {
      routeFatKeyToBlobStore(key, state[key]);
      delete state[key];
      console.log(`[ui-blobs] migrated ${key} → ${FAT_KEY_ROUTES[key].ns}`);
    } catch (err) {
      console.warn(`[ui-blobs] migration of ${key} failed (kept in ui-state):`, err.message);
    }
  }
  saveUiState(state);
}

try {
  initBlobStore(resolve(DATA_HOME, 'data', 'ui-blobs.db'));
  migrateFatKeysToBlobStore();
} catch (err) {
  console.warn('[ui-blobs] init failed:', err.message);
}

// GET /api/ui-state — Full state dump (boot hydration)
app.get('/api/ui-state', (req, res) => {
  try {
    res.json(loadUiState());
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// PATCH /api/ui-state — Partial key update (debounced writes from client)
app.patch('/api/ui-state', (req, res) => {
  try {
    if (!req.body || typeof req.body !== 'object') {
      return res.status(400).json({ error: 'Body must be a JSON object' });
    }
    mergeUiState(req.body);
    res.json({ ok: true });
  } catch (err) {
    console.error('PATCH /api/ui-state error:', err.message);
    res.status(500).json({ error: err.message });
  }
});

// POST /api/ui-state — Same as PATCH (needed for navigator.sendBeacon on page unload)
app.post('/api/ui-state', (req, res) => {
  try {
    if (!req.body || typeof req.body !== 'object') {
      return res.status(400).json({ error: 'Body must be a JSON object' });
    }
    mergeUiState(req.body);
    res.json({ ok: true });
  } catch (err) {
    console.error('POST /api/ui-state error:', err.message);
    res.status(500).json({ error: err.message });
  }
});

// ── UI blob store — per-entry storage for fat keys (transcript snapshots,
// node positions). PUT writes only the changed entry instead of the whole map.
function _blobNs(req, res) {
  const ns = req.params.ns;
  if (!BLOB_NS_ALLOWLIST.has(ns)) { res.status(400).json({ error: `unknown namespace: ${ns}` }); return null; }
  return ns;
}

app.get('/api/ui-blobs/:ns', (req, res) => {
  const ns = _blobNs(req, res);
  if (!ns) return;
  try { res.json(blobGetNamespace(ns)); }
  catch (err) { res.status(500).json({ error: err.message }); }
});

app.get('/api/ui-blobs/:ns/:id', (req, res) => {
  const ns = _blobNs(req, res);
  if (!ns) return;
  try {
    const value = blobGet(ns, req.params.id);
    if (value === null) return res.status(404).json({ error: 'not found' });
    res.json(value);
  } catch (err) { res.status(500).json({ error: err.message }); }
});

function _blobPutHandler(req, res) {
  const ns = _blobNs(req, res);
  if (!ns) return;
  try {
    blobPut(ns, req.params.id, req.body);
    const maxEntries = parseInt(req.query.maxEntries, 10) || 0;
    const maxChars = parseInt(req.query.maxChars, 10) || 0;
    let evicted = [];
    if (maxEntries || maxChars) evicted = blobPrune(ns, { maxEntries, maxTotalChars: maxChars });
    res.json({ ok: true, evicted });
  } catch (err) { res.status(500).json({ error: err.message }); }
}
app.put('/api/ui-blobs/:ns/:id', _blobPutHandler);
// POST alias — sendBeacon can only POST
app.post('/api/ui-blobs/:ns/:id', _blobPutHandler);

app.delete('/api/ui-blobs/:ns/:id', (req, res) => {
  const ns = _blobNs(req, res);
  if (!ns) return;
  try { blobDelete(ns, req.params.id); res.json({ ok: true }); }
  catch (err) { res.status(500).json({ error: err.message }); }
});


// ═══════════════════════════════════════════
// IMAGE GALLERY API
// ═══════════════════════════════════════════

// GET /api/images — list all images with metadata
app.get('/api/images', (req, res) => {
  try {
    const favs = new Set(loadImageFavorites());
    const files = readdirSync(IMAGES_DIR)
      .filter(f => /\.(png|jpe?g|gif|webp|bmp|svg)$/i.test(f))
      .map(f => {
        const fp = join(IMAGES_DIR, f);
        const st = statSync(fp);
        let type = 'other';
        if (f.startsWith('screenshot-')) type = 'screenshot';
        else if (f.startsWith('synabun-img-')) type = 'attachment';
        else if (f.startsWith('synabun-wbimg-')) type = 'whiteboard';
        else if (f.startsWith('synabun-paste-')) type = 'paste';
        return {
          filename: f,
          type,
          size: st.size,
          path: fp,
          createdAt: st.birthtimeMs || st.ctimeMs,
          modifiedAt: st.mtimeMs,
          favorite: favs.has(f),
        };
      })
      .sort((a, b) => b.modifiedAt - a.modifiedAt);
    res.json({ images: files, total: files.length });
  } catch (err) {
    console.error('GET /api/images error:', err.message);
    res.status(500).json({ error: err.message });
  }
});

// GET /api/images/file/:filename — serve an image file
app.get('/api/images/file/:filename', (req, res) => {
  const filename = basename(req.params.filename);
  const fp = join(IMAGES_DIR, filename);
  if (!existsSync(fp)) return res.status(404).json({ error: 'Not found' });
  res.sendFile(fp);
});

// POST /api/images/favorite — toggle favorite status
app.post('/api/images/favorite', (req, res) => {
  try {
    const { filename, favorite } = req.body;
    if (!filename) return res.status(400).json({ error: 'filename required' });
    const favs = loadImageFavorites();
    const idx = favs.indexOf(filename);
    if (favorite && idx === -1) favs.push(filename);
    else if (!favorite && idx !== -1) favs.splice(idx, 1);
    saveImageFavorites(favs);
    res.json({ ok: true, favorite: favs.includes(filename) });
  } catch (err) {
    console.error('POST /api/images/favorite error:', err.message);
    res.status(500).json({ error: err.message });
  }
});

// DELETE /api/images/:filename — delete an image
app.delete('/api/images/:filename', (req, res) => {
  try {
    const filename = basename(req.params.filename);
    const fp = join(IMAGES_DIR, filename);
    if (!existsSync(fp)) return res.status(404).json({ error: 'Not found' });
    unlinkSync(fp);
    // Remove from favorites too
    const favs = loadImageFavorites().filter(f => f !== filename);
    saveImageFavorites(favs);
    res.json({ ok: true });
  } catch (err) {
    console.error('DELETE /api/images error:', err.message);
    res.status(500).json({ error: err.message });
  }
});


// ═══════════════════════════════════════════
// YOUTUBE TRAILER PIPELINE — sourcing (IGDB+Steam), download (Steam mp4 / yt-dlp),
// config, test, analytics, OAuth. Browser upload/publish is handled by the
// youtube_* MCP tools driving Studio directly; these endpoints back the
// non-browser parts (the MCP server calls them via neural-interface.ts wrappers).
// ═══════════════════════════════════════════

const YT_CONFIG_PATH = resolve(DATA_HOME, 'data', 'youtube-config.json');
const YT_DOWNLOAD_DIR = resolve(DATA_HOME, 'data', 'youtube-downloads');
const YT_SECRET_KEYS = [
  'YT_OAUTH_CLIENT_ID', 'YT_OAUTH_CLIENT_SECRET', 'YT_REFRESH_TOKEN', 'YT_API_KEY',
  'YT_CHANNEL_ID', 'IGDB_CLIENT_ID', 'IGDB_CLIENT_SECRET', 'STEAM_API_KEY',
];

function ytReadSecrets() {
  const vars = parseEnvFile(ENV_PATH);
  const out = {};
  for (const k of YT_SECRET_KEYS) out[k] = vars[k] || process.env[k] || '';
  return out;
}

function ytDefaultPipelineConfig() {
  return {
    uploadTransport: 'browser',        // 'browser' (default, avoids API private-lock) | 'api'
    channelId: '',
    sources: { genres: [], platforms: [], minHype: 0, lookbackDays: 60, upcoming: true },
    download: { quality: 'bestvideo[height<=1080]+bestaudio/best[height<=1080]', outputDir: YT_DOWNLOAD_DIR, useCookies: false, cookiesBrowser: 'chrome', preferSteam: true },
    cadence: { postsPerDay: 1, scheduleWindow: ['16:00', '20:00'] },
  };
}

function ytReadPipelineConfig() {
  try {
    if (existsSync(YT_CONFIG_PATH)) return { ...ytDefaultPipelineConfig(), ...JSON.parse(readFileSync(YT_CONFIG_PATH, 'utf-8')) };
  } catch { /* fall through to defaults */ }
  return ytDefaultPipelineConfig();
}

function ytWritePipelineConfig(cfg) {
  mkdirSync(dirname(YT_CONFIG_PATH), { recursive: true });
  writeFileSync(YT_CONFIG_PATH, JSON.stringify(cfg, null, 2), 'utf-8');
}

function ytSanitizeFilename(name) {
  return String(name || 'trailer').replace(/[^a-z0-9._-]+/gi, '_').slice(0, 80) || 'trailer';
}

// ── IGDB (authenticated via a Twitch app-access token, cached until expiry) ──
let _igdbToken = null;
let _igdbTokenExp = 0;

async function igdbToken() {
  const s = ytReadSecrets();
  if (!s.IGDB_CLIENT_ID || !s.IGDB_CLIENT_SECRET) {
    throw new Error('IGDB not configured — set IGDB_CLIENT_ID + IGDB_CLIENT_SECRET in Settings → YouTube.');
  }
  if (_igdbToken && Date.now() < _igdbTokenExp - 60_000) return _igdbToken;
  const url = `https://id.twitch.tv/oauth2/token?client_id=${encodeURIComponent(s.IGDB_CLIENT_ID)}&client_secret=${encodeURIComponent(s.IGDB_CLIENT_SECRET)}&grant_type=client_credentials`;
  const r = await fetch(url, { method: 'POST' });
  const j = await r.json().catch(() => ({}));
  if (!r.ok || !j.access_token) throw new Error(`IGDB token failed: ${j.message || r.status}`);
  _igdbToken = j.access_token;
  _igdbTokenExp = Date.now() + (j.expires_in || 3600) * 1000;
  return _igdbToken;
}

async function igdbQuery(endpoint, body) {
  const s = ytReadSecrets();
  const token = await igdbToken();
  const r = await fetch(`https://api.igdb.com/v4/${endpoint}`, {
    method: 'POST',
    headers: { 'Client-ID': s.IGDB_CLIENT_ID, 'Authorization': `Bearer ${token}`, 'Accept': 'application/json' },
    body,
  });
  const txt = await r.text();
  if (!r.ok) throw new Error(`IGDB ${endpoint} ${r.status}: ${txt.slice(0, 200)}`);
  const trimmed = txt.trim();
  if (!trimmed) return []; // 200 with an empty body = legitimately no results
  try { return JSON.parse(trimmed); } catch {
    // Don't swallow a malformed body as "no results" — surface it as a real error.
    console.error(`IGDB ${endpoint} returned non-JSON (${trimmed.length}b): ${trimmed.slice(0, 120)}`);
    throw new Error(`IGDB ${endpoint} returned a non-JSON response — likely an API or token problem.`);
  }
}

// ── Steam Storefront appdetails → official publisher trailers (direct mp4) ──
async function steamMovies(appid) {
  try {
    const r = await fetch(`https://store.steampowered.com/api/appdetails?appids=${appid}&filters=movies`);
    const j = await r.json().catch(() => ({}));
    const entry = j && j[appid];
    if (!entry || !entry.success || !entry.data || !Array.isArray(entry.data.movies)) return [];
    const https = (u) => (u ? String(u).replace(/^http:/, 'https:') : null);
    return entry.data.movies.map((m) => ({
      id: m.id,
      name: m.name,
      thumbnail: https(m.thumbnail),
      mp4: https(m.mp4 && (m.mp4.max || m.mp4['480'])),
      webm: https(m.webm && (m.webm.max || m.webm['480'])),
    }));
  } catch { return []; }
}

// IGDB external_games category 1 == Steam; uid is the Steam appid.
function steamAppidFromExternal(externals) {
  if (!Array.isArray(externals)) return null;
  const steam = externals.find((e) => e && e.category === 1 && e.uid);
  if (!steam) return null;
  const n = parseInt(steam.uid, 10);
  return Number.isFinite(n) ? n : null;
}

function ytDaysAgoIso(days, fallback = 7) {
  const n = parseInt(days, 10);
  const safeDays = Number.isFinite(n) ? Math.min(Math.max(n, 1), 365) : fallback;
  return new Date(Date.now() - safeDays * 86400_000).toISOString();
}

function ytDecodeText(value) {
  return String(value || '')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/\s+/g, ' ')
    .trim();
}

function ytTrailerSearchQuery(query) {
  const q = String(query || '').trim();
  if (!q) return 'official game trailer video game';
  if (/\b(game|gaming|video game|pc|steam|xbox|playstation|ps5|ps4|nintendo|switch)\b/i.test(q)) return q;
  return `${q} video game`;
}

function inferGameFromYoutubeTitle(title) {
  let name = ytDecodeText(title)
    .replace(/\s*\[[^\]]+\]/g, ' ')
    .replace(/\s*\([^)]*(?:ps5|ps4|xbox|switch|nintendo|pc|steam|official|trailer|gameplay)[^)]*\)/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  const marker = name.search(/\b(official\s+)?(announce(?:ment)?|reveal|launch|release date|gameplay|story|cinematic|teaser|overview|accolades|dlc|update|early access)?\s*trailer\b/i);
  if (marker > 0) name = name.slice(0, marker);
  name = name.split(/\s+[-|:]\s+/)[0] || name;
  name = name
    .replace(/\b(official|trailer|gameplay|reveal|launch|announcement|announce|teaser|ps5|ps4|xbox|series x|series s|nintendo switch|switch|pc|steam|games)\b/gi, ' ')
    .replace(/[-:|]+$/g, '')
    .replace(/\s+/g, ' ')
    .trim();
  return name || ytDecodeText(title).slice(0, 80);
}

const YT_TRAILER_KEEP_RE = /\b(official\s+)?(trailer|launch trailer|release date trailer|gameplay trailer|story trailer|announcement trailer|announce trailer|reveal trailer|teaser trailer|cinematic trailer|overview trailer|accolades trailer|dlc trailer|update trailer|early access trailer)\b/i;
const YT_TRAILER_REJECT_RE = /\b(reaction|reacts|breakdown|analysis|review|walkthrough|let'?s play|longplay|playthrough|compilation|all trailers|top\s*\d+|fan[- ]?made|soundtrack|music video|ost|livestream|live stream|podcast|interview|behind the scenes|movie trailer|film trailer|tv spot)\b/i;

async function youtubeRecentTrailers({ query = '', limit = 10, lookbackDays = 7 } = {}) {
  const s = ytReadSecrets();
  if (!s.YT_API_KEY) throw new Error('YouTube API key not configured — set YT_API_KEY in Settings → YouTube.');

  const lim = Math.min(Math.max(parseInt(limit, 10) || 10, 1), 50);
  const url = new URL('https://www.googleapis.com/youtube/v3/search');
  url.searchParams.set('part', 'snippet');
  url.searchParams.set('type', 'video');
  url.searchParams.set('order', 'date');
  url.searchParams.set('maxResults', String(Math.min(Math.max(lim * 2, 10), 50)));
  url.searchParams.set('publishedAfter', ytDaysAgoIso(lookbackDays, 7));
  url.searchParams.set('q', ytTrailerSearchQuery(query));
  url.searchParams.set('videoCategoryId', '20');
  url.searchParams.set('relevanceLanguage', 'en');
  url.searchParams.set('safeSearch', 'none');
  url.searchParams.set('key', s.YT_API_KEY);

  const r = await fetch(url);
  const j = await r.json().catch(() => ({}));
  if (!r.ok) {
    const msg = j?.error?.message || j?.message || r.status;
    throw new Error(`YouTube search failed: ${msg}`);
  }

  const candidates = [];
  for (const item of j.items || []) {
    const videoId = item?.id?.videoId;
    const snip = item?.snippet || {};
    const title = ytDecodeText(snip.title);
    if (!videoId || !title) continue;
    if (!YT_TRAILER_KEEP_RE.test(title)) continue;
    if (YT_TRAILER_REJECT_RE.test(title)) continue;
    const publishedAt = snip.publishedAt || null;
    const thumbnail = snip.thumbnails?.maxres?.url || snip.thumbnails?.high?.url || snip.thumbnails?.medium?.url || null;
    candidates.push({
      source: 'youtube',
      game: inferGameFromYoutubeTitle(title),
      igdbId: null,
      appid: null,
      steamMovies: [],
      ytTrailerIds: [videoId],
      releaseDate: publishedAt ? String(publishedAt).slice(0, 10) : null,
      trailerPublishedAt: publishedAt,
      trailerTitle: title,
      channelTitle: ytDecodeText(snip.channelTitle),
      summary: ytDecodeText(snip.description) || null,
      cover: thumbnail,
      url: `https://www.youtube.com/watch?v=${videoId}`,
    });
    if (candidates.length >= lim) break;
  }
  return candidates;
}

// POST /api/sources/discover — YouTube/IGDB/Steam trailer discovery.
app.post('/api/sources/discover', async (req, res) => {
  try {
    const { source = 'auto', query = '', limit = 10, filters = {} } = req.body || {};
    const lim = Math.min(Math.max(parseInt(limit, 10) || 10, 1), 50);

    // YouTube direct search: newest published trailer videos first.
    if (source === 'youtube') {
      const candidates = await youtubeRecentTrailers({
        query,
        limit: lim,
        lookbackDays: filters.lookbackDays ?? 7,
      });
      return res.json({ ok: true, candidates });
    }

    // Steam-only: caller supplies explicit appids.
    if (source === 'steam') {
      const appids = Array.isArray(req.body?.appids) ? req.body.appids : [];
      const candidates = [];
      for (const appid of appids.slice(0, lim)) {
        candidates.push({ source: 'steam', game: String(appid), appid, steamMovies: await steamMovies(appid), ytTrailerIds: [] });
      }
      return res.json({ ok: true, candidates });
    }

    // IGDB discovery ('igdb' = metadata only, 'auto' = also resolve Steam mp4s).
    const cfg = ytReadPipelineConfig();
    const lookbackDays = (filters.lookbackDays ?? cfg.sources?.lookbackDays) || 60;
    const nowSec = Math.floor(Date.now() / 1000);
    const sinceSec = nowSec - lookbackDays * 86400;
    const aheadSec = nowSec + 120 * 86400;
    const fields = 'fields name,summary,first_release_date,genres.name,videos.video_id,videos.name,external_games.category,external_games.uid,cover.image_id,hypes;';

    let bodyStr;
    if (query && query.trim()) {
      bodyStr = `search "${query.replace(/"/g, '')}"; ${fields} where videos != null; limit ${lim};`;
    } else {
      bodyStr = `${fields} where first_release_date >= ${sinceSec} & first_release_date <= ${aheadSec} & videos != null & category = 0; sort hypes desc; limit ${lim};`;
    }

    const games = await igdbQuery('games', bodyStr);
    const candidates = [];
    for (const g of games || []) {
      const appid = steamAppidFromExternal(g.external_games);
      const ytTrailerIds = Array.isArray(g.videos) ? g.videos.map((v) => v.video_id).filter(Boolean) : [];
      const movies = appid && source === 'auto' ? await steamMovies(appid) : [];
      candidates.push({
        source: 'igdb',
        game: g.name,
        igdbId: g.id,
        appid: appid || null,
        steamMovies: movies,
        ytTrailerIds,
        releaseDate: g.first_release_date ? new Date(g.first_release_date * 1000).toISOString().slice(0, 10) : null,
        genres: Array.isArray(g.genres) ? g.genres.map((x) => x.name) : [],
        summary: g.summary || null,
        cover: g.cover?.image_id ? `https://images.igdb.com/igdb/image/upload/t_cover_big/${g.cover.image_id}.jpg` : null,
      });
    }
    if (candidates.length === 0) {
      // IGDB succeeded (a token/credential failure would have thrown above) but
      // matched nothing — say so, so an empty pool isn't mistaken for a broken token.
      return res.json({ ok: true, candidates: [], diagnostic: `IGDB reachable but returned 0 games for the ${lookbackDays}-day window${query && query.trim() ? ` matching "${query}"` : ''}. Broaden lookbackDays/query, or use source:youtube.` });
    }
    res.json({ ok: true, candidates });
  } catch (err) {
    console.error('POST /api/sources/discover error:', err.message);
    res.status(500).json({ error: err.message });
  }
});

// Resolve a yt-dlp invocation: explicit path → PATH binary → common install
// dirs (a GUI-launched server may not inherit the user's full PATH) → python module.
function resolveYtDlp() {
  const envPath = process.env.YTDLP_PATH;
  if (envPath && existsSync(envPath)) return { cmd: envPath, args: [] };
  try { execSync(process.platform === 'win32' ? 'where yt-dlp' : 'command -v yt-dlp', { stdio: 'ignore' }); return { cmd: 'yt-dlp', args: [] }; } catch { /* not on PATH */ }
  const home = os.homedir();
  for (const p of [join(home, '.local/bin/yt-dlp'), '/opt/homebrew/bin/yt-dlp', '/usr/local/bin/yt-dlp']) {
    if (existsSync(p)) return { cmd: p, args: [] };
  }
  try { execSync(process.platform === 'win32' ? 'where python3' : 'command -v python3', { stdio: 'ignore' }); return { cmd: 'python3', args: ['-m', 'yt_dlp'] }; } catch { /* no python */ }
  return null;
}

// Resolve an ffmpeg binary for yt-dlp's --ffmpeg-location (needed to merge the
// separate hi-res video+audio streams). Same PATH-independence as resolveYtDlp.
function resolveFfmpeg() {
  const envPath = process.env.FFMPEG_PATH;
  if (envPath && existsSync(envPath)) return envPath;
  const home = os.homedir();
  for (const p of ['/opt/homebrew/bin/ffmpeg', '/usr/local/bin/ffmpeg', join(home, '.local/bin/ffmpeg')]) {
    if (existsSync(p)) return p;
  }
  try {
    const out = execSync(process.platform === 'win32' ? 'where ffmpeg' : 'command -v ffmpeg', { encoding: 'utf-8' }).trim().split(/\r?\n/)[0];
    if (out && existsSync(out)) return out;
  } catch { /* not found */ }
  return null;
}

// POST /api/youtube/download — Steam direct-mp4 (preferred) or yt-dlp fallback.
app.post('/api/youtube/download', async (req, res) => {
  try {
    const cfg = ytReadPipelineConfig();
    const outDir = req.body?.outputDir || cfg.download?.outputDir || YT_DOWNLOAD_DIR;
    mkdirSync(outDir, { recursive: true });
    const baseName = ytSanitizeFilename(req.body?.filename || req.body?.ytId || (req.body?.appid ? `steam_${req.body.appid}` : 'trailer'));

    // 1) Steam direct mp4 — plain stream-to-disk, no yt-dlp/ffmpeg required.
    const steamUrl = req.body?.steamMp4Url;
    if (steamUrl) {
      const filePath = join(outDir, `${baseName}.mp4`);
      const r = await fetch(steamUrl);
      if (!r.ok || !r.body) throw new Error(`Steam mp4 fetch failed: HTTP ${r.status}`);
      await new Promise((ok, fail) => {
        Readable.fromWeb(r.body).pipe(createWriteStream(filePath)).on('finish', ok).on('error', fail);
      });
      return res.json({ ok: true, filePath, bytes: statSync(filePath).size, source: 'steam' });
    }

    // 2) yt-dlp fallback for an official YouTube trailer.
    const ytId = req.body?.ytId;
    const url = req.body?.url || (ytId ? `https://www.youtube.com/watch?v=${ytId}` : null);
    if (!url) return res.status(400).json({ error: 'Provide steamMp4Url, ytId, or url.' });

    const yd = resolveYtDlp();
    if (!yd) return res.status(501).json({ error: 'yt-dlp not found. Install it (brew install yt-dlp / pip install yt-dlp) or set YTDLP_PATH. ffmpeg is also required for merging.' });

    const quality = req.body?.quality || cfg.download?.quality || 'bestvideo[height<=1080]+bestaudio/best[height<=1080]';
    // yt-dlp 2026.06+ requires a JS runtime (node/deno) to extract YouTube — pass
    // --js-runtimes node so a fresh box doesn't fail extraction silently.
    const baseArgs = [...yd.args, '-f', quality, '--merge-output-format', 'mp4', '--no-playlist', '--js-runtimes', 'node', '-o', join(outDir, `${baseName}.%(ext)s`)];
    const ffmpeg = resolveFfmpeg();
    if (ffmpeg) baseArgs.push('--ffmpeg-location', dirname(ffmpeg)); // the flag wants the directory, not the binary path
    // Allow the cookie fallback by default; a caller can hard-disable with useCookies:false.
    const cookiesAllowed = req.body?.useCookies !== false;
    const cookieBrowser = cfg.download?.cookiesBrowser || 'chrome';

    // A GUI-launched NI may not inherit the user's shell PATH, so yt-dlp can't find
    // node/deno/ffmpeg. Prepend the running node's dir + the common Homebrew/local bins.
    const extraPath = [dirname(process.execPath), '/opt/homebrew/bin', '/usr/local/bin', join(os.homedir(), '.local/bin')].join(delimiter);
    const childEnv = { ...process.env, PATH: `${extraPath}${delimiter}${process.env.PATH || ''}` };

    const runYtDlp = (finalArgs) => new Promise((done) => {
      const child = spawn(yd.cmd, finalArgs, { windowsHide: true, env: childEnv });
      let stderr = '';
      child.stderr.on('data', (d) => { stderr += d.toString(); });
      child.on('error', (e) => done({ code: -1, stderr: `spawn failed: ${e.message}` }));
      child.on('close', (code) => done({ code, stderr }));
    });

    // Cookieless first (fast, no browser profile-lock risk); fall back to
    // browser cookies on auth errors OR 403/bot-detection failures.
    let run = await runYtDlp([...baseArgs, url]);
    const needsAuth = run.code !== 0 && /sign in|confirm your age|age-restrict|consent|login|private video|members-only|account|403|forbidden|bot|proof\s+of\s+humanity/i.test(run.stderr);
    if ((needsAuth || run.code !== 0) && cookiesAllowed) run = await runYtDlp([...baseArgs, '--cookies-from-browser', cookieBrowser, url]);
    if (run.code !== 0) return res.status(500).json({ error: `yt-dlp exited ${run.code}: ${run.stderr.slice(-400)}` });

    const produced = readdirSync(outDir).filter((f) => f.startsWith(`${baseName}.`)).map((f) => join(outDir, f));
    const mp4 = produced.find((f) => f.endsWith('.mp4')) || produced[0];
    if (!mp4) return res.status(500).json({ error: 'yt-dlp finished but no output file was found.' });
    res.json({ ok: true, filePath: mp4, bytes: statSync(mp4).size, source: 'yt-dlp' });
  } catch (err) {
    console.error('POST /api/youtube/download error:', err.message);
    if (!res.headersSent) res.status(500).json({ error: err.message });
  }
});

// GET /api/youtube/config — masked secrets + which credential sets are complete + pipeline config.
app.get('/api/youtube/config', (req, res) => {
  try {
    const secrets = ytReadSecrets();
    const masked = {};
    for (const k of YT_SECRET_KEYS) masked[k] = secrets[k] ? (k === 'YT_CHANNEL_ID' ? secrets[k] : maskKey(secrets[k])) : '';
    res.json({
      ok: true,
      secrets: masked,
      configured: {
        youtube: !!(secrets.YT_OAUTH_CLIENT_ID && secrets.YT_OAUTH_CLIENT_SECRET && secrets.YT_REFRESH_TOKEN),
        igdb: !!(secrets.IGDB_CLIENT_ID && secrets.IGDB_CLIENT_SECRET),
        steam: !!secrets.STEAM_API_KEY,
      },
      pipeline: ytReadPipelineConfig(),
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// PUT /api/youtube/config — secrets → .env, pipeline → json. Masked values are ignored (treated as unchanged).
app.put('/api/youtube/config', (req, res) => {
  try {
    const body = req.body || {};
    if (body.secrets && typeof body.secrets === 'object') {
      const vars = parseEnvFile(ENV_PATH);
      for (const k of YT_SECRET_KEYS) {
        const v = body.secrets[k];
        if (v === undefined) continue;
        if (typeof v === 'string' && v.includes('*')) continue; // masked → unchanged
        if (v === '') { delete vars[k]; delete process.env[k]; continue; }
        vars[k] = v;
        process.env[k] = v;
      }
      writeEnvFile(ENV_PATH, vars);
      _igdbToken = null; _ytAccess = null; // force token refresh after a credential change
    }
    if (body.pipeline && typeof body.pipeline === 'object') ytWritePipelineConfig(body.pipeline);
    res.json({ ok: true });
  } catch (err) {
    console.error('PUT /api/youtube/config error:', err.message);
    res.status(500).json({ error: err.message });
  }
});

// POST /api/youtube/test — connectivity check per credential set.
app.post('/api/youtube/test', async (req, res) => {
  const target = (req.body?.target || 'all').toLowerCase();
  const results = {};
  if (target === 'igdb' || target === 'all') {
    try { await igdbToken(); const g = await igdbQuery('games', 'fields name; limit 1;'); results.igdb = { ok: Array.isArray(g) }; }
    catch (e) { results.igdb = { ok: false, error: e.message }; }
  }
  if (target === 'steam' || target === 'all') {
    try { const m = await steamMovies(620); results.steam = { ok: true, sampleMovies: m.length }; }
    catch (e) { results.steam = { ok: false, error: e.message }; }
  }
  if (target === 'youtube' || target === 'all') {
    try { await ytAccessToken(); results.youtube = { ok: true }; }
    catch (e) { results.youtube = { ok: false, error: e.message }; }
  }
  res.json({ ok: true, results });
});

// ── YouTube OAuth (refresh-token → short-lived access-token, cached) ──
let _ytAccess = null;
let _ytAccessExp = 0;

async function ytAccessToken() {
  const s = ytReadSecrets();
  if (!s.YT_OAUTH_CLIENT_ID || !s.YT_OAUTH_CLIENT_SECRET || !s.YT_REFRESH_TOKEN) {
    throw new Error('YouTube API not configured — OAuth client id/secret + refresh token required (use Authorize in Settings → YouTube).');
  }
  if (_ytAccess && Date.now() < _ytAccessExp - 60_000) return _ytAccess;
  const body = new URLSearchParams({
    client_id: s.YT_OAUTH_CLIENT_ID, client_secret: s.YT_OAUTH_CLIENT_SECRET,
    refresh_token: s.YT_REFRESH_TOKEN, grant_type: 'refresh_token',
  });
  const r = await fetch('https://oauth2.googleapis.com/token', { method: 'POST', headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, body });
  const j = await r.json().catch(() => ({}));
  if (!r.ok || !j.access_token) throw new Error(`YouTube token refresh failed: ${j.error_description || j.error || r.status}`);
  _ytAccess = j.access_token;
  _ytAccessExp = Date.now() + (j.expires_in || 3600) * 1000;
  return _ytAccess;
}

// POST /api/youtube/analytics — read-only reports via the YouTube Analytics API.
app.post('/api/youtube/analytics', async (req, res) => {
  try {
    const { videoId, channelId, metrics, startDate, endDate } = req.body || {};
    const token = await ytAccessToken();
    const s = ytReadSecrets();
    const ch = channelId || s.YT_CHANNEL_ID;
    const end = endDate || new Date().toISOString().slice(0, 10);
    const start = startDate || new Date(Date.now() - 28 * 86400 * 1000).toISOString().slice(0, 10);
    const mets = (Array.isArray(metrics) && metrics.length ? metrics : ['views', 'estimatedMinutesWatched', 'likes', 'subscribersGained']).join(',');
    const params = new URLSearchParams({ ids: ch ? `channel==${ch}` : 'channel==MINE', startDate: start, endDate: end, metrics: mets });
    if (videoId) { params.set('filters', `video==${videoId}`); params.set('dimensions', 'video'); }
    const r = await fetch(`https://youtubeanalytics.googleapis.com/v2/reports?${params}`, { headers: { Authorization: `Bearer ${token}` } });
    const j = await r.json().catch(() => ({}));
    if (!r.ok) throw new Error(j.error?.message || `Analytics HTTP ${r.status}`);
    res.json({ ok: true, report: j });
  } catch (err) {
    console.error('POST /api/youtube/analytics error:', err.message);
    res.status(500).json({ error: err.message });
  }
});

// GET /api/youtube/oauth/start — returns the Google consent URL for the UI to open.
app.get('/api/youtube/oauth/start', (req, res) => {
  try {
    const s = ytReadSecrets();
    if (!s.YT_OAUTH_CLIENT_ID) return res.status(400).json({ error: 'Set YT_OAUTH_CLIENT_ID first.' });
    const redirect = `http://localhost:${PORT}/api/youtube/oauth/callback`;
    const url = 'https://accounts.google.com/o/oauth2/v2/auth?' + new URLSearchParams({
      client_id: s.YT_OAUTH_CLIENT_ID,
      redirect_uri: redirect,
      response_type: 'code',
      access_type: 'offline',
      prompt: 'consent',
      scope: ['https://www.googleapis.com/auth/youtube', 'https://www.googleapis.com/auth/youtube.upload', 'https://www.googleapis.com/auth/yt-analytics.readonly'].join(' '),
    });
    res.json({ ok: true, url, redirect });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// GET /api/youtube/oauth/callback — exchange the code for a refresh token, save to .env.
app.get('/api/youtube/oauth/callback', async (req, res) => {
  try {
    const code = req.query.code;
    if (!code) return res.status(400).send('Missing authorization code.');
    const s = ytReadSecrets();
    const redirect = `http://localhost:${PORT}/api/youtube/oauth/callback`;
    const body = new URLSearchParams({ code, client_id: s.YT_OAUTH_CLIENT_ID, client_secret: s.YT_OAUTH_CLIENT_SECRET, redirect_uri: redirect, grant_type: 'authorization_code' });
    const r = await fetch('https://oauth2.googleapis.com/token', { method: 'POST', headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, body });
    const j = await r.json().catch(() => ({}));
    if (!r.ok || !j.refresh_token) {
      return res.status(500).send(`<h3>Authorization failed</h3><pre>${j.error_description || j.error || 'No refresh_token returned. Revoke the prior grant at myaccount.google.com and retry.'}</pre>`);
    }
    const vars = parseEnvFile(ENV_PATH);
    vars.YT_REFRESH_TOKEN = j.refresh_token;
    process.env.YT_REFRESH_TOKEN = j.refresh_token;
    writeEnvFile(ENV_PATH, vars);
    _ytAccess = null;
    res.send('<h3>YouTube connected ✓</h3><p>You can close this tab and return to SynaBun.</p>');
  } catch (err) { res.status(500).send(`Error: ${err.message}`); }
});


// ═══════════════════════════════════════════
// WHITEBOARD API — Claude MCP integration
// ═══════════════════════════════════════════

// Layout engine for whiteboard auto-positioning
function applyWhiteboardLayout(elements, layout, vp) {
  const gap = 40;
  const pad = 60;
  const xOff = vp.xOffset || 0;
  const yOff = vp.yOffset || 0;
  const n = elements.length;
  if (!n) return;

  if (layout === 'center') {
    const totalH = elements.reduce((s, el) => s + (el.height || 100), 0) + gap * (n - 1);
    let y = yOff + (vp.height - totalH) / 2;
    for (const el of elements) {
      el.x = Math.round(xOff + (vp.width - (el.width || 200)) / 2);
      el.y = Math.round(y);
      y += (el.height || 100) + gap;
    }
  } else if (layout === 'row') {
    const totalW = elements.reduce((s, el) => s + (el.width || 200), 0) + gap * (n - 1);
    let x = xOff + (vp.width - totalW) / 2;
    for (const el of elements) {
      el.x = Math.round(x);
      el.y = Math.round(yOff + (vp.height - (el.height || 100)) / 2);
      x += (el.width || 200) + gap;
    }
  } else if (layout === 'column') {
    const totalH = elements.reduce((s, el) => s + (el.height || 100), 0) + gap * (n - 1);
    let y = yOff + (vp.height - totalH) / 2;
    for (const el of elements) {
      el.x = Math.round(xOff + (vp.width - (el.width || 200)) / 2);
      el.y = Math.round(y);
      y += (el.height || 100) + gap;
    }
  } else if (layout === 'grid') {
    const cols = n <= 2 ? 2 : n <= 6 ? 3 : 4;
    const rows = Math.ceil(n / cols);
    const cellW = (vp.width - pad * 2 - gap * (cols - 1)) / cols;
    const cellH = (vp.height - pad * 2 - gap * (rows - 1)) / rows;
    elements.forEach((el, i) => {
      const col = i % cols;
      const row = Math.floor(i / cols);
      el.x = Math.round(xOff + pad + col * (cellW + gap) + (cellW - (el.width || 200)) / 2);
      el.y = Math.round(yOff + pad + row * (cellH + gap) + (cellH - (el.height || 100)) / 2);
    });
  }
}

// GET /api/whiteboard — Read current whiteboard state from its dedicated store
app.get('/api/whiteboard', (req, res) => {
  try {
    const wb = loadWhiteboard();
    res.json({ ok: true, elements: wb.elements, nextZIndex: wb.nextZIndex || 1, viewport: whiteboardViewport });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// PUT /api/whiteboard — Bulk replace. Client persistence fallback for when the
// whiteboard WS is down; the WS state:sync path is preferred when connected.
app.put('/api/whiteboard', (req, res) => {
  try {
    const { elements, nextZIndex } = req.body || {};
    if (!Array.isArray(elements)) return res.status(400).json({ error: 'elements must be an array' });
    saveWhiteboard({ elements, nextZIndex: nextZIndex || 1 });
    res.json({ ok: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// POST /api/whiteboard/elements — Add one or more elements
app.post('/api/whiteboard/elements', (req, res) => {
  try {
    const { elements, coordMode, layout } = req.body;
    if (!Array.isArray(elements) || elements.length === 0) {
      return res.status(400).json({ error: 'elements must be a non-empty array' });
    }

    // Auto-layout or percentage coordinate conversion
    if (layout && whiteboardViewport) {
      applyWhiteboardLayout(elements, layout, whiteboardViewport);
    } else if (coordMode === 'pct' && whiteboardViewport) {
      const xOff = whiteboardViewport.xOffset || 0;
      const yOff = whiteboardViewport.yOffset || 0;
      for (const el of elements) {
        if (el.x != null) el.x = Math.round(xOff + (el.x / 100) * whiteboardViewport.width);
        if (el.y != null) el.y = Math.round(yOff + (el.y / 100) * whiteboardViewport.height);
        if (el.width != null) el.width = Math.round((el.width / 100) * whiteboardViewport.width);
        if (el.height != null) el.height = Math.round((el.height / 100) * whiteboardViewport.height);
      }
    }

    const wb = loadWhiteboard();

    const added = [];
    for (const el of elements) {
      // Resolve image URL to base64 dataUrl (for MCP image type)
      if (el.type === 'image' && el.url && !el.dataUrl) {
        try {
          const filePath = join(__dirname, el.url.replace(/^\//, ''));
          if (existsSync(filePath)) {
            const buf = readFileSync(filePath);
            const ext = extname(filePath).toLowerCase();
            const mime = ext === '.svg' ? 'image/svg+xml' : ext === '.png' ? 'image/png' : 'image/jpeg';
            el.dataUrl = `data:${mime};base64,${buf.toString('base64')}`;
          }
        } catch { /* ignore — element will just have no dataUrl */ }
      }
      // Apply section defaults when not specified
      if (el.type === 'section' && el.sectionType) {
        const SEC_DEFAULTS = {
          navbar: { w: 960, h: 56, color: '#64748b', label: 'Navbar' },
          hero: { w: 960, h: 340, color: '#6366f1', label: 'Hero' },
          sidebar: { w: 260, h: 400, color: '#475569', label: 'Sidebar' },
          content: { w: 640, h: 360, color: '#737373', label: 'Content' },
          footer: { w: 960, h: 100, color: '#6b7280', label: 'Footer' },
          card: { w: 260, h: 180, color: '#14b8a6', label: 'Card' },
          form: { w: 380, h: 280, color: '#f59e0b', label: 'Form' },
          'image-placeholder': { w: 280, h: 180, color: '#a855f7', label: 'Image' },
          button: { w: 140, h: 42, color: '#22c55e', label: 'Button' },
          'text-block': { w: 380, h: 90, color: '#e2e8f0', label: 'Text Block' },
          grid: { w: 640, h: 320, color: '#06b6d4', label: 'Grid' },
          modal: { w: 440, h: 300, color: '#f43f5e', label: 'Modal' },
        };
        const def = SEC_DEFAULTS[el.sectionType];
        if (def) {
          if (!el.width) el.width = def.w;
          if (!el.height) el.height = def.h;
          if (!el.color) el.color = def.color;
          if (!el.label) el.label = def.label;
        }
      }
      // Clamp elements to stay within the usable viewport
      if (whiteboardViewport && el.x != null && el.y != null) {
        const vpW = whiteboardViewport.width;
        const vpH = whiteboardViewport.height;
        const xOff = whiteboardViewport.xOffset || 0;
        const yOff = whiteboardViewport.yOffset || 0;
        const elW = el.width || 0;
        const elH = el.height || 0;
        // Don't let elements overflow right/bottom edges
        if (el.x + elW > vpW + xOff) el.x = Math.max(xOff, vpW + xOff - elW);
        if (el.y + elH > vpH + yOff) el.y = Math.max(yOff, vpH + yOff - elH);
        // Don't let elements go under toolbar or above navbar
        if (el.x < xOff) el.x = xOff;
        if (el.y < yOff) el.y = yOff;
      }
      if (!el.id) el.id = 'wb-' + Date.now() + '-' + randomBytes(2).toString('hex').slice(0, 3);
      el.zIndex = wb.nextZIndex++;
      wb.elements.push(el);
      added.push(el);
    }

    saveWhiteboard(wb);
    broadcastToWhiteboard({ type: 'add', elements: added });

    res.json({ ok: true, added: added.map(e => ({ id: e.id, type: e.type, zIndex: e.zIndex })) });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// PUT /api/whiteboard/elements/:id — Update an element
app.put('/api/whiteboard/elements/:id', (req, res) => {
  try {
    const { id } = req.params;
    const { updates, coordMode } = req.body.updates ? req.body : { updates: req.body, coordMode: req.body.coordMode };

    // Percentage coordinate conversion for updates
    if (coordMode === 'pct' && whiteboardViewport) {
      const xOff = whiteboardViewport.xOffset || 0;
      const yOff = whiteboardViewport.yOffset || 0;
      if (updates.x != null) updates.x = Math.round(xOff + (updates.x / 100) * whiteboardViewport.width);
      if (updates.y != null) updates.y = Math.round(yOff + (updates.y / 100) * whiteboardViewport.height);
      if (updates.width != null) updates.width = Math.round((updates.width / 100) * whiteboardViewport.width);
      if (updates.height != null) updates.height = Math.round((updates.height / 100) * whiteboardViewport.height);
    }

    const wb = loadWhiteboard();
    if (!wb.elements.length) return res.status(404).json({ error: 'Whiteboard is empty' });

    const idx = wb.elements.findIndex(e => e.id === id);
    if (idx === -1) return res.status(404).json({ error: `Element ${id} not found` });

    const el = wb.elements[idx];
    for (const [key, value] of Object.entries(updates)) {
      if (key === 'id' || key === 'type' || key === 'coordMode') continue;
      el[key] = value;
    }

    saveWhiteboard(wb);
    broadcastToWhiteboard({ type: 'update', id, updates });

    res.json({ ok: true, element: el });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// DELETE /api/whiteboard/elements/:id — Remove an element
app.delete('/api/whiteboard/elements/:id', (req, res) => {
  try {
    const { id } = req.params;
    const wb = loadWhiteboard();
    if (!wb.elements.length) return res.status(404).json({ error: 'Whiteboard is empty' });

    const idx = wb.elements.findIndex(e => e.id === id);
    if (idx === -1) return res.status(404).json({ error: `Element ${id} not found` });

    const removed = wb.elements.splice(idx, 1)[0];

    // Detach arrows anchored to this element
    for (const a of wb.elements) {
      if (a.type !== 'arrow') continue;
      if (a.startAnchor === id) a.startAnchor = null;
      if (a.endAnchor === id) a.endAnchor = null;
    }

    saveWhiteboard(wb);
    broadcastToWhiteboard({ type: 'remove', id });

    res.json({ ok: true, removed: { id: removed.id, type: removed.type } });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// POST /api/whiteboard/clear — Clear all elements
app.post('/api/whiteboard/clear', (req, res) => {
  try {
    saveWhiteboard({ elements: [], nextZIndex: 1 });
    broadcastToWhiteboard({ type: 'clear' });

    res.json({ ok: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// GET /api/whiteboard/screenshot — Request screenshot from connected browser
app.get('/api/whiteboard/screenshot', async (req, res) => {
  if (whiteboardClients.size === 0) {
    return res.status(503).json({ error: 'No browser connected to whiteboard. Open the Neural Interface and enter Focus mode.' });
  }

  const requestId = randomBytes(8).toString('hex');
  try {
    const data = await new Promise((resolve, reject) => {
      const timer = setTimeout(() => {
        whiteboardPendingScreenshots.delete(requestId);
        reject(new Error('Screenshot timed out after 10s'));
      }, 10000);

      whiteboardPendingScreenshots.set(requestId, { resolve, reject, timer });
      broadcastToWhiteboard({ type: 'screenshot:request', requestId });
    });

    res.json({ ok: true, data }); // data is base64 JPEG
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});


// ══════════════════════════════════════════════════
// STYLE GUIDE — per-project visual identity + DESIGN.md
// ══════════════════════════════════════════════════

const STYLE_GUIDES_DIR = resolve(DATA_HOME, 'data', 'style-guides');
const STYLE_GUIDES_ASSETS_DIR = resolve(STYLE_GUIDES_DIR, 'assets');

function ensureStyleGuidesDirs() {
  if (!existsSync(STYLE_GUIDES_DIR)) mkdirSync(STYLE_GUIDES_DIR, { recursive: true });
  if (!existsSync(STYLE_GUIDES_ASSETS_DIR)) mkdirSync(STYLE_GUIDES_ASSETS_DIR, { recursive: true });
}

function styleGuideHash(projectPath) {
  return createHash('sha1').update(resolve(projectPath)).digest('hex').slice(0, 16);
}

function styleGuideJsonPath(projectPath) {
  return resolve(STYLE_GUIDES_DIR, styleGuideHash(projectPath) + '.json');
}

function styleGuideAssetsDir(projectPath) {
  return resolve(STYLE_GUIDES_ASSETS_DIR, styleGuideHash(projectPath));
}

function resolveRegisteredProject(projectPath) {
  if (!projectPath) return null;
  const normalized = resolve(projectPath);
  const registered = loadHookProjects();
  return registered.find(p => resolve(p.path) === normalized) || null;
}

function loadStyleGuide(projectPath) {
  const file = styleGuideJsonPath(projectPath);
  if (!existsSync(file)) return defaultStyleGuide(resolve(projectPath));
  try {
    const parsed = JSON.parse(readFileSync(file, 'utf-8'));
    parsed.projectPath = resolve(projectPath);
    return parsed;
  } catch {
    return defaultStyleGuide(resolve(projectPath));
  }
}

function writeStyleGuideArtifacts(projectPath, config) {
  ensureStyleGuidesDirs();
  config.projectPath = resolve(projectPath);
  config.updatedAt = new Date().toISOString();

  // 1. Write per-project JSON
  writeFileSync(styleGuideJsonPath(projectPath), JSON.stringify(config, null, 2) + '\n', 'utf-8');

  // 2. Regenerate DESIGN.md in the project root
  const designPath = resolve(projectPath, 'DESIGN.md');
  writeFileSync(designPath, renderDesignMd(config), 'utf-8');

  // 3. Mirror logo files into <projectRoot>/.synabun/style-guide/
  const variants = Array.isArray(config.logo?.variants) ? config.logo.variants : [];
  if (variants.length > 0) {
    const projectLogoDir = resolve(projectPath, STYLE_GUIDE_LOGO_DIR);
    if (!existsSync(projectLogoDir)) mkdirSync(projectLogoDir, { recursive: true });
    const srcDir = styleGuideAssetsDir(projectPath);
    for (const v of variants) {
      if (!v.file) continue;
      const src = resolve(srcDir, v.file);
      const dst = resolve(projectLogoDir, v.file);
      if (existsSync(src)) {
        try { copyFileSync(src, dst); }
        catch (err) { console.error('[style-guide] logo mirror failed:', err.message); }
      }
    }
  }

  return { jsonPath: styleGuideJsonPath(projectPath), designPath };
}

// GET /api/style-guide?projectPath=... — Load config + rendered preview
app.get('/api/style-guide', (req, res) => {
  try {
    const projectPath = req.query.projectPath;
    if (!projectPath) return res.status(400).json({ error: 'Missing projectPath' });
    const project = resolveRegisteredProject(projectPath);
    if (!project) return res.status(403).json({ error: 'Project not registered' });

    const config = loadStyleGuide(project.path);
    res.json({
      ok: true,
      config,
      designMd: renderDesignMd(config),
      hasDesignFile: existsSync(resolve(project.path, 'DESIGN.md')),
      assetsHash: styleGuideHash(project.path),
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// PUT /api/style-guide — Save config (writes JSON + DESIGN.md)
app.put('/api/style-guide', (req, res) => {
  try {
    const { projectPath, config } = req.body || {};
    if (!projectPath || !config) return res.status(400).json({ error: 'Missing projectPath or config' });
    const project = resolveRegisteredProject(projectPath);
    if (!project) return res.status(403).json({ error: 'Project not registered' });

    const { designPath } = writeStyleGuideArtifacts(project.path, config);
    const fresh = loadStyleGuide(project.path);
    res.json({
      ok: true,
      config: fresh,
      designMd: renderDesignMd(fresh),
      designPath,
      assetsHash: styleGuideHash(project.path),
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// GET /api/style-guide/preview-md?projectPath=... — Rendered DESIGN.md without writing
app.get('/api/style-guide/preview-md', (req, res) => {
  try {
    const projectPath = req.query.projectPath;
    if (!projectPath) return res.status(400).json({ error: 'Missing projectPath' });
    const project = resolveRegisteredProject(projectPath);
    if (!project) return res.status(403).json({ error: 'Project not registered' });

    const config = loadStyleGuide(project.path);
    res.type('text/markdown').send(renderDesignMd(config));
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// POST /api/style-guide/logo?projectPath=...&variantId=...&name=...&bg=... — Upload a logo image
app.post('/api/style-guide/logo',
  express.raw({ type: ['image/png', 'image/svg+xml', 'image/jpeg', 'image/webp'], limit: '4mb' }),
  (req, res) => {
    try {
      const { projectPath, variantId, name, bg } = req.query;
      if (!projectPath) return res.status(400).json({ error: 'Missing projectPath' });
      if (!req.body || req.body.length === 0) return res.status(400).json({ error: 'No image data received' });
      const project = resolveRegisteredProject(projectPath);
      if (!project) return res.status(403).json({ error: 'Project not registered' });

      ensureStyleGuidesDirs();
      const dir = styleGuideAssetsDir(project.path);
      if (!existsSync(dir)) mkdirSync(dir, { recursive: true });

      const contentType = req.headers['content-type'] || 'image/png';
      const extMap = { 'image/png': '.png', 'image/svg+xml': '.svg', 'image/jpeg': '.jpg', 'image/webp': '.webp' };
      const ext = extMap[contentType] || '.png';
      const id = variantId || ('logo-' + Date.now().toString(36) + randomBytes(2).toString('hex'));
      const filename = id + ext;
      writeFileSync(resolve(dir, filename), req.body);

      const config = loadStyleGuide(project.path);
      if (!config.logo) config.logo = { variants: [], iconLibrary: 'lucide', imageryNotes: '' };
      if (!Array.isArray(config.logo.variants)) config.logo.variants = [];

      // Replace existing variant with same id, otherwise append
      const idx = config.logo.variants.findIndex(v => v.id === id);
      const variant = {
        id,
        name: name || (idx >= 0 ? config.logo.variants[idx].name : 'Variant'),
        bg: bg || (idx >= 0 ? config.logo.variants[idx].bg : 'primary'),
        file: filename,
      };
      if (idx >= 0) {
        // Remove stale file if extension changed
        const oldFile = config.logo.variants[idx].file;
        if (oldFile && oldFile !== filename) {
          try { unlinkSync(resolve(dir, oldFile)); } catch { /* ignore */ }
        }
        config.logo.variants[idx] = variant;
      } else {
        config.logo.variants.push(variant);
      }

      writeStyleGuideArtifacts(project.path, config);
      res.json({ ok: true, variant, config });
    } catch (err) {
      res.status(500).json({ error: err.message });
    }
  }
);

// DELETE /api/style-guide/logo/:variantId?projectPath=... — Remove a logo variant
app.delete('/api/style-guide/logo/:variantId', (req, res) => {
  try {
    const { variantId } = req.params;
    const projectPath = req.query.projectPath;
    if (!projectPath) return res.status(400).json({ error: 'Missing projectPath' });
    const project = resolveRegisteredProject(projectPath);
    if (!project) return res.status(403).json({ error: 'Project not registered' });

    const config = loadStyleGuide(project.path);
    const variants = Array.isArray(config.logo?.variants) ? config.logo.variants : [];
    const idx = variants.findIndex(v => v.id === variantId);
    if (idx === -1) return res.status(404).json({ error: 'Variant not found' });

    const removed = variants.splice(idx, 1)[0];
    if (removed.file) {
      try { unlinkSync(resolve(styleGuideAssetsDir(project.path), removed.file)); } catch { /* ignore */ }
      try { unlinkSync(resolve(project.path, STYLE_GUIDE_LOGO_DIR, removed.file)); } catch { /* ignore */ }
    }
    config.logo.variants = variants;
    writeStyleGuideArtifacts(project.path, config);
    res.json({ ok: true, config });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// GET /api/style-guide/assets/:hash/:file — Serve an uploaded logo file
app.get('/api/style-guide/assets/:hash/:file', (req, res) => {
  try {
    const { hash, file } = req.params;
    if (!/^[a-f0-9]{16}$/.test(hash)) return res.status(400).json({ error: 'Bad hash' });
    if (/[\\/]/.test(file) || file.includes('..')) return res.status(400).json({ error: 'Bad filename' });
    const full = resolve(STYLE_GUIDES_ASSETS_DIR, hash, file);
    if (!full.startsWith(STYLE_GUIDES_ASSETS_DIR + sep)) return res.status(403).json({ error: 'Forbidden' });
    if (!existsSync(full)) return res.status(404).json({ error: 'Not found' });
    res.sendFile(full);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});


// ══════════════════════════════════════════════════
// TIC TAC TOE — REST API (dedicated game endpoints)
// ══════════════════════════════════════════════════

const TTT_BOARD_SIZE = 500;
const TTT_CELL_SIZE = Math.round(TTT_BOARD_SIZE / 3);
const TTT_PIECE_SIZE = 120;
const TTT_PIECE_OFFSET = Math.round((TTT_CELL_SIZE - TTT_PIECE_SIZE) / 2);
const TTT_NUMBER_SIZE = 60;
const TTT_NUMBER_OFFSET = Math.round((TTT_CELL_SIZE - TTT_NUMBER_SIZE) / 2);

const TTT_WIN_LINES = [
  [0,1,2], [3,4,5], [6,7,8], // rows
  [0,3,6], [1,4,7], [2,5,8], // columns
  [0,4,8], [2,4,6],          // diagonals
];

function tttCheckResult(board) {
  for (const [a,b,c] of TTT_WIN_LINES) {
    if (board[a] && board[a] === board[b] && board[b] === board[c]) return board[a];
  }
  return board.every(c => c !== null) ? 'draw' : null;
}

function tttBoardAscii(board) {
  const display = board.map((c, i) => c || String(i + 1));
  return [
    `  ${display[0]} | ${display[1]} | ${display[2]}`,
    '  ---------',
    `  ${display[3]} | ${display[4]} | ${display[5]}`,
    '  ---------',
    `  ${display[6]} | ${display[7]} | ${display[8]}`,
  ].join('\n');
}

function tttLoadAsset(name) {
  const filePath = join(__dirname, 'games', 'TicTacToe', `${name}.svg`);
  if (!existsSync(filePath)) return null;
  const buf = readFileSync(filePath);
  return `data:image/svg+xml;base64,${buf.toString('base64')}`;
}

function tttCellPosition(cellNum, boardX, boardY, size, offset) {
  const idx = cellNum - 1;
  const col = idx % 3;
  const row = Math.floor(idx / 3);
  return {
    x: boardX + col * TTT_CELL_SIZE + offset,
    y: boardY + row * TTT_CELL_SIZE + offset,
  };
}

// POST /api/games/tictactoe/start — Set up board and initialize game
app.post('/api/games/tictactoe/start', (req, res) => {
  try {
    const piece = (req.body.piece || 'X').toUpperCase();
    if (piece !== 'X' && piece !== 'O') {
      return res.status(400).json({ error: 'piece must be "X" or "O"' });
    }

    // Fresh whiteboard for the board — persisted to its own store, not ui-state.
    const wb = { elements: [], nextZIndex: 1 };

    // Calculate centered board position
    const vp = whiteboardViewport || { width: 1920, height: 937 };
    const boardX = Math.round((vp.width - TTT_BOARD_SIZE) / 2);
    const boardY = Math.round((vp.height - TTT_BOARD_SIZE) / 2);

    // Build board elements
    const elements = [];

    // Board grid
    const boardDataUrl = tttLoadAsset('Board');
    elements.push({
      id: 'ttt-board',
      type: 'image',
      x: boardX,
      y: boardY,
      width: TTT_BOARD_SIZE,
      height: TTT_BOARD_SIZE,
      dataUrl: boardDataUrl,
      zIndex: wb.nextZIndex++,
    });

    // Number markers (1-9)
    for (let i = 1; i <= 9; i++) {
      const pos = tttCellPosition(i, boardX, boardY, TTT_NUMBER_SIZE, TTT_NUMBER_OFFSET);
      const dataUrl = tttLoadAsset(String(i));
      elements.push({
        id: `ttt-cell-${i}`,
        type: 'image',
        x: pos.x,
        y: pos.y,
        width: TTT_NUMBER_SIZE,
        height: TTT_NUMBER_SIZE,
        dataUrl,
        zIndex: wb.nextZIndex++,
      });
    }

    wb.elements = elements;

    // Initialize game state
    const gameState = {
      board: [null,null,null, null,null,null, null,null,null],
      turn: 'X',
      status: 'playing',
      winner: null,
      piece,
      boardX,
      boardY,
    };
    saveWhiteboard(wb);
    const state = loadUiState();
    state['tictactoe-game'] = gameState;
    saveUiState(state);

    // Broadcast to whiteboard clients
    broadcastToWhiteboard({ type: 'clear' });
    broadcastToWhiteboard({ type: 'add', elements });
    broadcastToWhiteboard({ type: 'ttt-started', boardX, boardY });

    res.json({
      ok: true,
      board: gameState.board,
      ascii: tttBoardAscii(gameState.board),
      turn: gameState.turn,
      status: gameState.status,
      piece,
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// POST /api/games/tictactoe/move — Make a move
app.post('/api/games/tictactoe/move', (req, res) => {
  try {
    const cell = parseInt(req.body.cell, 10);
    if (isNaN(cell) || cell < 1 || cell > 9) {
      return res.status(400).json({ error: 'cell must be a number 1-9' });
    }

    const state = loadUiState();
    const game = state['tictactoe-game'];
    if (!game) {
      return res.status(400).json({ error: 'No active TicTacToe game. Use start first.' });
    }
    if (game.status !== 'playing') {
      return res.status(400).json({ error: `Game is over: ${game.status}${game.winner ? ' — ' + game.winner + ' wins' : ''}` });
    }

    const idx = cell - 1;
    if (game.board[idx] !== null) {
      return res.status(400).json({ error: `Cell ${cell} is already taken by ${game.board[idx]}` });
    }

    // Place the piece
    const currentPiece = game.turn;
    game.board[idx] = currentPiece;

    // Update whiteboard: remove number marker, add piece
    const wb = loadWhiteboard();
    if (wb.elements.length) {
      // Remove number marker
      const markerIdx = wb.elements.findIndex(e => e.id === `ttt-cell-${cell}`);
      let removedMarker = null;
      if (markerIdx !== -1) {
        removedMarker = wb.elements.splice(markerIdx, 1)[0];
      }

      // Add piece at correct position
      const assetName = currentPiece === 'X' ? 'Cross' : 'Circle';
      const dataUrl = tttLoadAsset(assetName);
      const pos = tttCellPosition(cell, game.boardX, game.boardY, TTT_PIECE_SIZE, TTT_PIECE_OFFSET);
      const pieceEl = {
        id: `ttt-piece-${cell}`,
        type: 'image',
        x: pos.x,
        y: pos.y,
        width: TTT_PIECE_SIZE,
        height: TTT_PIECE_SIZE,
        dataUrl,
        zIndex: wb.nextZIndex++,
      };
      wb.elements.push(pieceEl);

      // Broadcast whiteboard changes
      if (removedMarker) broadcastToWhiteboard({ type: 'remove', id: `ttt-cell-${cell}` });
      broadcastToWhiteboard({ type: 'add', elements: [pieceEl] });
      saveWhiteboard(wb);
    }

    // Check for win/draw
    const result = tttCheckResult(game.board);
    if (result === 'draw') {
      game.status = 'draw';
    } else if (result) {
      game.status = 'won';
      game.winner = result;
    } else {
      // Toggle turn
      game.turn = game.turn === 'X' ? 'O' : 'X';
    }

    state['tictactoe-game'] = game;
    saveUiState(state);

    const response = {
      ok: true,
      board: game.board,
      ascii: tttBoardAscii(game.board),
      turn: game.turn,
      status: game.status,
    };
    if (game.winner) response.winner = game.winner;

    res.json(response);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// GET /api/games/tictactoe/state — Get current game state
app.get('/api/games/tictactoe/state', (req, res) => {
  try {
    const state = loadUiState();
    const game = state['tictactoe-game'];
    if (!game) {
      return res.json({ ok: true, active: false, message: 'No active game' });
    }

    const response = {
      ok: true,
      active: true,
      board: game.board,
      ascii: tttBoardAscii(game.board),
      turn: game.turn,
      status: game.status,
      piece: game.piece,
    };
    if (game.winner) response.winner = game.winner;

    res.json(response);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// POST /api/games/tictactoe/end — Tear down game
app.post('/api/games/tictactoe/end', (req, res) => {
  try {
    const state = loadUiState();
    delete state['tictactoe-game'];
    saveUiState(state);
    saveWhiteboard({ elements: [], nextZIndex: 1 });

    broadcastToWhiteboard({ type: 'clear' });
    broadcastToWhiteboard({ type: 'ttt-ended' });

    res.json({ ok: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});


