// POST /api/mcp/install/detect  { path } or { name } → re-run detection.
app.post('/api/mcp/install/detect', (req, res) => {
  try {
    const { path: repoPath, name } = req.body || {};
    const target = repoPath || (name ? mcpInstaller.repoDir(DATA_HOME, name) : null);
    if (!target) return res.status(400).json({ ok: false, error: 'Missing path or name' });
    const result = mcpInstaller.detectServer(target);
    if (!result.ok) return res.status(422).json(result);
    res.json({ ok: true, detected: result.detected, attempts: result.attempts });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// POST /api/mcp/install/run  { name, runInstall? } → re-run deps install.
app.post('/api/mcp/install/run', async (req, res) => {
  try {
    const { name } = req.body || {};
    if (!name) return res.status(400).json({ ok: false, error: 'Missing name' });
    const repoPath = mcpInstaller.repoDir(DATA_HOME, name);
    if (!existsSync(repoPath)) return res.status(404).json({ ok: false, error: `No cloned repo for "${name}" at ${repoPath}` });
    const lines = [];
    const result = await mcpInstaller.installDependencies({
      dataHome: DATA_HOME, name, repoPath,
      onLine: (l) => { if (lines.length < 500) lines.push(l); },
    });
    if (!result.ok) return res.status(500).json({ ok: false, error: result.error, log: lines });
    res.json({ ok: true, ...result, log: lines.slice(-50) });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// GET /api/mcp/install/log?name=foo&tail=200
app.get('/api/mcp/install/log', (req, res) => {
  try {
    const { name, tail } = req.query || {};
    if (!name) return res.status(400).json({ ok: false, error: 'Missing name' });
    const p = mcpInstaller.installLogPath(DATA_HOME, String(name));
    if (!existsSync(p)) return res.json({ ok: true, log: '' });
    const content = readFileSync(p, 'utf-8');
    const n = Number(tail) || 500;
    const lines = content.split(/\r?\n/);
    res.json({ ok: true, log: lines.slice(-n).join('\n') });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// GET /api/mcp/env/:name?reveal=1 — mask secrets unless reveal=1.
app.get('/api/mcp/env/:name', (req, res) => {
  try {
    const { name } = req.params;
    const reveal = String(req.query.reveal || '') === '1';
    const env = mcpInstaller.readEnvFile(DATA_HOME, name);
    res.json({ ok: true, env: reveal ? env : mcpInstaller.maskEnv(env) });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// PUT /api/mcp/env/:name { env: {...}, platforms?: [...] } → write env.json and optionally re-sync.
app.put('/api/mcp/env/:name', async (req, res) => {
  try {
    const { name } = req.params;
    const { env, platforms } = req.body || {};
    if (!env || typeof env !== 'object') return res.status(400).json({ ok: false, error: 'Missing env object' });
    // Do not store masked values — preserve existing ones.
    const existing = mcpInstaller.readEnvFile(DATA_HOME, name);
    const merged = { ...existing };
    for (const [k, v] of Object.entries(env)) {
      if (typeof v === 'string' && /^\*+/.test(v)) continue; // skip masked
      merged[k] = v;
    }
    // Remove keys explicitly set to null.
    for (const [k, v] of Object.entries(env)) {
      if (v === null) delete merged[k];
    }
    mcpInstaller.writeEnvFile(DATA_HOME, name, merged);

    // Trigger resync if caller requested.
    let resync = null;
    if (Array.isArray(platforms) && platforms.length) {
      const reg = readMcpRegistry();
      const serverEntry = reg.servers[name];
      if (serverEntry) {
        const launchConfig = buildLaunchConfig(name, serverEntry);
        resync = await internalMcpSync({ name, config: launchConfig, platforms });
      }
    }
    res.json({ ok: true, resync });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// Internal helper shared by PUT /api/mcp/env and POST /api/mcp/sync
async function internalMcpSync({ name, config, platforms }) {
  const results = {};
  const home = getHomePath();
  for (const p of platforms) {
    try {
      if (p === 'claudeCode') {
        const claudeJsonPath = join(home, '.claude.json');
        let data = {};
        try { data = JSON.parse(readFileSync(claudeJsonPath, 'utf-8')); } catch {}
        if (!data.mcpServers) data.mcpServers = {};
        if (config.type === 'stdio') {
          const entry = { command: config.command };
          if (config.args?.length) entry.args = config.args;
          if (config.env && Object.keys(config.env).length) entry.env = config.env;
          data.mcpServers[name] = entry;
        } else {
          data.mcpServers[name] = { type: config.type, url: config.url };
        }
        writeFileSync(claudeJsonPath, JSON.stringify(data, null, 2), 'utf-8');
        results.claudeCode = 'ok';
      } else if (p === 'opencode') {
        persistMcpToOpencodeConfig(name, config);
        results.opencode = 'ok';
      } else if (p === 'codex') {
        const dir = join(home, '.codex');
        const configPath = join(dir, 'config.toml');
        mkdirSync(dir, { recursive: true });
        let content = '';
        try { content = readFileSync(configPath, 'utf-8'); } catch {}
        const kvPairs = { command: config.command || '' };
        if (config.args?.length) kvPairs.args = config.args;
        if (config.env && Object.keys(config.env).length) kvPairs.env = config.env;
        content = tomlUpsertSection(content, `mcp_servers.${name}`, kvPairs);
        writeFileSync(configPath, content, 'utf-8');
        results.codex = 'ok';
      } else if (p === 'gemini') {
        const dir = join(home, '.gemini');
        const settingsPath = join(dir, 'settings.json');
        mkdirSync(dir, { recursive: true });
        let data = {};
        try { data = JSON.parse(readFileSync(settingsPath, 'utf-8')); } catch {}
        if (!data.mcpServers) data.mcpServers = {};
        const entry = { command: config.command || '' };
        if (config.args?.length) entry.args = config.args;
        if (config.env && Object.keys(config.env).length) entry.env = config.env;
        data.mcpServers[name] = entry;
        writeFileSync(settingsPath, JSON.stringify(data, null, 2) + '\n', 'utf-8');
        results.gemini = 'ok';
      }
    } catch (err) {
      results[p] = `error: ${err.message}`;
    }
  }
  return results;
}

app.post('/api/mcp/sync', async (req, res) => {
  const { name, config: incomingConfig, platforms } = req.body;
  if (!name || !incomingConfig || !Array.isArray(platforms)) {
    return res.status(400).json({ ok: false, error: 'Missing name, config, or platforms array' });
  }
  // Always merge env.json secrets on top of the incoming config.
  const envFromFile = mcpInstaller.readEnvFile(DATA_HOME, name);
  const config = { ...incomingConfig, env: { ...(incomingConfig.env || {}), ...envFromFile } };
  const results = await internalMcpSync({ name, config, platforms });
  res.json({ ok: true, results });
});

app.delete('/api/mcp/sync', (req, res) => {
  const { name, platforms } = req.body;
  if (!name || !Array.isArray(platforms)) {
    return res.status(400).json({ ok: false, error: 'Missing name or platforms array' });
  }
  const results = {};
  const home = getHomePath();

  for (const p of platforms) {
    try {
      if (p === 'claudeCode') {
        const claudeJsonPath = join(home, '.claude.json');
        if (existsSync(claudeJsonPath)) {
          const data = JSON.parse(readFileSync(claudeJsonPath, 'utf-8'));
          if (data.mcpServers?.[name]) {
            delete data.mcpServers[name];
            if (Object.keys(data.mcpServers).length === 0) delete data.mcpServers;
            writeFileSync(claudeJsonPath, JSON.stringify(data, null, 2), 'utf-8');
          }
        }
        results.claudeCode = 'ok';

      } else if (p === 'opencode') {
        const configPath = getOpencodeConfigPath();
        if (existsSync(configPath)) {
          const cfg = JSON.parse(readFileSync(configPath, 'utf8'));
          if (cfg.mcp?.[name]) {
            delete cfg.mcp[name];
            writeFileSync(configPath, JSON.stringify(cfg, null, 2) + '\n', 'utf8');
          }
        }
        results.opencode = 'ok';

      } else if (p === 'codex') {
        const configPath = join(home, '.codex', 'config.toml');
        if (existsSync(configPath)) {
          let content = readFileSync(configPath, 'utf-8');
          content = tomlRemoveSection(content, `mcp_servers.${name}`);
          writeFileSync(configPath, content, 'utf-8');
        }
        results.codex = 'ok';

      } else if (p === 'gemini') {
        const settingsPath = join(home, '.gemini', 'settings.json');
        if (existsSync(settingsPath)) {
          const data = JSON.parse(readFileSync(settingsPath, 'utf-8'));
          if (data.mcpServers?.[name]) {
            delete data.mcpServers[name];
            if (Object.keys(data.mcpServers).length === 0) delete data.mcpServers;
            writeFileSync(settingsPath, JSON.stringify(data, null, 2) + '\n', 'utf-8');
          }
        }
        results.gemini = 'ok';
      }
    } catch (err) {
      results[p] = `error: ${err.message}`;
    }
  }
  res.json({ ok: true, results });
});

// --- Invite Key & Session Management ---
const INVITE_KEY_PATH = resolve(DATA_HOME, 'data', 'invite-key.json');
const INVITE_SESSIONS_PATH = resolve(DATA_HOME, 'data', 'invite-sessions.json');
const INVITE_PROXY_PATH = resolve(DATA_HOME, 'data', 'invite-proxy.json');
const INVITE_PERMISSIONS_PATH = resolve(DATA_HOME, 'data', 'invite-permissions.json');

const DEFAULT_PERMISSIONS = { terminal: false, whiteboard: false, memories: true, skills: false, cards: true, browser: false };

let activeInviteKey = null;
const inviteSessions = new Map(); // token → { createdAt, lastSeen, userAgent }

function loadInviteKey() {
  try {
    if (existsSync(INVITE_KEY_PATH)) {
      const data = JSON.parse(readFileSync(INVITE_KEY_PATH, 'utf8'));
      activeInviteKey = data.key || null;
      return data;
    }
  } catch {}
  activeInviteKey = null;
  return null;
}

function saveInviteKey(key) {
  const dir = resolve(DATA_HOME, 'data');
  if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
  const data = { key, createdAt: new Date().toISOString() };
  writeFileSync(INVITE_KEY_PATH, JSON.stringify(data, null, 2));
  activeInviteKey = key;
  return data;
}

function deleteInviteKey() {
  try {
    if (existsSync(INVITE_KEY_PATH)) writeFileSync(INVITE_KEY_PATH, JSON.stringify({}, null, 2));
  } catch {}
  activeInviteKey = null;
}

function loadInviteSessions() {
  try {
    if (existsSync(INVITE_SESSIONS_PATH)) {
      const data = JSON.parse(readFileSync(INVITE_SESSIONS_PATH, 'utf8'));
      if (Array.isArray(data.sessions)) {
        const now = Date.now();
        for (const s of data.sessions) {
          if (s.token && s.createdAt && (now - s.createdAt) < 24 * 60 * 60 * 1000) {
            inviteSessions.set(s.token, { createdAt: s.createdAt, lastSeen: s.lastSeen || s.createdAt, userAgent: s.userAgent });
          }
        }
      }
    }
  } catch {}
}

function persistInviteSessions() {
  const dir = resolve(DATA_HOME, 'data');
  if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
  const sessions = [...inviteSessions.entries()].map(([token, s]) => ({
    token, createdAt: s.createdAt, lastSeen: s.lastSeen, userAgent: s.userAgent
  }));
  writeFileSync(INVITE_SESSIONS_PATH, JSON.stringify({ sessions }, null, 2));
}

function loadInviteProxy() {
  try {
    if (existsSync(INVITE_PROXY_PATH)) {
      return JSON.parse(readFileSync(INVITE_PROXY_PATH, 'utf8'));
    }
  } catch {}
  return { useProxy: false, proxyUrl: '' };
}

function saveInviteProxy(config) {
  const dir = resolve(DATA_HOME, 'data');
  if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
  writeFileSync(INVITE_PROXY_PATH, JSON.stringify(config, null, 2));
}

let invitePermissions = { ...DEFAULT_PERMISSIONS };

function loadInvitePermissions() {
  try {
    if (existsSync(INVITE_PERMISSIONS_PATH)) {
      const data = JSON.parse(readFileSync(INVITE_PERMISSIONS_PATH, 'utf8'));
      invitePermissions = { ...DEFAULT_PERMISSIONS, ...data };
      return invitePermissions;
    }
  } catch {}
  invitePermissions = { ...DEFAULT_PERMISSIONS };
  return invitePermissions;
}

function saveInvitePermissions(perms) {
  const dir = resolve(DATA_HOME, 'data');
  if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
  invitePermissions = { ...DEFAULT_PERMISSIONS, ...perms };
  writeFileSync(INVITE_PERMISSIONS_PATH, JSON.stringify(invitePermissions, null, 2));
  return invitePermissions;
}

// Load on startup
loadInviteKey();
loadInviteSessions();
loadInvitePermissions();

// Invite status (local only — tunnel middleware blocks unauthenticated)
app.get('/api/invite/status', (req, res) => {
  const keyData = loadInviteKey();
  const proxy = loadInviteProxy();
  // Clean expired sessions
  const now = Date.now();
  for (const [token, session] of inviteSessions.entries()) {
    if (now - session.createdAt > 24 * 60 * 60 * 1000) inviteSessions.delete(token);
  }
  const masked = keyData?.key ? '***' + keyData.key.slice(-8) : null;
  res.json({
    ok: true,
    hasKey: !!activeInviteKey,
    maskedKey: masked,
    createdAt: keyData?.createdAt || null,
    activeSessions: inviteSessions.size,
    proxyConfig: proxy,
  });
});

// Generate or rotate invite key (clears all sessions)
app.post('/api/invite/key', (req, res) => {
  const { custom } = req.body || {};
  let key;
  if (custom && typeof custom === 'string' && custom.trim().length >= 6) {
    key = custom.trim();
  } else {
    key = 'synabun_inv_' + randomBytes(24).toString('hex');
  }
  const data = saveInviteKey(key);
  inviteSessions.clear();
  persistInviteSessions();
  res.json({ ok: true, key, createdAt: data.createdAt });
});

// Revoke invite key + all sessions
app.delete('/api/invite/key', (req, res) => {
  deleteInviteKey();
  inviteSessions.clear();
  persistInviteSessions();
  res.json({ ok: true });
});

// Revoke all sessions (keep key)
app.delete('/api/invite/sessions', (req, res) => {
  inviteSessions.clear();
  persistInviteSessions();
  res.json({ ok: true });
});

// Save custom proxy config
app.put('/api/invite/proxy', (req, res) => {
  const { useProxy, proxyUrl } = req.body || {};
  const config = {
    useProxy: !!useProxy,
    proxyUrl: typeof proxyUrl === 'string' ? proxyUrl.trim() : '',
  };
  saveInviteProxy(config);
  res.json({ ok: true });
});

// Get guest permissions
app.get('/api/invite/permissions', (req, res) => {
  res.json({ ok: true, permissions: { ...invitePermissions } });
});

// Update guest permissions (owner only — admin middleware blocks guests)
app.put('/api/invite/permissions', (req, res) => {
  const updates = req.body || {};
  const validKeys = Object.keys(DEFAULT_PERMISSIONS);
  const merged = { ...invitePermissions };
  for (const k of validKeys) {
    if (typeof updates[k] === 'boolean') merged[k] = updates[k];
  }
  const saved = saveInvitePermissions(merged);
  broadcastSync({ type: 'permissions:changed', permissions: saved });
  res.json({ ok: true, permissions: saved });
});

// Serve invite auth page (express.static won't match /invite -> invite.html)
app.get('/invite', (req, res) => {
  res.sendFile(join(__dirname, 'public', 'invite.html'));
});

// Invite auth — validate key, create session, set cookie
app.post('/invite/auth', (req, res) => {
  if (!activeInviteKey) {
    return res.status(403).json({ error: 'Invitations are not enabled' });
  }
  const { key } = req.body || {};
  if (!key || key !== activeInviteKey) {
    return res.status(401).json({ error: 'Invalid invite key' });
  }
  const token = randomBytes(32).toString('hex');
  const session = {
    createdAt: Date.now(),
    lastSeen: Date.now(),
    userAgent: req.headers['user-agent'] || 'unknown',
  };
  inviteSessions.set(token, session);
  persistInviteSessions();

  const isSecure = !!req.headers['cf-connecting-ip'];
  const cookieParts = [
    `synabun_invite=${token}`,
    'HttpOnly',
    'Path=/',
    'SameSite=None',
    isSecure ? 'Secure' : '',
    'Max-Age=86400',
  ].filter(Boolean).join('; ');
  res.setHeader('Set-Cookie', cookieParts);
  res.json({ ok: true });
});

// Invite logout
app.get('/invite/logout', (req, res) => {
  const cookies = parseCookies(req.headers.cookie);
  const token = cookies['synabun_invite'];
  if (token) {
    inviteSessions.delete(token);
    persistInviteSessions();
  }
  res.setHeader('Set-Cookie', 'synabun_invite=; HttpOnly; Path=/; Max-Age=0');
  res.redirect('/invite');
});

// --- Cloudflare Tunnel Management ---
let tunnelProcess = null;
let tunnelUrl = null;
let tunnelStarting = false;

function findCloudflared() {
  // Try PATH-based lookup first (cross-platform)
  try {
    const cmd = process.platform === 'win32' ? 'where cloudflared' : 'which cloudflared';
    const result = execSync(cmd, { encoding: 'utf-8', timeout: 3000, stdio: ['pipe', 'pipe', 'pipe'] }).trim();
    if (result) return result.split('\n')[0].trim();
  } catch { /* not in PATH */ }

  // Windows-specific fallback paths
  if (process.platform === 'win32') {
    const paths = [
      `${process.env.LOCALAPPDATA}\\cloudflared\\cloudflared.exe`,
      `${process.env.ProgramFiles}\\cloudflared\\cloudflared.exe`,
      `${process.env['ProgramFiles(x86)']}\\cloudflared\\cloudflared.exe`,
    ];
    for (const p of paths) { if (p && existsSync(p)) return p; }
  }
  return null;
}

app.get('/api/tunnel/status', (req, res) => {
  res.json({
    ok: true,
    available: !!findCloudflared(),
    running: !!tunnelProcess,
    starting: tunnelStarting,
    url: tunnelUrl,
  });
});

app.post('/api/tunnel/start', (req, res) => {
  if (tunnelProcess) return res.json({ ok: true, url: tunnelUrl, message: 'Already running.' });
  const bin = findCloudflared();
  if (!bin) return res.status(400).json({ error: 'cloudflared not found. Install it from https://developers.cloudflare.com/cloudflare-one/connections/connect-networks/downloads/' });

  tunnelStarting = true;
  tunnelUrl = null;

  const child = spawn(bin, ['tunnel', '--url', `http://localhost:${PORT}`], {
    stdio: ['ignore', 'pipe', 'pipe'],
    windowsHide: true,
  });

  tunnelProcess = child;
  let urlFound = false;

  const parseUrl = (data) => {
    const text = data.toString();
    // cloudflared prints the URL to stderr
    const match = text.match(/https:\/\/[a-z0-9-]+\.trycloudflare\.com/);
    if (match && !urlFound) {
      urlFound = true;
      tunnelUrl = match[0];
      tunnelStarting = false;
      console.log(`  Tunnel:  ${tunnelUrl}`);
    }
  };

  child.stdout.on('data', parseUrl);
  child.stderr.on('data', parseUrl);

  child.on('close', () => {
    tunnelProcess = null;
    tunnelUrl = null;
    tunnelStarting = false;
  });

  // Respond immediately, client polls /api/tunnel/status for the URL
  res.json({ ok: true, message: 'Tunnel starting...' });
});

app.post('/api/tunnel/stop', (req, res) => {
  if (!tunnelProcess) return res.json({ ok: true, message: 'Not running.' });
  tunnelProcess.kill();
  tunnelProcess = null;
  tunnelUrl = null;
  tunnelStarting = false;
  res.json({ ok: true, message: 'Tunnel stopped.' });
});

// --- MCP HTTP Transport ---
// Mount the SynaBun MCP server as an HTTP endpoint for Claude web client
// Auth via URL-embedded key: /mcp/<key> for tunnel access, /mcp for local access
// Eagerly init DB + embeddings so first request is instant (no cold-start)
try {
  const mcpPath = pathToFileURL(resolve(PACKAGE_ROOT, 'mcp-server', 'dist', 'http.js')).href;
  const { createMcpRoutes, ensureInit: mcpEnsureInit } = await import(mcpPath);

  // Eagerly init: DB, categories, embedding model — runs in background, doesn't block server start
  mcpEnsureInit().then(() => {
    console.log('  MCP HTTP: DB + embeddings warm');
  }).catch(err => {
    console.error('  MCP HTTP eager init failed:', err.message);
  });

  const mcpRouter = createMcpRoutes();

  // Keyed path: /mcp/<key> — validates key, then forwards to MCP router
  app.use('/mcp/:key', (req, res, next) => {
    if (req.params.key !== activeMcpKey) {
      return res.status(403).json({ error: 'Forbidden' });
    }
    next();
  }, mcpRouter);

  // Open path: /mcp — local-only (reject tunnel traffic when key is set)
  app.use('/mcp', (req, res, next) => {
    if (req.headers['cf-connecting-ip'] && activeMcpKey) {
      return res.status(403).json({ error: 'Forbidden' });
    }
    next();
  }, mcpRouter);

  console.log('  MCP HTTP endpoint mounted at /mcp' + (activeMcpKey ? ' (key required for tunnel)' : ' (open)'));
} catch (err) {
  console.error('  MCP HTTP mount failed (run npm run build in mcp-server):', err.message);
}

// ═══════════════════════════════════════════
// TERMINAL — PTY Session Manager
// ═══════════════════════════════════════════

const terminalSessions = new Map(); // sessionId → { pty, clients, profile, cwd, createdAt, outputBytes, vterm, graceTimer }

const IS_WIN = process.platform === 'win32';
const DEFAULT_SHELL = IS_WIN ? (process.env.COMSPEC || 'cmd.exe') : (process.env.SHELL || '/bin/bash');
const TERMINAL_GRACE_PERIOD_MS = 30 * 60 * 1000; // 30 min before orphaned PTY is killed
const TERMINAL_SNAPSHOT_SCROLLBACK_ROWS = 1000;

// WS backpressure: a client whose socket buffer exceeds HIGH stops receiving
// terminal output; once it drains below LOW it gets a reset snapshot instead
// of the (dropped) backlog. Watermarks are estimates — tune with a throttled
// LAN client if resyncs fire too eagerly.
const TERMINAL_WS_HIGH_WATER = 1024 * 1024;  // 1MB
const TERMINAL_WS_LOW_WATER = 128 * 1024;    // 128KB
const TERMINAL_WS_DRAIN_FALLBACK_MS = 1000;  // safety net when 'drain' never fires

// Memoized snapshot render — keyed on the vterm write generation, so N
// simultaneously-draining clients (or a drain racing a reconnect restore)
// share ONE O(scrollback × cols) render instead of each paying for their own.
function getTerminalSnapshot(session) {
  const vterm = session?.vterm;
  if (!vterm) return { ansi: '', plain: '' };
  const gen = vterm.writeGen;
  const cached = session._snapshotCache;
  if (cached && cached.gen === gen) return cached;
  const snap = {
    gen,
    ansi: terminalSnapshotToAnsi(session),
    plain: terminalSnapshotToText(session),
  };
  session._snapshotCache = snap;
  return snap;
}

function _termResyncIfDrained(session, ws) {
  if (ws.readyState !== 1) { _termClearLagState(ws); return; }
  if (ws.bufferedAmount > TERMINAL_WS_LOW_WATER) return;
  _termClearLagState(ws);
  ws._termLagging = false;
  // Drained: bring vterm current, then resync the screen from a snapshot.
  // reset:true makes the client clear + reset before applying it (same path
  // as a reconnect restore).
  try {
    session._flushOutput?.();
    const snap = getTerminalSnapshot(session);
    ws.send(JSON.stringify({ type: 'snapshot', data: snap.ansi, plain: snap.plain, reset: true }));
  } catch {}
}

function _termClearLagState(ws) {
  if (ws._termLagTimer) { clearInterval(ws._termLagTimer); ws._termLagTimer = null; }
  if (ws._termDrainHandler && ws._socket) {
    try { ws._socket.off('drain', ws._termDrainHandler); } catch {}
  }
  ws._termDrainHandler = null;
}

function _termMarkLagging(session, ws) {
  if (ws._termLagging) return;
  ws._termLagging = true;
  // Event-driven: resync the moment the kernel socket buffer drains, instead
  // of polling every 200ms. ws._socket is the underlying net.Socket (semi-
  // internal but stable in the ws library) — the interval below is the
  // fallback for when it's unavailable or 'drain' never fires.
  const onDrain = () => _termResyncIfDrained(session, ws);
  if (ws._socket?.on) {
    ws._termDrainHandler = onDrain;
    ws._socket.on('drain', onDrain);
  }
  ws._termLagTimer = setInterval(onDrain, TERMINAL_WS_DRAIN_FALLBACK_MS);
}

// ── CLI Config (custom CLI paths for terminal profiles) ──

const CLI_CONFIG_PATH = resolve(DATA_HOME, 'data', 'cli-config.json');

const CLI_DEFAULTS = {
  'claude-code': { command: 'claude' },
  'codex':       { command: 'codex' },
  'gemini':      { command: 'gemini' },
  'opencode':    { command: 'opencode' },
};

function loadCliConfig() {
  try {
    if (!existsSync(CLI_CONFIG_PATH)) return { ...CLI_DEFAULTS };
    const raw = JSON.parse(readFileSync(CLI_CONFIG_PATH, 'utf-8'));
    return { ...CLI_DEFAULTS, ...raw };
  } catch { return { ...CLI_DEFAULTS }; }
}

function saveCliConfig(config) {
  const dir = dirname(CLI_CONFIG_PATH);
  if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
  writeFileSync(CLI_CONFIG_PATH, JSON.stringify(config, null, 2), 'utf-8');
  // Clear cached claude binary so getClaudeBin() re-resolves with new config
  _claudeBinPath = null;
}

const SHELL_PROFILE = { shell: DEFAULT_SHELL, args: [], env: {} };

/**
 * Build terminal profile config dynamically from cli-config.json.
 * Re-reads config each call so changes take effect without restart.
 * @param {string} profileId - CLI profile ID (e.g. 'claude-code', 'codex', 'gemini', 'shell')
 * @param {Object} [opts] - Optional overrides
 * @param {string} [opts.model] - Model flag for CLIs that support it (e.g. claude --model sonnet)
 */
function getTerminalProfile(profileId, opts = {}) {
  if (profileId === 'shell') return SHELL_PROFILE;

  const config = loadCliConfig();
  const entry = config[profileId];
  if (!entry || !entry.command) return SHELL_PROFILE;

  let cmd = entry.command.trim();
  if (!cmd) return SHELL_PROFILE;

  // Append resume flag for supported CLIs (mutually exclusive with model)
  if (opts.resume && profileId === 'claude-code') {
    cmd = `${cmd} --resume ${opts.resume}`;
  } else if (opts.resume && profileId === 'codex') {
    cmd = `${cmd} resume ${opts.resume}`;
  } else if (opts.resume && profileId === 'opencode') {
    cmd = `${cmd} -s ${opts.resume}`;
  }
  // Append model flag for CLIs that support it
  else if (opts.model) {
    // Normalize composite "modelId:contextWindow" → CLI-ready id (adds `[1m]`
    // suffix when the selected variant exceeds 200K). Only Claude Code uses
    // the suffix; other CLIs are handed the bare id.
    const cleanModel = profileId === 'claude-code'
      ? toCliModelName(opts.model)
      : (opts.model.includes(':') ? opts.model.split(':')[0] : opts.model);
    // Quote before interpolating into the shell command string. The 1M-context
    // suffix `[1m]` contains `[ ]`, which zsh parses as a glob character class —
    // unquoted it aborts with "no matches found" and the CLI never launches.
    // Mirror the IS_WIN-aware quoting used for --mcp-config below.
    const quotedModel = IS_WIN ? `"${cleanModel}"` : shellSingleQuote(cleanModel);
    const modelMap = {
      'claude-code': (m) => `${cmd} --model ${m}`,
      'codex':       (m) => `${cmd} --model ${m}`,
      'gemini':      (m) => `${cmd} --model ${m}`,
      'opencode':    (m) => `${cmd} --model ${m}`,
    };
    const builder = modelMap[profileId];
    if (builder) cmd = builder(quotedModel);
  }

  // Append effort flag for Claude Code (extended thinking)
  if (opts.effort && profileId === 'claude-code') {
    if (CLAUDE_EFFORT_LEVELS.includes(opts.effort)) {
      cmd = `${cmd} --effort ${opts.effort}`;
    }
  } else if (opts.effort && profileId === 'codex') {
    const codexEffort = toCodexReasoningEffort(opts.effort);
    if (codexEffort) {
      cmd = `${cmd} -c model_reasoning_effort="${codexEffort}"`;
    }
  }

  // Loop-only: bypass permission prompts for unattended Claude Code loops.
  // The loop runs in a PTY with no human to answer prompts, so accessing
  // sibling projects (e.g. CriticalPixel) or running Bash/Write would stall.
  // Scoped to opts.loopBypass so interactive terminal sessions still prompt.
  if (opts.loopBypass && profileId === 'claude-code') {
    cmd = `${cmd} --dangerously-skip-permissions`;
  }

  // Loop-only: per-loop MCP config file (user mcpServers with SynaBun swapped
  // for an HTTP entry carrying this loop's X-Synabun-* pin headers). Strict
  // mode makes the swap deterministic — without it, duplicate-name precedence
  // between --mcp-config and the user-scope ~/.claude.json entry is undefined
  // and a silent fallback to the un-pinned entry would reintroduce tab
  // collisions invisibly. Trade-off: project-scope .mcp.json servers are not
  // loaded inside loops (user-scope servers ARE — they're merged into the file).
  if (opts.mcpConfigPath && profileId === 'claude-code') {
    const quoted = IS_WIN ? `"${opts.mcpConfigPath}"` : `'${opts.mcpConfigPath.replace(/'/g, `'\\''`)}'`;
    cmd = `${cmd} --strict-mcp-config --mcp-config ${quoted}`;
  }

  return {
    shell: DEFAULT_SHELL,
    args: IS_WIN ? ['/k', cmd] : ['-c', `${cmd}; exec $SHELL`],
    env: { FORCE_COLOR: '1', TERM: 'xterm-256color' },
  };
}

function createTerminalSession(profile, cols, rows, cwd, opts = {}) {
  if (!pty) throw new Error('Terminal not available: node-pty failed to load. Run: cd neural-interface && npm run postinstall');
  const sessionId = opts.sessionId || randomBytes(16).toString('hex');
  const profileCfg = getTerminalProfile(profile, opts);
  const initialCols = cols || 120;
  const initialRows = rows || 30;

  // Strip VSCode env vars so spawned CLIs (e.g. claude) don't think they're inside VSCode
  const cleanEnv = Object.fromEntries(
    Object.entries(process.env).filter(([k]) =>
      !k.startsWith('VSCODE_') && k !== 'TERM_PROGRAM' && k !== 'TERM_PROGRAM_VERSION'
    )
  );

  const isLoopOwned = !!(opts.extraEnv && opts.extraEnv.SYNABUN_TERMINAL_SESSION === sessionId);
  if (isLoopOwned) {
    loopLog(sessionId, 'pty:resolve', 'profile resolved', {
      profile, shell: profileCfg.shell, args: profileCfg.args,
      envKeys: Object.keys(profileCfg.env || {}),
      extraEnvKeys: Object.keys(opts.extraEnv || {}),
      cwd, cols: initialCols, rows: initialRows,
    });
  }

  const ptyProcess = pty.spawn(profileCfg.shell, profileCfg.args, {
    name: 'xterm-256color',
    cols: initialCols,
    rows: initialRows,
    cwd: cwd || process.env.USERPROFILE || process.env.HOME || process.cwd(),
    env: { ...cleanEnv, ...profileCfg.env, ...(opts.extraEnv || {}) },
    useConpty: IS_WIN,
  });

  if (isLoopOwned) {
    loopLog(sessionId, 'pty:spawned', 'pty spawned', { pid: ptyProcess.pid });
  }

  const session = {
    pty: ptyProcess, clients: new Set(), profile, cwd,
    createdAt: Date.now(),
    outputBytes: 0,        // monotonic output counter (reconnects snapshot from vterm, no raw ring needed)
    vterm: new VTermBuffer(initialCols, initialRows, TERMINAL_SNAPSHOT_SCROLLBACK_ROWS + initialRows),
    graceTimer: null,      // setTimeout handle for orphan cleanup
    claudeSessionId: opts.resume || null,  // known Claude session ID (from resume or detect)
  };
  terminalSessions.set(sessionId, session);

  // Auto-detect Claude session ID for fresh sessions (not resumed — those already have it)
  if (profile === 'claude-code' && !session.claudeSessionId) {
    setTimeout(() => {
      if (!session.claudeSessionId && terminalSessions.has(sessionId)) {
        const csid = detectClaudeSessionForCwd(session.cwd, session.createdAt);
        if (csid) session.claudeSessionId = csid;
      }
    }, 5000);
  }

  // ── Output coalescing — send-first hot path ──
  // PTY onData fires per chunk (can be many times per ms). Batching per
  // event-loop tick sends one larger frame instead of many small ones. The
  // flush ships bytes to clients FIRST (binary frame, no JSON), then runs all
  // secondary consumers (vterm snapshot model, link capture, loop driver,
  // boot logging) — none of them sit between a PTY byte and the wire.
  let _outputCoalesceBuf = '';
  let _outputCoalesceScheduled = false;

  // Loop boot signature: log first ~500 bytes of PTY output (only for loop-owned sessions)
  let _loopBootCaptured = false;
  let _loopBootBuf = '';

  const _flushCoalesced = () => {
    _outputCoalesceScheduled = false;
    if (!_outputCoalesceBuf) return;
    const coalesced = _outputCoalesceBuf;
    _outputCoalesceBuf = '';
    session.outputBytes += coalesced.length;

    // 1) Ship to clients first — binary frame = raw PTY bytes, zero JSON cost.
    //    Backpressure: a client whose socket buffer exceeds the high-water mark
    //    stops receiving output and is resynced from a snapshot once drained.
    const payload = Buffer.from(coalesced, 'utf8');
    session.clients.forEach(ws => {
      if (ws.readyState !== 1 || ws._termLagging) return;
      if (ws.bufferedAmount > TERMINAL_WS_HIGH_WATER) {
        _termMarkLagging(session, ws);
        return;
      }
      ws.send(payload);
    });

    // 2) Secondary consumers — off the latency-critical path.
    try { session.vterm?.write(coalesced); } catch {}

    if (session._linkCaptureCallback) {
      session._linkCaptureCallback(coalesced);
    }

    if (session._loopDriverBuffer !== undefined) {
      session._loopDriverBuffer += coalesced;
      if (session._loopDriverBuffer.length > 16384) {
        session._loopDriverBuffer = session._loopDriverBuffer.slice(-8192);
      }
    }

    if (isLoopOwned && !_loopBootCaptured) {
      _loopBootBuf += coalesced;
      if (_loopBootBuf.length >= 500) {
        _loopBootCaptured = true;
        loopLog(sessionId, 'pty:boot-output', 'first 500 bytes of pty output captured', {
          uptimeMs: Date.now() - session.createdAt,
          sample: _loopBootBuf.slice(0, 500),
        });
        _loopBootBuf = '';
      }
    }
  };
  // Exposed so exit/connect/resize/resync paths can force vterm up to date
  session._flushOutput = _flushCoalesced;

  const OUTPUT_BURST_CAP = 64 * 1024; // flush early when this much buffered in one tick
  ptyProcess.onData((data) => {
    _outputCoalesceBuf += data;

    // Burst cap: if a huge chunk arrives in one tick, flush synchronously so a
    // multi-MB buffer doesn't pile up and stall the client write loop.
    if (_outputCoalesceBuf.length >= OUTPUT_BURST_CAP) {
      _flushCoalesced();
      return;
    }

    // Schedule flush for end of current event-loop tick
    if (!_outputCoalesceScheduled) {
      _outputCoalesceScheduled = true;
      setImmediate(_flushCoalesced);
    }
  });

  ptyProcess.onExit(({ exitCode }) => {
    // Flush pending output FIRST so the final bytes precede the exit message
    // (fixes the exit-outruns-output race on fast-exiting commands)
    try { session._flushOutput?.(); } catch {}

    // Clear grace timer if set
    if (session.graceTimer) { clearTimeout(session.graceTimer); session.graceTimer = null; }

    if (isLoopOwned) {
      // Flush any remaining boot buffer that didn't reach 500 bytes
      if (!_loopBootCaptured && _loopBootBuf.length > 0) {
        loopLog(sessionId, 'pty:boot-output', `pty exited before 500 bytes (got ${_loopBootBuf.length})`, {
          uptimeMs: Date.now() - session.createdAt,
          sample: _loopBootBuf,
        });
      }
      loopLog(sessionId, 'pty:exit', 'pty exited', {
        exitCode,
        uptimeMs: Date.now() - session.createdAt,
        bootCaptured: _loopBootCaptured,
      });
      // Mark loop file inactive if PTY died with loop still active
      try {
        const loopFile = findLoopFileForTerminal(sessionId);
        if (loopFile) {
          const loopPath = resolve(LOOP_DIR, loopFile);
          const ls = JSON.parse(readFileSync(loopPath, 'utf-8'));
          if (ls.active) {
            ls.active = false;
            ls.completedAt = new Date().toISOString();
            ls.stoppedReason = ls.stoppedReason || `pty-exit-${exitCode}`;
            ls.lastExitCode = exitCode;
            writeFileSync(loopPath, JSON.stringify(ls, null, 2));
            if (ls.driverType === 'exec' && ls.scheduledBy) {
              persistExecScheduleOutcome(ls, 'failed', ls.stoppedReason);
            }
            loopLog(sessionId, 'pty:exit', 'marked loop inactive', { stoppedReason: ls.stoppedReason, loopFile });
          }
        }
      } catch (err) {
        loopLog(sessionId, 'pty:exit', 'failed to mark loop inactive', { err: err.message });
      }
      // Per-loop claude MCP config is keyed by terminalSessionId (= sessionId
      // for loop-owned PTYs); harmless no-op for non-claude profiles.
      cleanupClaudeLoopMcpConfig(sessionId);
      // Per-loop opencode XDG dir is also keyed by terminalSessionId and holds a
      // ~61 MB node_modules. The graceful loop-stop path cleans it, but PTY exit
      // (crash, completion, kill) previously did not — that orphaned dirs into
      // data/loop-configs until they piled into multi-GB. Clean it here too.
      cleanupOpencodeLoopConfig(sessionId);
      cleanupExecLoopArtifacts(session);
    }

    const msg = JSON.stringify({ type: 'exit', exitCode });
    session.clients.forEach(ws => {
      if (ws.readyState === 1) ws.send(msg);
    });
    // Clean up loop driver interval
    if (session._loopDriverInterval) {
      clearInterval(session._loopDriverInterval);
      session._loopDriverInterval = null;
    }
    // Clean up temp files from image paste
    if (session.tempFiles) {
      session.tempFiles.forEach(f => { try { unlinkSync(f); } catch {} });
    }
    // Destroy any links involving this session
    for (const [linkId, link] of terminalLinks) {
      if (link.sessions.includes(sessionId)) {
        const sessions = [...link.sessions];
        destroyTerminalLink(linkId);
        broadcastSync({ type: 'link:deleted', linkId, sessions, reason: 'session-exited' });
      }
    }
    terminalSessions.delete(sessionId);
    // A loop terminal just exited — drop the keep-awake assertion if nothing else
    // (loop or enabled schedule) still needs it.
    if (session._loopTerminalSessionId) reconcileKeepAwake();
  });

  return sessionId;
}

function terminalSnapshotToAnsi(session) {
  const vterm = session?.vterm;
  if (!vterm) return '';

  const cols = Math.max(1, vterm.cols || session?.pty?.cols || 120);
  const rows = Math.max(1, vterm.rows || session?.pty?.rows || 30);
  const parts = ['\x1b[0m'];

  if (vterm.useAltBuffer) {
    parts.push('\x1b[?1049h');
  } else {
    parts.push('\x1b[?1049l');
    const sbLen = vterm.scrollbackLength || 0;
    const start = Math.max(0, sbLen - TERMINAL_SNAPSHOT_SCROLLBACK_ROWS);
    const chars = new Array(cols);
    for (let r = start; r < sbLen; r++) {
      const row = vterm.getScrollbackRow(r);
      if (!row) continue;
      for (let c = 0; c < cols; c++) chars[c] = row[c]?.char || ' ';
      parts.push(chars.join('').replace(/\s+$/g, ''), '\r\n');
    }
  }

  // Clear only the visible viewport. In normal-buffer mode this preserves the
  // scrollback rows emitted above while rebuilding the current screen from the
  // server-side terminal model instead of replaying an arbitrary ANSI tail.
  parts.push('\x1b[2J\x1b[H');
  const screenChars = new Array(cols);
  for (let r = 0; r < rows; r++) {
    const row = vterm.getRow(r);
    if (!row) continue;
    for (let c = 0; c < cols; c++) screenChars[c] = row[c]?.char || ' ';
    parts.push(`\x1b[${r + 1};1H`, screenChars.join('').replace(/\s+$/g, ''));
  }

  parts.push(
    '\x1b[0m',
    vterm.cursorVisible ? '\x1b[?25h' : '\x1b[?25l',
    `\x1b[${Math.min(rows, Math.max(1, vterm.cursorY + 1))};${Math.min(cols, Math.max(1, vterm.cursorX + 1))}H`,
  );

  return parts.join('');
}

function terminalSnapshotToText(session) {
  const vterm = session?.vterm;
  if (!vterm) return '';
  const sb = vterm.scrollbackLength || 0;
  const totalRows = sb + (vterm.rows || 0);
  if (totalRows <= 0) return '';
  const startRow = vterm.useAltBuffer ? sb : Math.max(0, totalRows - TERMINAL_SNAPSHOT_SCROLLBACK_ROWS - (vterm.rows || 0));
  return vterm.getText(startRow, 0, totalRows - 1, Math.max(0, (vterm.cols || 1) - 1));
}

// ── Loop Driver — sends /clear + next iteration prompt between loop iterations ──

// Comprehensive ANSI escape stripping: CSI sequences, OSC sequences, charset selects, cursor keys, and \r
const LOOP_ANSI_RE = /\x1b\[[\x20-\x3f]*[\x40-\x7e]|\x1b\][^\x07]*(?:\x07|\x1b\\)|\x1b[()][AB012]|\x1b[=<>78HMND]|\x1bO[A-Z]|\r/g;

/**
 * Writes text to a PTY in chunks to avoid ConPTY buffer overflow on Windows.
 * Same approach as client-side _sendOnceReady (256-byte chunks, 30ms delays).
 */
function writeToLoopPty(session, text, sendEnter = true) {
  const full = sendEnter ? text + '\r' : text;
  const CHUNK = 256;
  const DELAY = 30;
  const chunkCount = Math.ceil(full.length / CHUNK);
  const totalSettleMs = chunkCount * DELAY;
  const tsid = session?._loopTerminalSessionId || null;
  let writeFailures = 0;
  loopLog(tsid, 'pty:write-begin', 'writeToLoopPty start', {
    bytes: full.length, chunkCount, totalSettleMs, sendEnter,
    preview: text.slice(0, 200),
  });
  for (let i = 0; i < full.length; i += CHUNK) {
    const chunk = full.slice(i, i + CHUNK);
    const delay = (i / CHUNK) * DELAY;
    setTimeout(() => {
      try { session.pty.write(chunk); } catch (err) {
        writeFailures++;
        loopLog(tsid, 'pty:write-fail', 'pty.write threw', { offset: i, err: err.message });
      }
    }, delay);
  }
  setTimeout(() => {
    loopLog(tsid, 'pty:write-end', 'writeToLoopPty all chunks scheduled', {
      bytes: full.length, chunkCount, writeFailures,
    });
  }, totalSettleMs + 50);
  // Return total time for all chunks to be sent
  return totalSettleMs;
}

/**
 * Check if the ANSI-stripped PTY output buffer contains a ready prompt (>).
 * Matches: ">" at end of buffer, ">" on its own line, ">" followed by whitespace/newlines,
 * or the box-style prompt used by newer Claude Code UI (│ > │).
 */
function loopPromptReady(buffer) {
  const stripped = buffer.replace(LOOP_ANSI_RE, '');
  // Current Claude Code prompt: "? for shortcuts" hint line
  if (/\?\s*for shortcuts/i.test(stripped)) return true;
  // End of buffer prompt
  if (/>\s*$/.test(stripped)) return true;
  // Prompt on its own line (possibly with surrounding whitespace/newlines)
  if (/^>\s*$/m.test(stripped)) return true;
  // Prompt followed by newlines then nothing meaningful (e.g. "> \n\n")
  if (/>\s*\n\s*$/.test(stripped)) return true;
  // Box-style prompt: newer Claude Code renders "│ > " inside a box — box chars survive ANSI strip
  const tail = stripped.slice(-400);
  if (/│\s*>/.test(tail)) return true;
  // Claude Code v2.1.x renders the empty input prompt and boot placeholder with the
  // "❯" glyph (U+276F), e.g. `❯ Try "fix lint errors"`. The older checks only match
  // ">" (U+003E) and never fire for this TUI, forcing every loop onto the 30s fallback.
  if (/❯/.test(tail)) return true;
  // Last non-empty line contains a prompt marker (catches any decorated variant)
  const lastLine = stripped.trimEnd().split('\n').pop() || '';
  if (lastLine.includes('>') || lastLine.includes('❯')) return true;
  return false;
}

/**
 * Detect a TRANSIENT Claude Code error in the PTY output buffer — the kind that
 * aborts the turn without firing the Stop hook (so awaitingNext never gets set
 * and the loop would stall). Anchored to the CLI's "API Error:" label to avoid
 * matching the same phrase appearing in normal assistant prose.
 */
function detectTransientApiError(buffer) {
  const stripped = buffer.replace(LOOP_ANSI_RE, '');
  return /API Error:[\s\S]{0,160}?(socket connection was closed|connection (error|closed|reset)|fetch failed|terminated|ECONNRESET|ETIMEDOUT|stream (error|disconnected|interrupted)|overloaded|52\d|50[023])/i.test(stripped);
}

/**
 * Attach a loop driver to a terminal session. The driver watches for the
 * `awaitingNext` flag in the loop state file. When detected, it sends /clear
 * to the PTY via fixed delays, then sends the next iteration message.
 *
 * Prompt detection (loopPromptReady) is ONLY used for the initial boot claim
 * where we need to detect when the CLI has started. For iteration transitions,
 * we use deterministic delays — the stop hook guarantees the PTY is at the prompt.
 */
function attachLoopDriver(terminalSessionId) {
  const session = terminalSessions.get(terminalSessionId);
  if (!session) {
    loopLog(terminalSessionId, 'driver:attach', 'ABORT: terminal session not found in registry');
    return;
  }

  // Initialize capture buffer (used only for initial boot prompt detection)
  session._loopDriverBuffer = '';
  session._loopDriverStartedAt = Date.now();
  session._loopTerminalSessionId = terminalSessionId;
  session._pendingClaimed = false;
  session._pendingClaimedAt = null;
  reconcileKeepAwake(); // a live loop terminal must keep the machine awake (clamshell)
  let driving = false; // prevent re-entrance

  let consecutiveFailures = 0;
  const MAX_DRIVE_FAILURES = 5; // with deterministic delays, failures are real problems
  let tickCount = 0;

  loopLog(terminalSessionId, 'driver:attach', 'hook-driven loop driver attached (claude-code)', { intervalMs: 2000 });

  const interval = setInterval(async () => {
    tickCount++;
    if (driving) return;
    if (!terminalSessions.has(terminalSessionId)) {
      clearInterval(interval);
      loopLog(terminalSessionId, 'driver:tick', 'terminal session gone — clearing driver interval', { ticks: tickCount });
      return;
    }
    // Throttled tick log: every 10th tick (20s)
    if (tickCount % 10 === 0) {
      loopLog(terminalSessionId, 'driver:tick', `tick #${tickCount}`, {
        pendingClaimed: !!session._pendingClaimed,
        bootElapsedMs: Date.now() - (session._loopDriverStartedAt || 0),
        bufferBytes: (session._loopDriverBuffer || '').length,
      });
    }

    // ── Transient API/socket error auto-recovery ──
    // A dropped API socket aborts Claude's turn WITHOUT firing the Stop hook,
    // so awaitingNext is never set and the loop would stall until the
    // maxMinutes watchdog. Detect the error once the CLI is back at the prompt
    // and resume the current iteration (no /clear → context preserved). Runs
    // before the pending-claim cooldown so it can recover the first iteration.
    if (!driving && detectTransientApiError(session._loopDriverBuffer || '')
        && loopPromptReady(session._loopDriverBuffer || '')) {
      const sinceLastErr = Date.now() - (session._lastApiErrorAt || 0);
      if (sinceLastErr > 15000) {
        const loopFile = findLoopFileForTerminal(terminalSessionId);
        let ls = null;
        if (loopFile) {
          try { ls = JSON.parse(readFileSync(resolve(LOOP_DIR, loopFile), 'utf-8')); } catch { /* ok */ }
        }
        if (ls && ls.active && !ls.awaitingNext) {
          const MAX_API_RETRIES = 3;
          session._lastApiErrorAt = Date.now();
          session._loopDriverBuffer = '';
          session._apiErrorRetries = (session._apiErrorRetries || 0) + 1;
          if (session._apiErrorRetries <= MAX_API_RETRIES) {
            loopLog(terminalSessionId, 'driver:api-error', `transient API error — resuming iteration`, {
              retry: session._apiErrorRetries, max: MAX_API_RETRIES, iter: ls.currentIteration,
            });
            driving = true;
            const msg = '[SynaBun Loop] The previous turn hit a transient API/socket error. Resume the current iteration task from where you left off. Do not restart from scratch.';
            const chunkTime = writeToLoopPty(session, msg, true);
            setTimeout(() => { try { session.pty.write('\r'); } catch { /* ok */ } }, chunkTime + 3000);
            setTimeout(() => { driving = false; }, chunkTime + 4000);
          } else {
            // Retries exhausted — force-advance to the next iteration with fresh context
            loopLog(terminalSessionId, 'driver:api-error', `transient API error — retries exhausted, advancing iteration`, {
              iter: ls.currentIteration,
            });
            session._apiErrorRetries = 0;
            try {
              ls.awaitingNext = true;
              writeFileSync(resolve(LOOP_DIR, loopFile), JSON.stringify(ls, null, 2));
            } catch (err) {
              loopLog(terminalSessionId, 'driver:api-error', 'force-advance write FAILED', { err: err.message });
            }
          }
          return;
        }
      }
    }

    // Cooldown after pending claim: don't scan for awaitingNext while the first
    // iteration is still running. Once the pending file is gone (renamed by hook)
    // AND some time has passed, resume normal scanning.
    if (session._pendingClaimedAt) {
      const sinceClaim = Date.now() - session._pendingClaimedAt;
      // Check if any pending files for this terminal still exist
      const stillPending = existsSync(LOOP_DIR) && readdirSync(LOOP_DIR)
        .filter(f => f.startsWith('pending-') && f.endsWith('.json'))
        .some(pf => {
          try {
            const ps = JSON.parse(readFileSync(resolve(LOOP_DIR, pf), 'utf-8'));
            return ps.terminalSessionId === terminalSessionId;
          } catch { return false; }
        });
      // If pending file is still there, the hook hasn't claimed yet — wait
      // If claimed but less than 60s ago, the first iteration is likely still running
      if (stillPending || sinceClaim < 60_000) return;
      // First iteration should be underway — clear cooldown and resume normal scanning
      session._pendingClaimedAt = null;
    }

    // Scan for any loop state file with awaitingNext
    try {
      if (!existsSync(LOOP_DIR)) return;
      const files = readdirSync(LOOP_DIR).filter(f => f.endsWith('.json') && !f.startsWith('pending-'));
      for (const f of files) {
        let loopState;
        try {
          loopState = JSON.parse(readFileSync(resolve(LOOP_DIR, f), 'utf-8'));
        } catch { continue; }

        if (!loopState.awaitingNext || !loopState.active) continue;
        // Only drive loops owned by THIS terminal (prevents cross-session leaking)
        if (loopState.terminalSessionId && loopState.terminalSessionId !== terminalSessionId) continue;

        // Found a loop awaiting next iteration — drive it
        driving = true;
        let success = false;
        try {
          success = await driveNextIteration(session, loopState, f);
        } catch (err) {
          console.error('[loop-driver] Error driving iteration:', err.message);
        }

        if (success) {
          consecutiveFailures = 0;
        } else {
          consecutiveFailures++;
          console.warn(`[loop-driver] Iteration drive failed (${consecutiveFailures}/${MAX_DRIVE_FAILURES})`);
          if (consecutiveFailures >= MAX_DRIVE_FAILURES) {
            console.error(`[loop-driver] ${MAX_DRIVE_FAILURES} consecutive failures — deleting loop`);
            try { unlinkSync(resolve(LOOP_DIR, f)); } catch { /* ok */ }
            consecutiveFailures = 0;
          }
        }

        driving = false;
        break;
      }

      // Claim any pending-*.json for THIS terminal session by writing the initial
      // message directly to the PTY once Claude's > prompt is detected.
      // This makes the server authoritative for the first iteration claim, bypassing
      // the client-side _sendOnceReady which can silently fail if the WS is closed.
      if (!driving && !session._pendingClaimed) {
        // Boot delay: CLI needs ~8-12s to start. Don't poll too early.
        const bootElapsed = Date.now() - (session._loopDriverStartedAt || Date.now());
        if (bootElapsed < 8000) {
          // Too early — let CLI boot
        } else {
          const pendingFiles = readdirSync(LOOP_DIR)
            .filter(f => f.startsWith('pending-') && f.endsWith('.json'));
          if (tickCount % 5 === 0) {
            loopLog(terminalSessionId, 'driver:scan', 'scanning for pending file', {
              pendingCount: pendingFiles.length, bootElapsedMs: bootElapsed,
            });
          }
          let foundOwnPending = false;
          for (const pf of pendingFiles) {
            let pendingState;
            try { pendingState = JSON.parse(readFileSync(resolve(LOOP_DIR, pf), 'utf-8')); } catch { continue; }
            if (pendingState.terminalSessionId !== terminalSessionId) continue;
            foundOwnPending = true;
            if (!pendingState.active && !pendingState.pending) continue;

            // Check for prompt OR use fallback after 30s of waiting
            const waitedForPrompt = bootElapsed - 8000;
            const promptDetected = loopPromptReady(session._loopDriverBuffer || '');
            const fallbackFire = waitedForPrompt > 30000;

            if (promptDetected || fallbackFire) {
              loopLog(terminalSessionId, 'driver:claim', `claiming pending loop`, {
                file: pf, promptDetected, fallbackFire,
                waitedForPromptMs: waitedForPrompt, bootElapsedMs: bootElapsed,
                bufferTail: (session._loopDriverBuffer || '').slice(-300),
              });
              session._pendingClaimed = true;
              session._pendingClaimedAt = Date.now();
              session._loopDriverBuffer = '';

              // Send the initial task message
              const chunkTime = writeToLoopPty(session, '[SynaBun Loop] Begin task.', true);

              // Auto-confirm Enter after the message settles (handles Y/n prompt)
              setTimeout(() => {
                try {
                  session.pty.write('\r');
                  loopLog(terminalSessionId, 'driver:claim', 'auto-confirm Enter sent for pending claim');
                } catch (err) {
                  loopLog(terminalSessionId, 'driver:claim', 'auto-confirm Enter FAILED', { err: err.message });
                }
              }, chunkTime + 4000);
            } else if (tickCount % 5 === 0) {
              loopLog(terminalSessionId, 'driver:claim', 'pending file matched but not claiming yet', {
                promptDetected, waitedForPromptMs: waitedForPrompt, bufferBytes: (session._loopDriverBuffer || '').length,
              });
            }
            break;
          }
          if (!foundOwnPending && tickCount % 5 === 0 && pendingFiles.length > 0) {
            loopLog(terminalSessionId, 'driver:scan', 'no pending file matches this terminal session', {
              pendingFiles, ourTerminalSessionId: terminalSessionId,
            });
          }
        }
      }
    } catch { /* ok */ }
  }, 2000);

  session._loopDriverInterval = interval;
}

/**
 * Drive the next loop iteration: fixed delay → /clear → fixed delay → iteration prompt → auto-confirm.
 * Uses deterministic delays instead of fragile PTY prompt detection.
 * The stop hook only sets awaitingNext after Claude has fully stopped, so the PTY
 * IS at the > prompt — we just need a small grace period for rendering.
 */
async function driveNextIteration(session, loopState, filename) {
  const loopPath = resolve(LOOP_DIR, filename);
  const iter = loopState.currentIteration;
  const tsid = loopState.terminalSessionId || session?._loopTerminalSessionId || null;

  loopLog(tsid, 'driver:iter-begin', `driving iteration ${iter}/${loopState.totalIterations}`, {
    file: filename, awaitingNext: !!loopState.awaitingNext,
  });

  // Reset the transient-API-error retry budget — it is per-iteration.
  session._apiErrorRetries = 0;
  session._lastApiErrorAt = 0;

  // Step 1: Grace delay — let PTY finish rendering after Claude stopped
  await new Promise(r => setTimeout(r, 1000));

  // Step 2: Send /clear to reset conversation context
  session._loopDriverBuffer = '';
  try {
    session.pty.write('/clear\r');
    loopLog(tsid, 'driver:iter', '/clear sent');
  } catch (err) {
    loopLog(tsid, 'driver:iter', '/clear write FAILED', { err: err.message });
  }

  // Step 3: Wait for /clear to process (CLI clears conversation, renders fresh prompt)
  await new Promise(r => setTimeout(r, 2500));

  // Step 4: Send the iteration message (prompt-submit hook will inject full context)
  session._loopDriverBuffer = '';
  const iterMsg = `[SynaBun Loop] Iteration ${iter}. Begin task.`;
  const chunkTime = writeToLoopPty(session, iterMsg, true);
  loopLog(tsid, 'driver:iter', 'iteration message scheduled', { iter, msg: iterMsg, chunkTime });

  // Step 5: Auto-confirm (Enter after all chunks + settle time)
  setTimeout(() => {
    try {
      session.pty.write('\r');
      loopLog(tsid, 'driver:iter', 'auto-confirm Enter sent', { iter });
    } catch (err) {
      loopLog(tsid, 'driver:iter', 'auto-confirm Enter FAILED', { iter, err: err.message });
    }
  }, chunkTime + 1500);

  // Step 6: Clear awaitingNext flag
  try {
    const freshState = JSON.parse(readFileSync(loopPath, 'utf-8'));
    freshState.awaitingNext = false;
    delete freshState._driveRetries; // no longer needed
    writeFileSync(loopPath, JSON.stringify(freshState, null, 2));
    loopLog(tsid, 'driver:iter-end', `iteration ${iter} dispatched, awaitingNext cleared`);
  } catch (err) {
    loopLog(tsid, 'driver:iter-end', 'clear awaitingNext FAILED', { iter, err: err.message });
  }

  return true;
}

// ── Exec-based Loop Driver (Codex, Gemini, etc.) ──
// Fully isolated from Claude's hook-based driver. Runs platform-native wrapper
// files inside a shell PTY and detects completion via sentinel echo markers.
// The wrapper captures the CLI status before printing SYNABUN_ITER_DONE_<N>, so
// cmd.exe and POSIX shells share one driver state machine.

const EXEC_SENTINEL_PREFIX = 'SYNABUN_ITER_DONE_';
const EXEC_BOOT_SENTINEL = 'SYNABUN_EXEC_BOOT_READY';

/**
 * Write loop task to a temp file so the exec command can read from it via stdin.
 * Long task texts garble when passed as shell arguments through PTY chunking
 * (256-byte chunks at 30ms intervals corrupt multi-KB single-quoted strings).
 * The temp file is written once and reused across all iterations.
 */
// Resolve {{GAME_URL[:CCY]}} / {{DEAL_CONTEXT}} tokens against a freshly-picked CriticalPixel
// fresh-release game, so Facebook deal posts link the actual GAME PAGE (/games/<slug>?currency=X)
// instead of the /deals listing. No-op unless the task carries a DEAL SOURCE directive or a
// {{GAME_URL token, so the ~30 non-deal templates are untouched. Resolved ONCE at launch and
// baked into loopState.task, so BOTH the exec driver (prepareExecTaskFile) and the claude-code
// hook (prompt-submit.mjs) inherit the same link with zero per-driver duplication. The deals API
// requires the X-App-Request header (else 403) and reads a precomputed Redis cache (fast).
const CRITICALPIXEL_BASE = process.env.CRITICALPIXEL_BASE_URL || 'https://criticalpixel.gg';
async function resolveDealLink(task) {
  if (!task || (!/\{\{GAME_URL/.test(task) && !/DEAL SOURCE:/i.test(task))) {
    return { task, resolved: false, link: null };
  }
  const m = task.match(/DEAL SOURCE:\s*([a-z-]+)\s*(?:\|\s*currency=([A-Za-z]{3}))?/i);
  const defCcy = (m?.[2] || 'USD').toUpperCase();
  // The game is currency-agnostic (the slug is the same across currencies — only price display
  // differs), so query USD once just to PICK a fresh release, then localize the URL per currency.
  let pick = null;
  try {
    const r = await fetch(`${CRITICALPIXEL_BASE}/api/deals/fresh-releases?currency=USD&limit=25&pricedOnly=1`, {
      headers: { 'X-App-Request': 'critical-pixel', 'User-Agent': 'SynaBun-Loop/1.0' },
      signal: AbortSignal.timeout(6000),
    });
    if (r.ok) {
      const j = await r.json();
      const deals = Array.isArray(j?.deals) ? j.deals : [];
      const priced = deals.filter(d => d?.game_slug && (d.lowest_price ?? 0) > 0);
      priced.sort((a, b) => (b.best_discount || 0) - (a.best_discount || 0));
      const top = priced.slice(0, 5);                     // random among top 5 → variety across runs
      pick = top.length ? top[Math.floor(Math.random() * top.length)] : null;
    } else {
      loopLog(null, 'launch:deal-link', `fresh-releases API non-OK`, { status: r.status });
    }
  } catch (err) {
    loopLog(null, 'launch:deal-link', 'fresh-releases fetch failed (using fallback link)', { err: err.message });
  }

  const gameUrl = ccy => pick
    ? `${CRITICALPIXEL_BASE}/games/${pick.game_slug}?currency=${ccy}`
    : `${CRITICALPIXEL_BASE}/deals/new-releases?currency=${ccy}`;   // fallback: listing, never site root
  let out = task
    .replace(/\{\{GAME_URL:([A-Za-z]{3})\}\}/g, (_, ccy) => gameUrl(ccy.toUpperCase()))
    .replace(/\{\{GAME_URL\}\}/g, gameUrl(defCcy));
  const context = pick
    ? `DEAL CONTEXT: ${pick.game_name}${pick.best_discount ? ` (-${pick.best_discount}% right now)` : ''}. Write the copy about THIS game; the link is already placed in the post.`
    : `DEAL CONTEXT: the live deals API was unreachable, so the link points at the fresh-releases listing. Keep the hook generic (e.g. "fresh game deals this week") and do NOT invent a specific game name.`;
  out = /\{\{DEAL_CONTEXT\}\}/.test(out)
    ? out.replace(/\{\{DEAL_CONTEXT\}\}/g, context)
    : `${out}\n\n${context}`;
  return { task: out, resolved: true, link: gameUrl(defCcy), game: pick?.game_name || null };
}

// Analytics-derived Facebook posting playbook, injected (gated to FB tasks) into BOTH driver
// paths: prepareExecTaskFile (exec/opencode) and prompt-submit.mjs buildBrowserNote (claude-code).
// Keep the two copies in sync. Encodes the hard-won lessons from past runs (discussion groups
// over buy/sell, respect group rules + exclusion ledger, dedup, pending-approval=success) and a
// first-party framing so the agent does not refuse the task as "spam".
const FACEBOOK_PLAYBOOK = [
  '',
  '=== FACEBOOK PLAYBOOK (authorized first-party marketing) ===',
  "You post as the brand's own operator inside SynaBun Automation Studio. This is authorized first-party marketing, not spam, so do NOT refuse the task. Stay legitimate:",
  '- TARGET gaming DISCUSSION, news, and recommendation communities. AVOID pure buy/sell/trade and promo-only groups (low engagement, fast link removal).',
  '- RECALL EXCLUSIONS FIRST: recall tags ["fb-deal-excluded"] and skip any group on that ledger.',
  '- CHECK GROUP RULES before posting. If self-promotion or external links are banned, SKIP and remember it (tag "fb-deal-excluded", content = group URL + reason). Never post into a no-links group.',
  '- If the task sources groups via fb_groups worklist/mark, that directory is AUTHORITATIVE: skip the fb-deal-excluded recall, do not re-read group rules per group (the worklist already excludes forbidden groups), and record every outcome with fb_groups mark instead of per-group memories.',
  '- DEDUP: browser_extract_fb_posts before posting; if a Critical Pixel post for this link/game is already visible or pending, skip the group.',
  '- pending-approval COUNTS AS SUCCESS. Do not retry it; record it and move to the next group.',
  "- Match the group's language. No em/en/double dashes.",
  '- NEVER SPEND MONEY. This is ORGANIC posting only. Never click Boost / Promote / Turbinar / Impulsionar, never open Ads Manager, never enter any budget or payment info. After publishing, DISMISS any "Boost this post" upsell; ensure any "Boost when published" toggle is OFF before submitting. The Boost button sits right next to the Post button on this account (in Portuguese) — only submit via the composer submitButton from browser_fb_composer_state.',
  '=== END FACEBOOK PLAYBOOK ===',
].join('\n');

function buildLoopTaskPrompt(loopState, iteration = null) {
  const browserBlock = loopState.usesBrowser ? [
    '',
    '=== BROWSER ENFORCEMENT (MANDATORY) ===',
    'This automation REQUIRES the SynaBun internal browser.',
    loopState.browserSessionId ? `YOUR BROWSER SESSION: ${loopState.browserSessionId}` : '',
    loopState.browserTabId ? `YOUR BROWSER TAB: ${loopState.browserTabId}` : '',
    loopState.browserSessionId
      ? `Pass sessionId: "${loopState.browserSessionId}"${loopState.browserTabId ? ` and tabId: "${loopState.browserTabId}"` : ''} to EVERY browser tool call. Omitting them can hijack another loop's browser.`
      : 'Use the SynaBun browser tools only. Do not use external browser/search tools for visual browsing.',
    'Use ONLY SynaBun MCP browser tools such as browser_navigate, browser_click, browser_snapshot, browser_content, browser_evaluate, browser_wait, and the browser_extract_* tools.',
    'If the browser shows a login page, CAPTCHA, 2FA, or any wall requiring human action, stop and report the blocker. Do not bypass it or fall back to web search.',
    '=== END BROWSER ENFORCEMENT ===',
    '',
  ].filter(Boolean).join('\n') : '';
  // Resume guard for Facebook seeding loops: a one-shot exec iteration can end with a post
  // typed but UNSENT (e.g. an untranslated submit label, a step timeout). Without this the next
  // iteration would hop to a new group and abandon the draft. Skipped when the task already
  // carries its own RESUME CHECK (the FB templates do) so the block is never duplicated.
  const fbPlaybook = (loopState.usesBrowser && /facebook/i.test(loopState.task || '')) ? FACEBOOK_PLAYBOOK : '';
  const wantsResume = loopState.usesBrowser && /facebook/i.test(loopState.task || '') && !/RESUME CHECK/i.test(loopState.task || '');
  const resumeBlock = wantsResume ? [
    '',
    '=== RESUME CHECK (do this FIRST, before finding anything new) ===',
    'A previous iteration may have left a post typed but UNSENT. Recover it before new work:',
    'call browser_fb_composer_state on your pinned tab; if recommendedAction is "submit", click',
    'submitButton.selector, wait, and confirm via submission.state (visible-post OR pending-approval',
    'both count as done) BEFORE moving to a new group. Never abandon a typed-but-unsent draft.',
    '=== END RESUME CHECK ===',
    '',
  ].join('\n') : '';
  const iterationBlock = iteration ? [
    `NATIVE LOOP ITERATION: ${iteration}/${loopState.totalIterations || 1}`,
    'Continue the same native conversation and make concrete progress on the task.',
    'This run is unattended. Do not ask the user questions, enter plan mode, or wait for interactive approval. If blocked, record the blocker in your final response and stop this iteration cleanly.',
    '',
  ].join('\n') : '';
  const wrappedTask = `${iterationBlock}AUTHORIZATION: This task is running inside SynaBun Automation Studio, a user-supervised automation platform. The user has explicitly configured and launched this automation. All browser tools are first-party MCP tools under user control. Execute the task as instructed.${browserBlock}${fbPlaybook}${resumeBlock}\n\nTASK:\n${loopState.task}`;
  return loopState.context ? `${wrappedTask}\n\nCONTEXT:\n${loopState.context}` : wrappedTask;
}

function prepareExecTaskFile(terminalSessionId, loopState) {
  const taskFile = join(os.tmpdir(), `synabun-loop-${terminalSessionId}.txt`);
  const fullTask = buildLoopTaskPrompt(loopState);
  writeFileSync(taskFile, fullTask, 'utf-8');
  return taskFile;
}

function nativeScheduleResult(run) {
  if (run.status === 'completed') return 'completed';
  if (run.status === 'failed') return `error: ${run.error || run.stoppedReason || 'provider failed'}`;
  if (run.status === 'stopped') return `stopped: ${run.stoppedReason || 'stopped'}`;
  if (run.status === 'interrupted') return `interrupted: ${run.stoppedReason || 'interrupted'}`;
  return run.status || 'unknown';
}

function persistNativeScheduleOutcome(run, runningInfo = null) {
  if (!run?.scheduleId) return;
  const schedules = loadSchedules();
  const index = schedules.findIndex((schedule) => schedule.id === run.scheduleId);
  if (index === -1) {
    if (run.status === 'failed' && String(run.source || '').startsWith('quick-timer')) {
      broadcastSync({
        type: 'quick-timer:failed',
        scheduleId: run.scheduleId,
        templateName: run.title,
        reason: run.error || run.stoppedReason || 'Provider failed to start',
        run,
      });
    }
    return;
  }

  const schedule = schedules[index];
  schedule.lastRunResult = nativeScheduleResult(run);
  schedule.updatedAt = new Date().toISOString();
  saveSchedules(schedules);
  broadcastSync({ type: 'schedule:updated', schedule });
  if (run.status === 'failed') {
    broadcastSync({
      type: 'schedule:failed',
      scheduleId: schedule.id,
      scheduleName: schedule.name || runningInfo?.name || run.title,
      provider: run.provider,
      reason: run.error || run.stoppedReason || 'Provider failed to start',
      run,
    });
  }
}

function persistExecScheduleOutcome(loopState, status, reason = '') {
  if (!loopState?.scheduledBy) return;
  _runningScheduledLoops.delete(loopState.terminalSessionId);
  try {
    const schedules = loadSchedules();
    const index = schedules.findIndex((schedule) => schedule.id === loopState.scheduledBy);
    if (index === -1) return;
    const schedule = schedules[index];
    schedule.lastRunResult = status === 'completed'
      ? 'completed'
      : status === 'stopped'
        ? `stopped: ${reason || 'stopped'}`
        : `error: ${reason || 'exec provider failed'}`;
    schedule.updatedAt = new Date().toISOString();
    saveSchedules(schedules);
    broadcastSync({ type: 'schedule:updated', schedule });
    if (status === 'failed') {
      broadcastSync({
        type: 'schedule:failed',
        scheduleId: schedule.id,
        scheduleName: schedule.name,
        provider: loopState.profile,
        reason: reason || 'Exec provider failed',
      });
    }
  } catch (error) {
    loopLog(
      loopState.terminalSessionId || null,
      'exec-driver:schedule-outcome',
      'failed to persist scheduled exec outcome',
      { status, reason, error: error.message },
    );
  }
}

async function releaseNativeLoopResources(run) {
  if (!run) return;
  const runningInfo = _runningScheduledLoops.get(run.runId) || null;
  persistNativeScheduleOutcome(run, runningInfo);
  _runningScheduledLoops.delete(run.runId);
  if (run.provider === 'opencode') {
    stopIsolatedServe(run.runId);
    cleanupOpencodeLoopConfig(run.runId);
  }
  if (run.provider === 'claude-code') cleanupClaudeLoopMcpConfig(run.runId);
  if (run.browserSessionId && browserSessions.has(run.browserSessionId)) {
    const session = browserSessions.get(run.browserSessionId);
    session?._loopOwned?.delete(run.runId);
    session?._tabOwners?.delete(run.runId);
    if (run.browserTabId && session?.tabs?.has(run.browserTabId) && session.tabs.size > 1) {
      await closeSessionTab(session, run.browserSessionId, run.browserTabId).catch(() => {});
    }
  }
  reconcileKeepAwake();
}

_nativeLoopRuntime = new NativeLoopRuntime({
  stateDir: LOOP_DIR,
  ledgerPath: resolve(LOOP_DATA_DIR, 'native-loop-runs.json'),
  buildPrompt: (state, iteration) => buildLoopTaskPrompt(state, iteration),
  log: (runId, tag, message, meta) => loopLog(runId, tag, message, meta),
  onEvent: (message) => {
    // OpenCode already streams from its isolated serve into the V2 panel. Claude
    // and Codex SDK events need the shared sync socket to reach their renderers.
    if (message.type !== 'sidepanel:provider-event' || message.event?.provider !== 'opencode') {
      broadcastSync(message);
    }
  },
  onFinish: releaseNativeLoopResources,
  providerFactories: {
    'claude-code': (state) => {
      const config = _readClaudeSkinConfig();
      return createClaudeNativeLoopAdapter({
        ...state,
        model: state.model && state.model.includes(':') ? toCliModelName(state.model) : state.model,
        mcpUrl: `http://localhost:${PORT}/mcp`,
        sdkExecutable: config.sdkExecutable || undefined,
        // Fallback if the SDK's bundled native binary is unusable — unattended
        // loops cannot surface a permission error to anyone, so they need the
        // same escape hatch the sidepanel has.
        claudeBin: getClaudeBin(),
        includePartialMessages: typeof config.partials === 'boolean'
          ? config.partials
          : process.platform !== 'win32',
      });
    },
    codex: (state) => {
      // Native SDK schedules bypass the interactive app-server initialization
      // path, so repair the shared config before the SDK can parse it. Without
      // this, legacy inline + table SynaBun env definitions surface as a
      // configWarning and the unattended turn never becomes active.
      ensureCanonicalCodexConfig({ strict: true });
      return createCodexNativeLoopAdapter({
        ...state,
        codexHome: state.codexHome || getCodexAccountHome(state.codexAccountId || 'default'),
        // Native schedules use the same trusted global CLI as the interactive
        // sidepanel. The SDK-owned platform payload is never repaired or run.
        codexPath: getNativeCodexBin(),
      });
    },
    opencode: async (state) => {
      const xdgRoot = setupOpencodeLoopConfig(
        state.runId,
        state.browserSessionId,
        state.browserTabId,
        state.mcpProfile,
        state.model,
      );
      const entry = await ensureIsolatedServe(state.runId, {
        xdgRoot,
        keepAlive: true,
        mcpProfile: state.mcpProfile,
      });
      if (!entry?.client) throw new Error('OpenCode isolated native serve failed to start');
      let providerSessionId = null;
      return createOpenCodeNativeLoopAdapter({
        ...state,
        client: entry.client,
        onIdentity: (identity) => {
          providerSessionId = identity?.providerSessionId || null;
          if (providerSessionId) {
            _ocpSessionToServe.set(providerSessionId, state.runId);
            _ocpSessionProfiles.set(providerSessionId, state.mcpProfile || entry.mcpProfile);
            entry.sessions.add(providerSessionId);
          }
          state.onIdentity(identity);
        },
        release: async () => {
          if (providerSessionId && _ocpSessionToServe.get(providerSessionId) === state.runId) {
            _ocpSessionToServe.delete(providerSessionId);
          }
          stopIsolatedServe(state.runId);
        },
      });
    },
  },
});

/**
 * Build a per-loop XDG_CONFIG_HOME with an opencode config.json whose MCP env
 * block is augmented with this loop's SYNABUN_BROWSER_SESSION/TAB pins.
 * OpenCode's `opencode run` reads MCP server env verbatim from config.json; the
 * pins set on the PTY don't propagate to the MCP child, so we have to bake them
 * into the config file. Returns the XDG_CONFIG_HOME root (parent of opencode/).
 */
function setupOpencodeLoopConfig(terminalSessionId, browserSessionId, browserTabId, mcpProfile = null, model = null) {
  const xdgRoot = resolve(DATA_HOME, 'data', 'loop-configs', `opencode-${terminalSessionId}`);
  const targetDir = resolve(xdgRoot, 'opencode');
  if (!existsSync(targetDir)) mkdirSync(targetDir, { recursive: true });
  const resolvedProfile = normalizeMcpProfileName(mcpProfile || readActiveMcpProfile());
  if (!isValidMcpProfileValue(resolvedProfile)) throw new Error(`Invalid MCP profile: ${resolvedProfile}`);
  const runtimeProfilePath = writeOpencodeRuntimeProfile(xdgRoot, resolvedProfile);

  let baseCfg = {};
  try {
    const userPath = getOpencodeConfigPath();
    if (existsSync(userPath)) baseCfg = JSON.parse(readFileSync(userPath, 'utf8'));
  } catch { /* start from blank if user's config is missing/broken */ }
  if (!baseCfg.mcp) baseCfg.mcp = {};
  const existingEntry = baseCfg.mcp.SynaBun;
  const { mcpIndexPath, envPath } = getMcpPaths();
  const pinOverrides = {
    SYNABUN_TERMINAL_SESSION: terminalSessionId,
    SYNABUN_PROFILE: resolvedProfile,
    SYNABUN_RUNTIME_PROFILE_PATH: runtimeProfilePath,
  };
  if (browserSessionId) pinOverrides.SYNABUN_BROWSER_SESSION = browserSessionId;
  if (browserTabId) pinOverrides.SYNABUN_BROWSER_TAB = browserTabId;
  baseCfg.mcp.SynaBun = buildManagedOpenCodeSynabunEntry(existingEntry, {
    command: ['node', mcpIndexPath],
    defaults: {
      DOTENV_PATH: envPath,
      SYNABUN_DATA_HOME: DATA_HOME,
      MEMORY_DATA_DIR: resolve(DATA_HOME, 'mcp-data'),
    },
    overrides: pinOverrides,
    clearEnv: [
      ...(!browserSessionId ? ['SYNABUN_BROWSER_SESSION'] : []),
      ...(!browserTabId ? ['SYNABUN_BROWSER_TAB'] : []),
      'CLAUDECODE',
    ],
  });
  // Loop permission bypass: SynaBun Automation Studio runs loops unattended,
  // so the loop must not stall on permission gates. The CLI's
  // --dangerously-skip-permissions does NOT cover the `external_directory`
  // gate (a separate permission rule), which auto-REJECTS in non-interactive
  // `run` mode — e.g. reading a sibling project like /Apps/CriticalPixel.
  // Set it (plus edit/bash/webfetch) to "allow" here. Preserves any existing
  // tools/question allow-list from the user's config.
  baseCfg.permission = {
    ...(baseCfg.permission || {}),
    edit: 'allow',
    bash: 'allow',
    webfetch: 'allow',
    external_directory: 'allow',
  };
  ensureOpenCodeCoreMcpPermissions(baseCfg);
  // OpenCode's generic provider request timeout defaults to five minutes. Long
  // cloud-model turns in an unattended loop need a larger but still finite cap.
  const providerId = String(model || '').split('/')[0];
  if (providerId) {
    if (!baseCfg.provider) baseCfg.provider = {};
    const provider = baseCfg.provider[providerId] || {};
    baseCfg.provider[providerId] = {
      ...provider,
      options: {
        ...(provider.options || {}),
        timeout: provider.options?.timeout ?? 600000,
      },
    };
  }
  const target = resolve(targetDir, 'config.json');
  writeFileSync(target, JSON.stringify(baseCfg, null, 2) + '\n', 'utf8');
  return xdgRoot;
}

/**
 * Best-effort cleanup of a per-loop opencode XDG_CONFIG_HOME dir on loop stop.
 */
function cleanupOpencodeLoopConfig(terminalSessionId) {
  const xdgRoot = resolve(DATA_HOME, 'data', 'loop-configs', `opencode-${terminalSessionId}`);
  try {
    if (existsSync(xdgRoot)) rmSync(xdgRoot, { recursive: true, force: true });
  } catch (err) {
    console.warn(`[loop/stop] Failed to remove opencode loop config dir: ${err.message}`);
  }
}

/**
 * Write a per-loop --mcp-config file for Claude Code loops. The PTY env pins
 * (SYNABUN_BROWSER_SESSION/TAB, SYNABUN_TERMINAL_SESSION) only cross into
 * STDIO MCP children — they never reach the NI-hosted HTTP MCP server that
 * ~/.claude.json points Claude Code at. Headers on a per-loop SynaBun HTTP
 * entry carry the same pins per-request instead, so the server's
 * getTargetPage()/_tabOwners routing lands this loop's tab-less browser calls
 * on its own pre-acquired tab. The file contains the user's full mcpServers
 * with SynaBun swapped (used with --strict-mcp-config), so duplicate-name
 * precedence quirks can never reintroduce the un-pinned user-scope entry.
 * Returns the config file path.
 */
function setupClaudeLoopMcpConfig(terminalSessionId, browserSessionId, browserTabId) {
  const dir = resolve(DATA_HOME, 'data', 'loop-configs');
  if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
  const headers = { 'X-Synabun-Terminal': terminalSessionId };
  if (browserSessionId) headers['X-Synabun-Browser-Session'] = browserSessionId;
  if (browserTabId) headers['X-Synabun-Browser-Tab'] = browserTabId;
  let mcpServers = {};
  try {
    const home = process.env.USERPROFILE || process.env.HOME || '';
    const data = JSON.parse(readFileSync(join(home, '.claude.json'), 'utf-8'));
    if (data.mcpServers && typeof data.mcpServers === 'object') mcpServers = { ...data.mcpServers };
  } catch { /* the SynaBun entry alone still pins the loop */ }
  mcpServers.SynaBun = { type: 'http', url: `http://localhost:${PORT}/mcp`, headers };
  const target = resolve(dir, `claude-mcp-${terminalSessionId}.json`);
  writeFileSync(target, JSON.stringify({ mcpServers }, null, 2) + '\n', 'utf8');
  return target;
}

/** Best-effort cleanup of a per-loop Claude MCP config file on loop stop. */
function cleanupClaudeLoopMcpConfig(terminalSessionId) {
  const target = resolve(DATA_HOME, 'data', 'loop-configs', `claude-mcp-${terminalSessionId}.json`);
  try {
    if (existsSync(target)) unlinkSync(target);
  } catch (err) {
    console.warn(`[loop/stop] Failed to remove claude loop mcp config: ${err.message}`);
  }
}

/**
 * Boot-time sweep of orphaned per-loop config artifacts in data/loop-configs.
 * Each opencode-<sid> dir carries a ~61 MB node_modules; the per-loop cleanup
 * runs on graceful stop and PTY exit, but a server crash/restart (or a PTY that
 * never fired its exit) leaves dirs stranded forever. At boot no loop is live,
 * so anything older than the cutoff is safe to remove. Mirrors the mtime-cutoff
 * rmSync pattern used by cleanupOldUpdaterStages().
 */
function cleanupStaleLoopConfigs(maxAgeMs = 6 * 60 * 60 * 1000) {
  const dir = resolve(DATA_HOME, 'data', 'loop-configs');
  let removedDirs = 0, removedFiles = 0;
  try {
    if (!existsSync(dir)) return { removedDirs, removedFiles };
    const cutoff = Date.now() - maxAgeMs;
    for (const name of readdirSync(dir)) {
      const isOpencodeDir = name.startsWith('opencode-');
      const isClaudeCfg = name.startsWith('claude-mcp-') && name.endsWith('.json');
      if (!isOpencodeDir && !isClaudeCfg) continue;
      const full = resolve(dir, name);
      try {
        const st = statSync(full);
        if (st.mtimeMs >= cutoff) continue;
        if (st.isDirectory()) { rmSync(full, { recursive: true, force: true }); removedDirs++; }
        else { unlinkSync(full); removedFiles++; }
      } catch { /* skip unreadable/racing entries */ }
    }
    if (removedDirs || removedFiles) {
      console.log(`[loop-configs] swept ${removedDirs} stale opencode dir(s) + ${removedFiles} claude config(s)`);
    }
  } catch (err) {
    console.warn(`[loop-configs] stale sweep failed: ${err.message}`);
  }
  return { removedDirs, removedFiles };
}

function toCodexReasoningEffort(effort) {
  const value = String(effort || '').trim().toLowerCase();
  if (!value || value === 'off') return null;
  if (value === 'max') return 'xhigh';
  return ['minimal', 'low', 'medium', 'high', 'xhigh'].includes(value) ? value : null;
}

function buildExecMcpEnvOverrides(loopState) {
  const overrides = [];
  if (loopState.browserSessionId) {
    overrides.push(['SYNABUN_BROWSER_SESSION', loopState.browserSessionId]);
  }
  if (loopState.browserTabId) {
    overrides.push(['SYNABUN_BROWSER_TAB', loopState.browserTabId]);
  }
  if (loopState.terminalSessionId) {
    overrides.push(['SYNABUN_TERMINAL_SESSION', loopState.terminalSessionId]);
  }
  if (loopState.mcpProfile) {
    overrides.push(['SYNABUN_PROFILE', loopState.mcpProfile]);
  }
  return overrides;
}

/**
 * Write one platform-native wrapper for an exec-loop iteration. The wrapper
 * reads the task from stdin redirection, captures the provider exit code on its
 * own line, and emits the shared sentinel. Keeping shell grammar in a file
 * avoids sending POSIX syntax to cmd.exe and avoids PTY chunking of long tasks.
 */
function prepareExecWrapperFile(terminalSessionId, loopState, taskFile, sentinel) {
  const config = loadCliConfig();
  const profile = loopState.profile;
  const mcpEnvOverrides = buildExecMcpEnvOverrides(loopState);

  // Surface the exact pins being injected per exec iteration so a stripped/missing
  // browser pin (the codex/opencode env-loss failure mode) is visible in loop logs.
  if (terminalSessionId) {
    loopLog(terminalSessionId, 'exec:mcp-env', `MCP env overrides for ${profile} exec iteration`, {
      profile,
      keys: mcpEnvOverrides.map(([k]) => k),
      browserSessionId: loopState.browserSessionId || null,
      browserTabId: loopState.browserTabId || null,
    });
  }

  const invocation = buildExecInvocation({
    profile,
    command: config[profile]?.command || profile,
    cwd: loopState.cwd || PACKAGE_ROOT,
    model: loopState.model,
    effort: loopState.effort,
    mcpEnvOverrides,
  });
  const wrapperFile = join(
    os.tmpdir(),
    `synabun-loop-${terminalSessionId}${execWrapperExtension(process.platform)}`,
  );
  const wrapper = renderExecWrapper({
    platform: process.platform,
    command: invocation.command,
    args: invocation.args,
    taskFile,
    sentinel,
  });
  writeFileSync(wrapperFile, wrapper, 'utf-8');
  if (process.platform !== 'win32') {
    try { chmodSync(wrapperFile, 0o700); } catch {}
  }
  return {
    wrapperFile,
    launchCommand: execWrapperLaunchCommand(wrapperFile, process.platform),
    invocation,
  };
}

function cleanupExecLoopArtifacts(session) {
  if (!session) return;
  for (const key of ['_execTaskFile', '_execWrapperFile']) {
    const filePath = session[key];
    if (filePath) {
      try { unlinkSync(filePath); } catch {}
      session[key] = null;
    }
  }
}

/**
 * Find the loop state file owned by a given terminal session.
 * Searches both pending-*.json and active loop files.
 */
function findLoopFileForTerminal(terminalSessionId) {
  if (!existsSync(LOOP_DIR)) return null;
  const files = readdirSync(LOOP_DIR).filter(f => f.endsWith('.json'));
  for (const f of files) {
    try {
      const data = JSON.parse(readFileSync(resolve(LOOP_DIR, f), 'utf-8'));
      if (data.terminalSessionId === terminalSessionId) return f;
    } catch { continue; }
  }
  return null;
}

/**
 * Exec-based loop driver for non-Claude CLIs (Codex, Gemini, etc.).
 * State machine: booting → ready → running → ready → ...
 *
 * Completion detection: sentinel echo approach.
 * - Boot: sends `echo SYNABUN_EXEC_BOOT_READY` and waits for it in output.
 * - Each iteration: sends one generated .cmd/.sh wrapper path.
 *   The wrapper captures the CLI exit code and echoes SYNABUN_ITER_DONE_<N>.
 *   We detect `SYNABUN_ITER_DONE_<N>` in the PTY output buffer.
 * This is immune to PS1/PROMPT overrides from oh-my-zsh, starship, etc.
 */
function attachExecLoopDriver(terminalSessionId) {
  const session = terminalSessions.get(terminalSessionId);
  if (!session) {
    loopLog(terminalSessionId, 'exec-driver:attach', 'ABORT: terminal session not found in registry');
    return;
  }

  session._loopDriverBuffer = '';
  session._loopDriverStartedAt = Date.now();
  session._loopTerminalSessionId = terminalSessionId;
  reconcileKeepAwake(); // a live loop terminal must keep the machine awake (clamshell)
  session._execDriverState = 'booting';
  session._execBootSent = false;
  session._execCurrentIter = 0;
  session._execTaskFile = null; // prepared on first ready
  session._execWrapperFile = null; // generated per iteration, same path reused
  session._execIterStartedAt = null;
  let driving = false;
  let tickCount = 0;
  let consecutiveFastFails = 0;
  let consecutiveNonZero = 0;
  const FAST_FAIL_THRESHOLD_MS = 30_000;
  const FAIL_LIMIT = 3;
  loopLog(terminalSessionId, 'exec-driver:attach', 'exec loop driver attached', { intervalMs: 1500 });

  const interval = setInterval(async () => {
    tickCount++;
    if (driving) return;
    if (!terminalSessions.has(terminalSessionId)) {
      clearInterval(interval);
      loopLog(terminalSessionId, 'exec-driver:tick', 'terminal session gone — clearing driver interval', { ticks: tickCount });
      return;
    }
    if (tickCount % 10 === 0) {
      loopLog(terminalSessionId, 'exec-driver:tick', `tick #${tickCount}`, {
        state: session._execDriverState, currentIter: session._execCurrentIter,
        bootSent: session._execBootSent,
      });
    }

    // Load loop state file for this terminal
    const loopFile = findLoopFileForTerminal(terminalSessionId);
    if (!loopFile) return;

    const loopPath = resolve(LOOP_DIR, loopFile);
    let loopState;
    try { loopState = JSON.parse(readFileSync(loopPath, 'utf-8')); }
    catch { return; }

    if (!loopState.active) {
      clearInterval(interval);
      cleanupExecLoopArtifacts(session);
      console.log('[exec-loop-driver] Loop inactive, stopping driver');
      return;
    }

    // Check for sentinel markers in ANSI-stripped PTY output
    const buffer = session._loopDriverBuffer || '';
    const stripped = buffer.replace(LOOP_ANSI_RE, '');

    driving = true;
    try {
      const state = session._execDriverState;

      if (state === 'booting') {
        const bootElapsed = Date.now() - session._loopDriverStartedAt;

        // Send boot sentinel after initial shell startup delay
        if (!session._execBootSent && bootElapsed > 3000) {
          session._loopDriverBuffer = '';
          writeToLoopPty(session, `echo ${EXEC_BOOT_SENTINEL}`, true);
          session._execBootSent = true;
          loopLog(terminalSessionId, 'exec-driver:boot', 'boot sentinel echo sent', { sentinel: EXEC_BOOT_SENTINEL, bootElapsedMs: bootElapsed });
        }

        // Detect boot sentinel OR use fallback timeout
        const sentinelDetected = session._execBootSent && stripped.includes(EXEC_BOOT_SENTINEL);
        const fallbackFire = bootElapsed > 20000;
        if (sentinelDetected || fallbackFire) {
          session._execDriverState = 'ready';
          session._loopDriverBuffer = '';
          loopLog(terminalSessionId, 'exec-driver:boot', 'shell ready', {
            sentinelDetected, fallbackFire, bootElapsedMs: bootElapsed,
            bufferTail: stripped.slice(-200),
          });
        }
      }

      else if (state === 'ready') {
        // Check iteration cap
        const iter = loopState.currentIteration || 0;
        if (iter >= loopState.totalIterations) {
          loopState.active = false;
          loopState.completedAt = new Date().toISOString();
          writeFileSync(loopPath, JSON.stringify(loopState, null, 2));
          persistExecScheduleOutcome(loopState, 'completed');
          clearInterval(interval);
          console.log(`[exec-loop-driver] Loop complete: ${iter}/${loopState.totalIterations}`);
          cleanupExecLoopArtifacts(session);
          driving = false;
          return;
        }

        // Check time cap
        const elapsedMin = (Date.now() - new Date(loopState.startedAt).getTime()) / 60000;
        if (elapsedMin >= loopState.maxMinutes) {
          loopState.active = false;
          loopState.completedAt = new Date().toISOString();
          loopState.stoppedReason = 'time_cap';
          writeFileSync(loopPath, JSON.stringify(loopState, null, 2));
          persistExecScheduleOutcome(loopState, 'stopped', 'time_cap');
          clearInterval(interval);
          console.log(`[exec-loop-driver] Time cap reached: ${Math.round(elapsedMin)}/${loopState.maxMinutes}min`);
          cleanupExecLoopArtifacts(session);
          driving = false;
          return;
        }

        // Prepare task file on first iteration (reused across all iterations)
        if (!session._execTaskFile) {
          session._execTaskFile = prepareExecTaskFile(terminalSessionId, loopState);
          loopLog(terminalSessionId, 'exec-driver:taskfile', 'task file prepared', { path: session._execTaskFile });
        }

        // Generate the platform-native wrapper. It owns exit-code capture and
        // sentinel output; the PTY receives only the short wrapper invocation.
        const nextIter = iter + 1;
        const sentinel = `${EXEC_SENTINEL_PREFIX}${nextIter}`;
        const prepared = prepareExecWrapperFile(
          terminalSessionId,
          loopState,
          session._execTaskFile,
          sentinel,
        );
        session._execWrapperFile = prepared.wrapperFile;
        const fullCmd = prepared.launchCommand;
        loopLog(terminalSessionId, 'exec-driver:iter-begin', `starting iteration ${nextIter}/${loopState.totalIterations}`, {
          profile: loopState.profile, sentinel,
          wrapperFile: prepared.wrapperFile,
          executable: prepared.invocation.command,
          argCount: prepared.invocation.args.length,
          cmdPreview: fullCmd.slice(0, 300),
          cmdBytes: fullCmd.length,
        });

        // Grace delay before sending command
        await new Promise(r => setTimeout(r, 2000));

        session._loopDriverBuffer = '';
        session._execDriverState = 'running';
        session._execCurrentIter = nextIter;
        session._execIterStartedAt = Date.now();
        writeToLoopPty(session, fullCmd, true);

        // Update loop state
        loopState.currentIteration = nextIter;
        loopState.lastIterationAt = new Date().toISOString();
        loopState.pending = false;
        writeFileSync(loopPath, JSON.stringify(loopState, null, 2));
      }

      else if (state === 'running') {
        // Detect iteration completion via sentinel echo + capture rc
        const sentinelRe = new RegExp(`${EXEC_SENTINEL_PREFIX}${session._execCurrentIter} rc=(-?\\d+)`);
        const m = stripped.match(sentinelRe);
        if (m) {
          const rc = parseInt(m[1], 10);
          const iterDurationMs = Date.now() - (session._execIterStartedAt || Date.now());
          const isFastFail = iterDurationMs < FAST_FAIL_THRESHOLD_MS;
          const isNonZero = rc !== 0;

          if (isNonZero) consecutiveNonZero++; else consecutiveNonZero = 0;
          if (isFastFail) consecutiveFastFails++; else consecutiveFastFails = 0;

          loopLog(terminalSessionId, 'exec-driver:iter-end', `iteration ${session._execCurrentIter} complete`, {
            rc, iterDurationMs, isFastFail, isNonZero,
            consecutiveNonZero, consecutiveFastFails,
          });

          // Halt on failure streak (3 consecutive non-zero OR 3 consecutive fast)
          if (consecutiveNonZero >= FAIL_LIMIT || consecutiveFastFails >= FAIL_LIMIT) {
            const reason = consecutiveNonZero >= FAIL_LIMIT ? 'fast-fail-rc' : 'fast-fail-duration';
            loopState.active = false;
            loopState.completedAt = new Date().toISOString();
            loopState.stoppedReason = reason;
            loopState.lastExitCode = rc;
            try { writeFileSync(loopPath, JSON.stringify(loopState, null, 2)); } catch { /* ok */ }
            persistExecScheduleOutcome(loopState, 'failed', `${reason} (exit ${rc})`);
            loopLog(terminalSessionId, 'exec-driver:halt', `halting loop: ${reason}`, {
              rc, iterDurationMs, consecutiveNonZero, consecutiveFastFails,
            });
            clearInterval(interval);
            cleanupExecLoopArtifacts(session);
            try { session.pty?.kill?.(); } catch { /* ok */ }
            driving = false;
            return;
          }

          session._loopDriverBuffer = '';
          session._execDriverState = 'ready';
          // Cooldown before next iteration
          await new Promise(r => setTimeout(r, 3000));
        }
      }
    } catch (err) {
      console.error('[exec-loop-driver] Error:', err.message);
      loopState.active = false;
      loopState.completedAt = new Date().toISOString();
      loopState.stoppedReason = 'exec-driver-error';
      loopState.lastError = err.message;
      try { writeFileSync(loopPath, JSON.stringify(loopState, null, 2)); } catch {}
      persistExecScheduleOutcome(loopState, 'failed', err.message || 'Exec driver error');
      loopLog(terminalSessionId, 'exec-driver:error', 'fatal exec driver error', { error: err.message });
      clearInterval(interval);
      cleanupExecLoopArtifacts(session);
      try { session.pty?.kill?.(); } catch {}
    }
    driving = false;
  }, 2000);

  session._loopDriverInterval = interval;
}

// ── Last Session (resume after server restart) ──

const LAST_SESSION_PATH = resolve(DATA_HOME, 'data', 'last-session.json');

app.get('/api/last-session', (req, res) => {
  try {
    const fileExists = existsSync(LAST_SESSION_PATH);
    const activeCount = [...terminalSessions.values()].filter(s => s.profile === 'claude-code').length;
    console.log(`[last-session] Check: file=${fileExists}, activeClaude=${activeCount}`);
    if (!fileExists) return res.status(404).json({ error: 'No saved session' });
    // If there are currently active claude-code sessions, the snapshot is live — don't offer resume
    if (activeCount > 0) return res.status(404).json({ error: 'Sessions still active' });
    const raw = readFileSync(LAST_SESSION_PATH, 'utf-8').trim();
    if (!raw) {
      unlinkSync(LAST_SESSION_PATH);
      return res.status(404).json({ error: 'Empty snapshot — cleaned up' });
    }
    const data = JSON.parse(raw);
    // Enrich with labels from ui-state
    const uiState = loadUiState();
    for (const s of data.sessions || []) {
      const labelKey = `synabun-session-label:${s.claudeSessionId}`;
      if (uiState[labelKey]) s.label = uiState[labelKey];
    }
    console.log(`[last-session] Returning ${data.sessions?.length} sessions`);
    res.json(data);
  } catch (err) {
    console.error('[last-session] Error:', err);
    // Corrupt file — clean it up so it doesn't keep failing
    if (err instanceof SyntaxError) {
      try { unlinkSync(LAST_SESSION_PATH); } catch {}
      return res.status(404).json({ error: 'Corrupt snapshot — cleaned up' });
    }
    res.status(500).json({ error: err.message });
  }
});

app.delete('/api/last-session', (req, res) => {
  try {
    if (existsSync(LAST_SESSION_PATH)) unlinkSync(LAST_SESSION_PATH);
    res.json({ ok: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// ═══════════════════════════════════════════
// SESSION MONITOR — Registry + Leak Detection
// ═══════════════════════════════════════════

const sessionRegistry = new Map(); // claudeSessionId → { cwd, profile, pid, connectedAt, lastActivity, terminalType, terminalSessionId, source }
const sessionMonitorClients = new Set(); // WebSocket clients for /ws/sessions
const LEAK_SCAN_INTERVAL_MS = 10_000;
const PENDING_REMEMBER_DIR = resolve(DATA_HOME, 'data', 'pending-remember');
const LOOP_DIR_MONITOR = resolve(DATA_HOME, 'data', 'loop');

function broadcastSessionEvent(event) {
  const data = JSON.stringify(event);
  for (const client of sessionMonitorClients) {
    if (client.readyState === 1) client.send(data);
  }
  broadcastSync(event);
}

function registerSession(claudeSessionId, meta) {
  const existing = sessionRegistry.get(claudeSessionId);
  const entry = {
    claudeSessionId,
    cwd: meta.cwd || '',
    profile: meta.profile || 'claude-code',
    pid: meta.pid || null,
    connectedAt: existing?.connectedAt || Date.now(),
    lastActivity: Date.now(),
    terminalType: meta.terminalType || 'external',
    terminalSessionId: meta.terminalSessionId || null,
    source: meta.source || 'hook',
    project: meta.project || '',
  };
  sessionRegistry.set(claudeSessionId, entry);
  broadcastSessionEvent({ type: 'session:registered', session: entry });
  return entry;
}

function unregisterSession(claudeSessionId) {
  if (!sessionRegistry.has(claudeSessionId)) return;
  sessionRegistry.delete(claudeSessionId);
  broadcastSessionEvent({ type: 'session:unregistered', claudeSessionId });
}

function classifyTerminalType(terminalSessionId) {
  const uiState = loadUiState();
  if (uiState['neural-terminal-detached']) return 'floating';
  return 'terminal';
}

const STALE_HOOK_SESSION_MS = 30 * 60 * 1000;

function syncRegistryFromTerminals() {
  for (const [tsId, session] of terminalSessions) {
    if (session.profile !== 'claude-code') continue;
    if (!session.claudeSessionId) continue;
    const existing = sessionRegistry.get(session.claudeSessionId);
    if (!existing || existing.terminalSessionId !== tsId) {
      registerSession(session.claudeSessionId, {
        cwd: session.cwd,
        profile: session.profile,
        terminalType: classifyTerminalType(tsId),
        terminalSessionId: tsId,
        source: 'terminal',
      });
    }
  }
  const now = Date.now();
  for (const [csId, entry] of sessionRegistry) {
    if (entry.terminalSessionId && !terminalSessions.has(entry.terminalSessionId)) {
      unregisterSession(csId);
    } else if (!entry.terminalSessionId && (now - (entry.lastActivity || 0)) > STALE_HOOK_SESSION_MS) {
      unregisterSession(csId);
    }
  }
}

// ── Leak Detection ──

function scanForLeaks() {
  const leaks = [];
  const now = Date.now();
  const activeSessionIds = new Set(sessionRegistry.keys());
  for (const [, s] of terminalSessions) {
    if (s.claudeSessionId) activeSessionIds.add(s.claudeSessionId);
  }

  // 1. Orphaned pending-remember files
  try {
    if (existsSync(PENDING_REMEMBER_DIR)) {
      const files = readdirSync(PENDING_REMEMBER_DIR).filter(f => f.endsWith('.json') && !f.startsWith('test-'));
      for (const f of files) {
        const filePath = join(PENDING_REMEMBER_DIR, f);
        try {
          const fstat = statSync(filePath);
          const ageMs = now - fstat.mtimeMs;
          if (ageMs < 5 * 60 * 1000) continue;
          const sid = f.replace('.json', '');
          if (!activeSessionIds.has(sid)) {
            leaks.push({ type: 'orphaned-state', severity: ageMs > 30 * 60 * 1000 ? 'warning' : 'info', description: `Orphaned pending-remember flag (${Math.round(ageMs / 60000)}m old)`, file: filePath, sessionId: sid, ageMs });
          }
        } catch { /* skip */ }
      }
    }
  } catch { /* ok */ }

  // 2. Orphaned loop files
  try {
    if (existsSync(LOOP_DIR_MONITOR)) {
      const files = readdirSync(LOOP_DIR_MONITOR).filter(f => f.endsWith('.json') && !f.startsWith('pending-'));
      for (const f of files) {
        const filePath = join(LOOP_DIR_MONITOR, f);
        try {
          const data = JSON.parse(readFileSync(filePath, 'utf-8'));
          if (data.stopped || data.finishedAt) continue;
          const fstat = statSync(filePath);
          const ageMs = now - fstat.mtimeMs;
          if (ageMs < 2 * 60 * 1000) continue;
          const sid = f.replace('.json', '');
          if (!activeSessionIds.has(sid) && data.active) {
            leaks.push({ type: 'orphaned-loop', severity: 'warning', description: `Active loop with no session (${data.template || 'custom'}, ${Math.round(ageMs / 60000)}m stale)`, file: filePath, sessionId: sid, ageMs, loopData: { template: data.template, currentIteration: data.currentIteration, maxIterations: data.maxIterations } });
          }
        } catch { /* skip */ }
      }
    }
  } catch { /* ok */ }

  // 3. Multiple sessions targeting same cwd (alive only)
  const ALIVE_THRESHOLD_MS = 5 * 60 * 1000;
  const cwdMap = new Map();
  for (const [csId, entry] of sessionRegistry) {
    if (!entry.cwd) continue;
    const isAlive = entry.terminalSessionId
      ? terminalSessions.has(entry.terminalSessionId)
      : (now - (entry.lastActivity || 0)) < ALIVE_THRESHOLD_MS;
    if (!isAlive) continue;
    if (!cwdMap.has(entry.cwd)) cwdMap.set(entry.cwd, []);
    cwdMap.get(entry.cwd).push(csId);
  }
  for (const [cwd, sessions] of cwdMap) {
    if (sessions.length > 1) {
      leaks.push({ type: 'multi-session-cwd', severity: 'critical', description: `${sessions.length} sessions targeting same directory`, cwd, sessions });
    }
  }

  // 4. Stale precompact flags
  const precompactDir = resolve(DATA_HOME, 'data', 'precompact');
  try {
    if (existsSync(precompactDir)) {
      const files = readdirSync(precompactDir).filter(f => f.endsWith('.json'));
      for (const f of files) {
        const filePath = join(precompactDir, f);
        try {
          const fstat = statSync(filePath);
          const ageMs = now - fstat.mtimeMs;
          if (ageMs > 10 * 60 * 1000) {
            leaks.push({ type: 'stale-precompact', severity: 'info', description: `Stale precompact cache (${Math.round(ageMs / 60000)}m old)`, file: filePath, sessionId: f.replace('.json', ''), ageMs });
          }
        } catch { /* skip */ }
      }
    }
  } catch { /* ok */ }

  return leaks;
}

let _lastLeakHash = '';
setInterval(() => {
  syncRegistryFromTerminals();
  const leaks = scanForLeaks();
  // Strip ageMs AND description (which embeds age as "Xm old") to prevent
  // broadcasts every ~60s when the minute counter ticks in descriptions
  const hash = JSON.stringify(leaks.map(l => { const { ageMs, description, ...stable } = l; return stable; }));
  if (hash !== _lastLeakHash) {
    _lastLeakHash = hash;
    if (leaks.length > 0) broadcastSessionEvent({ type: 'session:leaks', leaks });
  }
}, LEAK_SCAN_INTERVAL_MS);

// Inline scan of LOOP_DIR matching the GET /api/loop/list shape. Used by both
// the WS init payload and the periodic broadcast so the Session Monitor stays
// in sync with the Loops tab without a separate fetch.
function scanLoopInventory() {
  const result = { loops: [], staleCount: 0 };
  try {
    if (!existsSync(LOOP_DIR)) return result;
    const files = readdirSync(LOOP_DIR).filter(f => f.endsWith('.json') && f !== '.gitkeep' && !f.startsWith('pending-') && f !== 'active-pointer.json');
    const now = Date.now();
    for (const f of files) {
      try {
        const filePath = resolve(LOOP_DIR, f);
        const data = JSON.parse(readFileSync(filePath, 'utf-8'));
        const startedAtMs = data.startedAt ? new Date(data.startedAt).getTime() : 0;
        const lastIterAtMs = data.lastIterationAt ? new Date(data.lastIterationAt).getTime() : startedAtMs;
        const elapsedMs = startedAtMs ? now - startedAtMs : 0;
        const stalledMs = lastIterAtMs ? now - lastIterAtMs : 0;
        const terminalAlive = isLoopRuntimeAlive(data);
        const iterDone = (data.currentIteration || 0) >= (data.totalIterations || 0) && (data.totalIterations || 0) > 0;
        let state;
        if (data.active === false) { state = 'stale-inactive'; result.staleCount++; }
        else if (data.terminalSessionId && !terminalAlive) state = data.runtimeType === 'native' ? 'orphaned-native' : 'orphaned-pty';
        else if (iterDone) state = 'finished';
        else state = 'active';
        result.loops.push({
          sessionId: f.replace('.json', ''),
          terminalSessionId: data.terminalSessionId || null,
          terminalAlive,
          task: typeof data.task === 'string' ? data.task.slice(0, 200) : '',
          currentIteration: data.currentIteration || 0,
          totalIterations: data.totalIterations || 0,
          startedAt: data.startedAt || null,
          lastIterationAt: data.lastIterationAt || null,
          elapsedMinutes: Math.round(elapsedMs / 60000),
          stalledMinutes: Math.round(stalledMs / 60000),
          stalledMs,
          state,
          browserSessionId: data.browserSessionId || null,
          browserTabId: data.browserTabId || null,
          usesBrowser: !!data.usesBrowser,
        });
      } catch { /* skip corrupt */ }
    }
    result.loops.sort((a, b) => (b.startedAt || '').localeCompare(a.startedAt || ''));
  } catch { /* ok */ }
  return result;
}

let _lastLoopHash = '';
setInterval(() => {
  const inventory = scanLoopInventory();
  // Hash on stable fields only (drop minute counters that tick every poll)
  const hash = JSON.stringify({
    staleCount: inventory.staleCount,
    loops: inventory.loops.map(l => ({
      sessionId: l.sessionId, state: l.state, terminalAlive: l.terminalAlive,
      currentIteration: l.currentIteration, totalIterations: l.totalIterations,
    })),
  });
  if (hash !== _lastLoopHash) {
    _lastLoopHash = hash;
    broadcastSessionEvent({ type: 'session:loops', loops: inventory.loops, staleCount: inventory.staleCount });
  }
}, LEAK_SCAN_INTERVAL_MS);

// ── Session Monitor API ──

app.post('/api/sessions/register', express.json(), (req, res) => {
  const { claudeSessionId, cwd, profile, pid, terminalType, source, project } = req.body || {};
  if (!claudeSessionId) return res.status(400).json({ error: 'claudeSessionId required' });
  const entry = registerSession(claudeSessionId, { cwd, profile, pid, terminalType, source, project });
  res.json({ ok: true, session: entry });
});

app.post('/api/sessions/heartbeat', express.json(), (req, res) => {
  const { claudeSessionId } = req.body || {};
  if (!claudeSessionId) return res.status(400).json({ error: 'claudeSessionId required' });
  const entry = sessionRegistry.get(claudeSessionId);
  if (entry) { entry.lastActivity = Date.now(); res.json({ ok: true }); }
  else res.status(404).json({ error: 'Session not registered' });
});

app.delete('/api/sessions/:id', (req, res) => {
  unregisterSession(req.params.id);
  res.json({ ok: true });
});

app.get('/api/sessions/active', (req, res) => {
  syncRegistryFromTerminals();
  const sessions = [...sessionRegistry.values()].map(s => ({
    ...s,
    isAlive: s.terminalSessionId ? terminalSessions.has(s.terminalSessionId) : (Date.now() - s.lastActivity < 5 * 60 * 1000),
  }));
  res.json({ sessions });
});

app.get('/api/sessions/:id/state', (req, res) => {
  const csId = req.params.id;
  const entry = sessionRegistry.get(csId);
  if (!entry) return res.status(404).json({ error: 'Session not found' });
  const ownedFiles = [];
  try {
    const prPath = join(PENDING_REMEMBER_DIR, `${csId}.json`);
    if (existsSync(prPath)) ownedFiles.push({ type: 'pending-remember', path: prPath, data: JSON.parse(readFileSync(prPath, 'utf-8')) });
  } catch { /* ok */ }
  try {
    const loopPath = join(LOOP_DIR_MONITOR, `${csId}.json`);
    if (existsSync(loopPath)) ownedFiles.push({ type: 'loop', path: loopPath, data: JSON.parse(readFileSync(loopPath, 'utf-8')) });
  } catch { /* ok */ }
  res.json({ session: entry, ownedFiles });
});

app.get('/api/sessions/leaks', (req, res) => {
  syncRegistryFromTerminals();
  res.json({ leaks: scanForLeaks(), scannedAt: Date.now() });
});

app.post('/api/sessions/cleanup', express.json(), (req, res) => {
  const { types } = req.body || {};
  const allowedTypes = new Set(types || ['orphaned-state', 'stale-precompact']);
  const leaks = scanForLeaks();
  let cleaned = 0;
  for (const leak of leaks) {
    if (!allowedTypes.has(leak.type) || !leak.file) continue;
    try { unlinkSync(leak.file); cleaned++; } catch { /* skip */ }
  }
  res.json({ ok: true, cleaned, total: leaks.length });
});

// GET /api/sessions/pending-remember-prompt — build the prompt that processes
// orphaned pending-remember flags. The client routes this prompt to the
// chosen provider sidepanel (Claude Code / Codex / OpenCode) — no agent spawn.
app.get('/api/sessions/pending-remember-prompt', (req, res) => {
  try {
    const leaks = scanForLeaks().filter(l =>
      l.type === 'orphaned-state' && l.file && l.file.includes('pending-remember') && l.sessionId
    );
    if (leaks.length === 0) return res.json({ ok: true, count: 0, prompt: '', message: 'No pending-remember flags to process.' });

    const homeDir = process.env.HOME || process.env.USERPROFILE || '';
    const claudeProjectsDir = join(homeDir, '.claude', 'projects');

    const targets = leaks.map(l => {
      let transcriptPath = null;
      try {
        if (existsSync(claudeProjectsDir)) {
          const projDirs = readdirSync(claudeProjectsDir, { withFileTypes: true }).filter(d => d.isDirectory());
          for (const d of projDirs) {
            const candidate = join(claudeProjectsDir, d.name, `${l.sessionId}.jsonl`);
            if (existsSync(candidate)) { transcriptPath = candidate; break; }
          }
        }
      } catch { /* ignore */ }
      return { sessionId: l.sessionId, flagFile: l.file, transcriptPath, ageMs: l.ageMs };
    });

    const lines = targets.map((t, i) =>
      `${i + 1}. session=${t.sessionId}\n   flag=${t.flagFile}\n   transcript=${t.transcriptPath || '(not found)'}`
    ).join('\n');

    const prompt = [
      'Process orphaned pending-remember flags. Each flag corresponds to a Claude Code session whose auto-remember never fired.',
      '',
      'For each target below:',
      '1. If a transcript path is given, read it (JSONL — read enough to identify edited files, decisions, fixes, features).',
      '2. If the session did substantive work, call the `remember` MCP tool with: clear summary (what + why + how), appropriate category, project="synabun", related_files (paths actually touched), 3-5 tags, importance 5-7 (8+ only if architectural).',
      '3. If the transcript is missing, empty, or shows trivial activity (Q&A, no edits), skip the remember step.',
      '4. After deciding, DELETE the flag file using a shell command: `rm "<flagFile>"`.',
      '5. Move to the next target. Do not narrate between items — just execute.',
      '',
      `Targets (${targets.length}):`,
      lines,
      '',
      'When all targets are processed, output one line: "Processed N flags: M memories created, K skipped."',
    ].join('\n');

    res.json({ ok: true, count: targets.length, prompt });
  } catch (err) {
    console.error('GET /api/sessions/pending-remember-prompt error:', err.message);
    res.status(500).json({ error: err.message });
  }
});

// ── Session Monitor WebSocket ──

function handleSessionMonitorWebSocket(ws) {
  sessionMonitorClients.add(ws);
  syncRegistryFromTerminals();
  const sessions = [...sessionRegistry.values()].map(s => ({
    ...s,
    isAlive: s.terminalSessionId ? terminalSessions.has(s.terminalSessionId) : (Date.now() - s.lastActivity < 5 * 60 * 1000),
  }));
  const loopInv = scanLoopInventory();
  ws.send(JSON.stringify({ type: 'session:init', sessions, leaks: scanForLeaks(), loops: loopInv.loops, staleCount: loopInv.staleCount }));
  ws.on('close', () => sessionMonitorClients.delete(ws));
  ws.on('error', () => sessionMonitorClients.delete(ws));
}

// ── Terminal REST endpoints ──

app.get('/api/terminal/sessions', (req, res) => {
  const sessions = [...terminalSessions.entries()].map(([id, s]) => ({
    id,
    profile: s.profile,
    cwd: s.cwd,
    createdAt: s.createdAt,
    clients: s.clients.size,
  }));
  res.json({ sessions });
});

app.post('/api/terminal/sessions', (req, res) => {
  const { profile = 'shell', cols = 120, rows = 30, cwd, resume, model, codexAccountId } = req.body;
  if (codexAccountId && profile !== 'codex') {
    return res.status(400).json({ error: 'Codex account selection is only valid for Codex terminals' });
  }
  const codexAccount = codexAccountId ? findCodexAccount(String(codexAccountId)) : null;
  if (codexAccountId && !codexAccount) {
    return res.status(400).json({ error: 'Unknown Codex account' });
  }
  const codexExtraEnv = codexAccount
    ? { CODEX_HOME: codexAccount.home || getCodexAccountHome(codexAccount.id) }
    : undefined;
  try {
    const sessionId = createTerminalSession(profile, cols, rows, cwd, { resume, model, extraEnv: codexExtraEnv });
    broadcastSync({ type: 'terminal:session-created', sessionId, profile });
    if (profile === 'claude-code') setTimeout(saveSessionSnapshot, 2000); // update resume snapshot
    res.json({ sessionId, profile, codexAccountId: profile === 'codex' ? (codexAccountId || 'default') : null });
  } catch (err) {
    let msg = err.message;
    if (process.platform !== 'win32' && (msg.includes('posix_spawn') || msg.includes('EACCES'))) {
      // Attempt auto-fix: chmod spawn-helper and retry once
      try {
        const ptyBase = resolve(__dirname, 'node_modules', 'node-pty');
        const sh = resolve(ptyBase, 'prebuilds', `${process.platform}-${process.arch}`, 'spawn-helper');
        if (existsSync(sh)) {
          chmodSync(sh, 0o755);
          console.log(`[pty] Auto-fixed spawn-helper permissions, retrying...`);
          const sessionId = createTerminalSession(profile, cols, rows, cwd, { resume, model, extraEnv: codexExtraEnv });
          broadcastSync({ type: 'terminal:session-created', sessionId, profile });
          if (profile === 'claude-code') setTimeout(saveSessionSnapshot, 2000);
          return res.json({ sessionId, profile, codexAccountId: profile === 'codex' ? (codexAccountId || 'default') : null });
        }
      } catch {}
      msg = `Terminal failed: spawn-helper lacks execute permission. Try: chmod +x neural-interface/node_modules/node-pty/prebuilds/${process.platform}-${process.arch}/spawn-helper`;
    }
    res.status(500).json({ error: msg });
  }
});

app.delete('/api/terminal/sessions/:id', (req, res) => {
  const session = terminalSessions.get(req.params.id);
  if (!session) return res.status(404).json({ error: 'Session not found' });
  const wasClaudeCode = session.profile === 'claude-code';
  session.pty.kill();
  // Clean up temp files from image paste
  if (session.tempFiles) {
    session.tempFiles.forEach(f => { try { unlinkSync(f); } catch {} });
  }
  terminalSessions.delete(req.params.id);
  broadcastSync({ type: 'terminal:session-deleted', sessionId: req.params.id });
  if (wasClaudeCode) setTimeout(saveSessionSnapshot, 500); // update resume snapshot
  res.json({ ok: true });
});

app.get('/api/terminal/profiles', (req, res) => {
  const profileIds = ['claude-code', 'codex', 'gemini', 'shell'];
  const profiles = profileIds.map(id => {
    const p = getTerminalProfile(id);
    return { id, shell: p.shell, args: p.args };
  });
  const projects = loadHookProjects().map(p => ({ path: p.path, label: p.label || basename(p.path) }));
  res.json({ profiles, projects });
});

// Detect Claude Code session UUID for a given cwd (finds newest JSONL modified after createdAfter)
// exclude: Set of session IDs to skip (already claimed by other terminals)
function detectClaudeSessionForCwd(cwd, createdAfter = 0, exclude = null) {
  if (!cwd) return null;
  try {
    const homeDir = process.env.USERPROFILE || process.env.HOME;
    const claudeProjectsDir = join(homeDir, '.claude', 'projects');
    const projKeyLower = pathToClaudeKey(cwd).replace(/^([A-Z])/, m => m.toLowerCase());
    const projKeyUpper = pathToClaudeKey(cwd);
    let projDir = join(claudeProjectsDir, projKeyLower);
    if (!existsSync(projDir)) projDir = join(claudeProjectsDir, projKeyUpper);
    if (!existsSync(projDir)) return null;
    const files = readdirSync(projDir).filter(f => f.endsWith('.jsonl'));
    let newest = null, newestMtime = 0;
    for (const f of files) {
      const sid = f.replace('.jsonl', '');
      if (exclude && exclude.has(sid)) continue;
      try {
        const st = statSync(join(projDir, f));
        if (st.size < 1024) continue; // skip sidechains / empty snapshots
        const mtime = st.mtimeMs;
        if (mtime >= createdAfter && mtime > newestMtime) {
          newestMtime = mtime;
          newest = sid;
        }
      } catch {}
    }
    return newest;
  } catch { return null; }
}

// GET /api/terminal/sessions/:id/claude-session — detect Claude Code session UUID for a terminal
app.get('/api/terminal/sessions/:id/claude-session', (req, res) => {
  const session = terminalSessions.get(req.params.id);
  if (!session) return res.status(404).json({ error: 'Session not found' });
  if (session.profile !== 'claude-code') return res.json({ claudeSessionId: null });
  const csid = session.claudeSessionId || detectClaudeSessionForCwd(session.cwd, session.createdAt);
  if (csid) session.claudeSessionId = csid; // cache for snapshot
  res.json({ claudeSessionId: csid });
});

// ── Terminal file tree ──

const IS_WINDOWS = process.platform === 'win32';
let _gitMissingLogged = false;
let _gitExePath = null;   // Cached absolute path — preferring .exe on Windows
let _gitResolved = false;

// Resolve git's absolute path at first use. On Windows, `where git` lists all matches;
// prefer .exe so spawnSync works without cmd.exe quoting issues. On Unix, use `command -v`.
function resolveGitPath() {
  if (_gitResolved) return _gitExePath;
  _gitResolved = true;
  try {
    const cmd = IS_WINDOWS ? 'where git' : 'command -v git';
    const out = execSync(cmd, { encoding: 'utf8', timeout: 3000, windowsHide: true, stdio: ['ignore', 'pipe', 'ignore'] }).trim();
    const lines = out.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
    if (IS_WINDOWS) {
      _gitExePath = lines.find(l => /\.exe$/i.test(l)) || lines[0] || null;
    } else {
      _gitExePath = lines[0] || null;
    }
    if (_gitExePath) console.log(`[git] resolved: ${_gitExePath}`);
    else console.warn('[git] resolver returned no paths');
  } catch (err) {
    console.warn('[git] resolution failed:', err?.message || String(err));
    _gitExePath = null;
  }
  return _gitExePath;
}

// Cross-platform git invocation. Uses resolved absolute path when possible (spawnable
// directly on all OSes with no shell/quoting pitfalls). Falls back to `shell: true` on
// Windows only when path resolution fails or when the resolved target is a .cmd/.bat shim.
function spawnGit(args, opts = {}) {
  const baseOpts = { stdio: 'pipe', timeout: 5000, windowsHide: true, ...opts };
  const gitPath = resolveGitPath();
  if (gitPath) {
    if (IS_WINDOWS && /\.(cmd|bat)$/i.test(gitPath)) {
      const quoted = args.map(a => /[\s()%&|<>^"']/.test(a) ? `"${String(a).replace(/"/g, '\\"')}"` : a);
      return spawnSync(gitPath, quoted, { ...baseOpts, shell: true });
    }
    return spawnSync(gitPath, args, baseOpts);
  }
  if (IS_WINDOWS) {
    const quoted = args.map(a => /[\s()%&|<>^"']/.test(a) ? `"${String(a).replace(/"/g, '\\"')}"` : a);
    return spawnSync('git', quoted, { ...baseOpts, shell: true });
  }
  return spawnSync('git', args, baseOpts);
}

function logGitFailure(where, err) {
  const msg = err?.stderr?.toString?.() || err?.message || String(err);
  if (!msg || /not a git repository/i.test(msg)) return;
  if (/ENOENT/i.test(msg) || /is not recognized/i.test(msg) || /command not found/i.test(msg)) {
    if (_gitMissingLogged) return;
    _gitMissingLogged = true;
    console.warn(`[git] '${where}' failed: git executable not found on PATH. Install Git and ensure it's on the Node process PATH.`);
    return;
  }
  console.warn(`[git] '${where}' failed:`, msg.trim().split('\n')[0]);
}

// Startup probe — always logs git status so Windows users can see whether git works at all.
setImmediate(() => {
  const probe = spawnGit(['--version'], { timeout: 3000 });
  if (probe.status === 0) {
    console.log(`[git] ${probe.stdout.toString().trim()} — OK`);
  } else {
    const msg = probe.stderr?.toString?.()?.trim() || probe.error?.message || 'unknown error';
    console.warn(`[git] startup probe FAILED: ${msg}. File explorer git UI will be hidden.`);
  }
});

// Git "dubious ownership" detection — CVE-2022-24765 safety check refuses to operate on
// repos owned by a different OS user/SID. Common on Windows external drives or repos
// copied from another machine. Returns true only when git emits the specific error.
function detectDubiousOwnership(dir) {
  const r = spawnGit(['rev-parse', '--is-inside-work-tree'], { cwd: dir, timeout: 3000 });
  if (r.status === 0) return false;
  const stderr = r.stderr?.toString?.() || '';
  return /dubious ownership|safe\.directory/i.test(stderr);
}

// Normalize a filesystem path for `git config --add safe.directory` — forward-slashed
// absolute path, no trailing slash.
function normalizeGitPath(dir) {
  return String(dir).replace(/\\/g, '/').replace(/\/+$/, '');
}

/** Try to get git status for a directory. Returns { branch, statuses } or null. */
function getGitInfo(dir) {
  // Check if inside a git work tree (spawnGit for consistent path resolution)
  const inside = spawnGit(['rev-parse', '--is-inside-work-tree'], { cwd: dir, timeout: 3000 });
  if (inside.status !== 0) {
    logGitFailure('rev-parse --is-inside-work-tree', inside.error || { stderr: inside.stderr });
    return null;
  }

  // Get branch name — try --show-current first (git 2.22+), then fall back to
  // --abbrev-ref HEAD (works on older git; detached HEAD returns the literal "HEAD"),
  // then short SHA for detached HEAD. The chained fallback is essential for Windows users
  // with older Git for Windows installs where --show-current exits non-zero.
  let branch = '';
  const showCurrent = spawnGit(['branch', '--show-current'], { cwd: dir, timeout: 3000 });
  if (showCurrent.status === 0) {
    branch = showCurrent.stdout.toString().trim();
  } else {
    logGitFailure('branch --show-current', showCurrent.error || { stderr: showCurrent.stderr });
  }
  if (!branch) {
    const abbrev = spawnGit(['rev-parse', '--abbrev-ref', 'HEAD'], { cwd: dir, timeout: 3000 });
    if (abbrev.status === 0) {
      const b = abbrev.stdout.toString().trim();
      if (b && b !== 'HEAD') branch = b;
    }
  }
  if (!branch) {
    const shortSha = spawnGit(['rev-parse', '--short', 'HEAD'], { cwd: dir, timeout: 3000 });
    if (shortSha.status === 0) branch = shortSha.stdout.toString().trim();
  }

  try {
    // Get status for this directory (porcelain v1: XY <path>)
    const statusResult = spawnGit(['status', '--porcelain', '-u', '.'], { cwd: dir, maxBuffer: 256 * 1024 * 1024 });
    if (statusResult.status !== 0) {
      logGitFailure('status --porcelain', statusResult.error || { stderr: statusResult.stderr });
      return { branch, statuses: new Map() };
    }
    const raw = statusResult.stdout.toString();
    const statuses = new Map(); // name → status code

    for (const line of raw.split('\n')) {
      if (!line || line.length < 4) continue;
      const xy = line.substring(0, 2); // index + worktree status
      let filePath = line.substring(3);
      // Handle renames: "R  old -> new"
      const arrowIdx = filePath.indexOf(' -> ');
      if (arrowIdx !== -1) filePath = filePath.substring(arrowIdx + 4);

      // Get the immediate child name relative to this directory
      const sep = filePath.indexOf('/');
      const childName = sep === -1 ? filePath : filePath.substring(0, sep);

      // Map XY to a simplified status
      let status;
      const x = xy[0], y = xy[1];
      if (xy === '??') status = 'untracked';
      else if (xy === '!!') continue; // ignored
      else if (x === 'U' || y === 'U' || xy === 'DD' || xy === 'AA') status = 'conflict';
      else if (x === 'A') status = 'added';
      else if (x === 'D' || y === 'D') status = 'deleted';
      else if (x === 'R') status = 'renamed';
      else if (x !== ' ' && y !== ' ') status = 'mixed'; // staged + unstaged changes
      else if (x !== ' ') status = 'staged';
      else if (y !== ' ') status = 'modified';
      else continue;

      // For directories: escalate priority (conflict > modified > staged > added > untracked)
      const existing = statuses.get(childName);
      if (!existing || gitStatusPriority(status) > gitStatusPriority(existing)) {
        statuses.set(childName, status);
      }
    }

    return { branch, statuses };
  } catch (err) {
    logGitFailure('getGitInfo status-parse', err);
    return { branch, statuses: new Map() };
  }
}

const GIT_STATUS_PRIORITY = { untracked: 1, added: 2, renamed: 2, staged: 3, modified: 4, mixed: 5, deleted: 5, conflict: 6 };
function gitStatusPriority(s) { return GIT_STATUS_PRIORITY[s] || 0; }

app.get('/api/terminal/files', (req, res) => {
  const dir = req.query.path;
  if (!dir || typeof dir !== 'string') return res.status(400).json({ error: 'path required' });
  const search = (req.query.search || '').trim().toLowerCase();

  // Recursive search mode — return flat list of matching files
  if (search) {
    const SKIP = new Set(['.git', 'node_modules', '__pycache__', '.next', '.cache', 'dist', 'build', '.turbo']);
    const MAX_RESULTS = 80;
    const results = [];

    function walk(current, rel) {
      if (results.length >= MAX_RESULTS) return;
      let entries;
      try { entries = readdirSync(current, { withFileTypes: true }); } catch { return; }
      for (const e of entries) {
        if (results.length >= MAX_RESULTS) return;
        if (e.name.startsWith('.') && SKIP.has(e.name)) continue;
        if (SKIP.has(e.name)) continue;
        const childRel = rel ? rel + '/' + e.name : e.name;
        if (e.isDirectory()) {
          if (e.name.toLowerCase().includes(search)) {
            results.push({ name: childRel, type: 'dir' });
          }
          walk(resolve(current, e.name), childRel);
        } else {
          if (e.name.toLowerCase().includes(search)) {
            results.push({ name: childRel, type: 'file' });
          }
        }
      }
    }

    try {
      walk(dir, '');
      res.json({ path: dir, items: results, branch: null, search: true });
    } catch (err) {
      res.status(500).json({ error: err.message });
    }
    return;
  }

  try {
    const entries = readdirSync(dir, { withFileTypes: true });
    const items = [];
    for (const e of entries) {
      // Skip hidden/system files
      if (e.name.startsWith('.') || e.name === 'node_modules' || e.name === '__pycache__') continue;
      items.push({ name: e.name, type: e.isDirectory() ? 'dir' : 'file' });
    }
    // Sort: directories first, then alphabetical
    items.sort((a, b) => {
      if (a.type !== b.type) return a.type === 'dir' ? -1 : 1;
      return a.name.localeCompare(b.name, undefined, { sensitivity: 'base' });
    });

    // Try git — gracefully ignored if unavailable
    const git = getGitInfo(dir);
    if (git) {
      for (const item of items) {
        const s = git.statuses.get(item.name);
        if (s) item.git = s;
      }
    }

    res.json({ path: dir, items, branch: git?.branch || null });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get('/api/terminal/branches', (req, res) => {
  const dir = req.query.path;
  if (!dir || typeof dir !== 'string') return res.status(400).json({ error: 'path required' });

  const inside = spawnGit(['rev-parse', '--is-inside-work-tree'], { cwd: dir, timeout: 3000 });
  if (inside.status !== 0) {
    logGitFailure('branches: rev-parse', inside.error || { stderr: inside.stderr });
    return res.json({ branches: [], current: null });
  }

  try {
    // Current branch — chained fallback (older git may not support --show-current)
    let current = '';
    const showCurrent = spawnGit(['branch', '--show-current'], { cwd: dir, timeout: 3000 });
    if (showCurrent.status === 0) current = showCurrent.stdout.toString().trim();
    else logGitFailure('branches: show-current', showCurrent.error || { stderr: showCurrent.stderr });
    if (!current) {
      const abbrev = spawnGit(['rev-parse', '--abbrev-ref', 'HEAD'], { cwd: dir, timeout: 3000 });
      if (abbrev.status === 0) {
        const b = abbrev.stdout.toString().trim();
        if (b && b !== 'HEAD') current = b;
      }
    }

    // All local branches — plain `git branch` parsed manually; avoids --format=%(refname:short)
    // which can get mangled by cmd.exe variable expansion on Windows even with proper quoting.
    const branchResult = spawnGit(['branch'], { cwd: dir });
    if (branchResult.status !== 0) logGitFailure('branch list', branchResult.error || { stderr: branchResult.stderr });
    const raw = branchResult.status === 0 ? branchResult.stdout.toString() : '';
    // Plain `git branch` output: each line is "  branch" or "* branch" (current). Strip
    // marker + whitespace. Skip detached-HEAD lines like "* (HEAD detached at abc1234)".
    const branches = raw.split('\n')
      .map(l => l.replace(/^[\s*]+/, '').trim())
      .filter(b => b && !b.startsWith('(') && !b.includes(' -> '));

    res.json({ branches, current });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Trust a workspace path with git — runs `git config --global --add safe.directory <path>`
// so git stops refusing to operate on it (CVE-2022-24765 dubious-ownership protection).
// Triggered by the add-project UI flows when the server detects the dubious-ownership error.
app.post('/api/terminal/trust-workspace', (req, res) => {
  const { path: dir } = req.body || {};
  if (!dir || typeof dir !== 'string') return res.status(400).json({ ok: false, error: 'path required' });
  if (/[\x00-\x1f]/.test(dir) || dir === '*' || dir === '/' || dir === '\\') {
    return res.status(400).json({ ok: false, error: 'Invalid path' });
  }
  let abs;
  try {
    abs = resolve(dir);
    if (!existsSync(abs)) return res.status(400).json({ ok: false, error: `Directory not found: ${abs}` });
    if (!statSync(abs).isDirectory()) return res.status(400).json({ ok: false, error: 'Path is not a directory' });
  } catch (err) {
    return res.status(400).json({ ok: false, error: err.message });
  }

  const gitPath = normalizeGitPath(abs);
  const r = spawnGit(['config', '--global', '--add', 'safe.directory', gitPath]);
  if (r.status !== 0) {
    const stderr = r.stderr?.toString?.()?.trim() || r.error?.message || 'git config failed';
    logGitFailure('config --add safe.directory', r.error || { stderr: r.stderr });
    return res.status(500).json({ ok: false, error: stderr });
  }

  // Confirm by re-probing
  const stillDubious = detectDubiousOwnership(abs);
  console.log(`[git] trusted workspace: ${gitPath}${stillDubious ? ' (but still flagged — check permissions)' : ''}`);
  res.json({ ok: true, path: gitPath, stillDubious });
});

app.post('/api/terminal/checkout', (req, res) => {
  const { path: dir, branch } = req.body;
  if (!dir || !branch) return res.status(400).json({ error: 'path and branch required' });

  // Validate branch name — only allow safe characters (letters, digits, /, -, _, .)
  if (!/^[\w.\-/]+$/.test(branch)) {
    return res.status(400).json({ error: 'Invalid branch name' });
  }

  const inside = spawnGit(['rev-parse', '--is-inside-work-tree'], { cwd: dir, timeout: 3000 });
  if (inside.status !== 0) {
    logGitFailure('checkout: rev-parse', inside.error || { stderr: inside.stderr });
    return res.status(400).json({ error: 'Not a git repository' });
  }

  // Branch is validated against /^[\w.\-/]+$/ above, so no shell metacharacters are possible.
  // No '--' separator — that would make git treat the branch name as a file pathspec.
  const result = spawnGit(['checkout', branch], { cwd: dir, timeout: 10000 });
  if (result.status !== 0) {
    const stderr = result.stderr?.toString?.()?.trim() || result.error?.message || 'Checkout failed';
    return res.status(500).json({ error: stderr });
  }

  // Return confirmed branch name + git's own output
  let current = '';
  const showCurrent = spawnGit(['branch', '--show-current'], { cwd: dir, timeout: 3000 });
  if (showCurrent.status === 0) current = showCurrent.stdout.toString().trim();
  else logGitFailure('checkout: show-current', showCurrent.error || { stderr: showCurrent.stderr });
  const output = result.stderr?.toString?.()?.trim() || `Switched to branch '${current}'`;
  res.json({ ok: true, branch: current, output });
});

// Polled by the file explorer — run git via async execFile (never blocks the
// event loop) and memoize per path for 1.5s so rapid polls share one result.
const _gitStatusCache = new Map(); // dir -> { at, promise }
const GIT_STATUS_TTL_MS = 1500;

async function computeGitStatus(dir) {
  try {
    await execFileAsync('git', ['rev-parse', '--is-inside-work-tree'], { cwd: dir, timeout: 3000 });
  } catch {
    return { ok: true, isGit: false, branch: null, changes: [] };
  }

  const resolveBranch = async () => {
    try {
      const { stdout } = await execFileAsync('git', ['branch', '--show-current'], { cwd: dir, timeout: 3000 });
      let branch = stdout.trim();
      if (!branch) {
        const { stdout: head } = await execFileAsync('git', ['rev-parse', '--short', 'HEAD'], { cwd: dir, timeout: 3000 });
        branch = head.trim();
      }
      return branch;
    } catch { return ''; }
  };

  const [branch, statusOut] = await Promise.all([
    resolveBranch(),
    execFileAsync('git', ['status', '--porcelain'], { cwd: dir, timeout: 5000, maxBuffer: 256 * 1024 * 1024 }),
  ]);

  const changes = [];
  for (const line of statusOut.stdout.split('\n')) {
    if (!line || line.length < 4) continue;
    const xy = line.substring(0, 2);
    let filePath = line.substring(3);
    const arrowIdx = filePath.indexOf(' -> ');
    if (arrowIdx !== -1) filePath = filePath.substring(arrowIdx + 4);
    const x = xy[0], y = xy[1];
    let staged = x !== ' ' && x !== '?';
    let status;
    if (xy === '??') status = 'untracked';
    else if (xy === '!!') continue;
    else if (x === 'U' || y === 'U' || xy === 'DD' || xy === 'AA') status = 'conflict';
    else if (x === 'A') status = 'added';
    else if (x === 'D' || y === 'D') status = 'deleted';
    else if (x === 'R') status = 'renamed';
    else if (x !== ' ' && y !== ' ') status = 'mixed';
    else if (x !== ' ') status = 'staged';
    else status = 'modified';
    changes.push({ path: filePath, status, staged });
  }

  return { ok: true, isGit: true, branch, changes };
}

app.get('/api/git/status', async (req, res) => {
  const dir = req.query.path;
  if (!dir || typeof dir !== 'string') return res.status(400).json({ error: 'path required' });

  let entry = _gitStatusCache.get(dir);
  if (!entry || Date.now() - entry.at >= GIT_STATUS_TTL_MS) {
    const promise = computeGitStatus(dir);
    entry = { at: Date.now(), promise };
    _gitStatusCache.set(dir, entry);
    // Failed computations shouldn't be served for the rest of the TTL.
    promise.catch(() => {
      if (_gitStatusCache.get(dir)?.promise === promise) _gitStatusCache.delete(dir);
    });
    // Keep the map bounded across many distinct paths.
    if (_gitStatusCache.size > 100) {
      const cutoff = Date.now() - 60_000;
      for (const [k, v] of _gitStatusCache) if (v.at < cutoff) _gitStatusCache.delete(k);
    }
  }

  try {
    res.json(await entry.promise);
  } catch (err) {
    res.status(500).json({ error: err.stderr?.toString?.()?.trim?.() || err.message });
  }
});

app.post('/api/git/commit', (req, res) => {
  const { path: dir, message, files } = req.body;
  if (!dir || !message) return res.status(400).json({ error: 'path and message required' });
  if (typeof message !== 'string' || message.trim().length === 0) return res.status(400).json({ error: 'Commit message cannot be empty' });

  try {
    execSync('git rev-parse --is-inside-work-tree', { cwd: dir, stdio: 'pipe', timeout: 3000 });
  } catch {
    return res.status(400).json({ error: 'Not a git repository' });
  }

  try {
    // Stage: specific files or all changes
    if (Array.isArray(files) && files.length > 0) {
      // Validate file paths — no shell injection
      for (const f of files) {
        if (typeof f !== 'string' || f.includes('..')) return res.status(400).json({ error: 'Invalid file path' });
      }
      const result = spawnSync('git', ['add', '--', ...files], { cwd: dir, stdio: 'pipe', timeout: 10000 });
      if (result.status !== 0) return res.status(500).json({ error: result.stderr?.toString?.()?.trim() || 'Stage failed' });
    } else {
      // Stage all changes
      const result = spawnSync('git', ['add', '-A'], { cwd: dir, stdio: 'pipe', timeout: 10000 });
      if (result.status !== 0) return res.status(500).json({ error: result.stderr?.toString?.()?.trim() || 'Stage failed' });
    }

    // Commit
    const result = spawnSync('git', ['commit', '-m', message.trim()], { cwd: dir, stdio: 'pipe', timeout: 15000 });
    if (result.status !== 0) {
      const stderr = result.stderr?.toString?.()?.trim() || '';
      const stdout = result.stdout?.toString?.()?.trim() || '';
      return res.status(500).json({ error: stderr || stdout || 'Commit failed' });
    }

    const output = result.stdout?.toString?.()?.trim() || 'Committed';
    res.json({ ok: true, output });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get('/api/git/diff-summary', (req, res) => {
  const dir = req.query.path;
  if (!dir || typeof dir !== 'string') return res.status(400).json({ error: 'path required' });

  try {
    execSync('git rev-parse --is-inside-work-tree', { cwd: dir, stdio: 'pipe', timeout: 3000 });
  } catch {
    return res.status(400).json({ error: 'Not a git repository' });
  }

  try {
    // Get diff stat for tracked files
    const stat = execSync('git diff --stat --stat-width=120', { cwd: dir, stdio: 'pipe', timeout: 5000 }).toString().trim();

    // Get diff stat for staged files
    const stagedStat = execSync('git diff --cached --stat --stat-width=120', { cwd: dir, stdio: 'pipe', timeout: 5000 }).toString().trim();

    // Get untracked files
    const untracked = execSync('git ls-files --others --exclude-standard', { cwd: dir, stdio: 'pipe', timeout: 5000 }).toString().trim();

    // Get short diff for context (limited to avoid huge payloads)
    const diff = execSync('git diff -U1 --no-color', { cwd: dir, stdio: 'pipe', timeout: 8000, maxBuffer: 64 * 1024 }).toString().substring(0, 4000);

    const stagedDiff = execSync('git diff --cached -U1 --no-color', { cwd: dir, stdio: 'pipe', timeout: 8000, maxBuffer: 64 * 1024 }).toString().substring(0, 4000);

    // Build a commit message from the changes
    const changedFiles = [];
    const statLines = (stat + '\n' + stagedStat).split('\n').filter(l => l.includes('|'));
    for (const line of statLines) {
      const match = line.match(/^\s*(.+?)\s*\|/);
      if (match) {
        const f = match[1].trim();
        if (!changedFiles.includes(f)) changedFiles.push(f);
      }
    }

    const untrackedFiles = untracked ? untracked.split('\n').filter(Boolean) : [];

    // Analyze diff to detect what kind of changes were made
    const allDiff = diff + '\n' + stagedDiff;
    const addedLines = (allDiff.match(/^\+[^+]/gm) || []).length;
    const removedLines = (allDiff.match(/^-[^-]/gm) || []).length;

    // Generate message
    let message = '';
    const totalFiles = changedFiles.length + untrackedFiles.length;

    if (totalFiles === 0) {
      return res.json({ ok: true, message: '', summary: 'No changes to commit' });
    }

    // Detect common patterns from file paths
    const dirs = new Set();
    for (const f of [...changedFiles, ...untrackedFiles]) {
      const parts = f.split('/');
      if (parts.length > 1) dirs.add(parts[0]);
    }

    // Build descriptive message
    if (totalFiles === 1) {
      const f = changedFiles[0] || untrackedFiles[0];
      const basename = f.split('/').pop();
      if (untrackedFiles.length === 1) message = 'Add ' + basename;
      else if (removedLines > addedLines * 2) message = 'Remove code from ' + basename;
      else message = 'Update ' + basename;
    } else if (totalFiles <= 4) {
      const names = [...changedFiles, ...untrackedFiles].map(f => f.split('/').pop());
      if (untrackedFiles.length === totalFiles) message = 'Add ' + names.join(', ');
      else message = 'Update ' + names.join(', ');
    } else {
      const scope = dirs.size === 1 ? [...dirs][0] : `${totalFiles} files`;
      if (untrackedFiles.length > changedFiles.length) message = 'Add and update ' + scope;
      else message = 'Update ' + scope;
    }

    const summary = `${changedFiles.length} modified, ${untrackedFiles.length} new — +${addedLines} -${removedLines} lines`;

    res.json({ ok: true, message, summary });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// ── Git Diff (raw content) ──

app.get('/api/git/diff', (req, res) => {
  const dir = req.query.path;
  if (!dir || typeof dir !== 'string') return res.status(400).json({ error: 'path required' });
  const maxLines = Math.min(Math.max(parseInt(req.query.maxLines) || 500, 50), 2000);

  try {
    execSync('git rev-parse --is-inside-work-tree', { cwd: dir, stdio: 'pipe', timeout: 3000 });
  } catch {
    return res.status(400).json({ error: 'Not a git repository' });
  }

  try {
    let branch = '';
    try { branch = execSync('git branch --show-current', { cwd: dir, stdio: 'pipe', timeout: 3000 }).toString().trim(); } catch {}
    if (!branch) try { branch = execSync('git rev-parse --short HEAD', { cwd: dir, stdio: 'pipe', timeout: 3000 }).toString().trim(); } catch {}

    const rawDiff = execSync('git diff --no-color', { cwd: dir, stdio: 'pipe', timeout: 10000, maxBuffer: 2 * 1024 * 1024 }).toString();
    const rawStaged = execSync('git diff --cached --no-color', { cwd: dir, stdio: 'pipe', timeout: 10000, maxBuffer: 2 * 1024 * 1024 }).toString();
    const untracked = execSync('git ls-files --others --exclude-standard', { cwd: dir, stdio: 'pipe', timeout: 5000 }).toString().trim();

    const truncate = (text) => {
      const lines = text.split('\n');
      if (lines.length <= maxLines) return { text, truncated: false };
      return { text: lines.slice(0, maxLines).join('\n'), truncated: true };
    };

    const d = truncate(rawDiff);
    const s = truncate(rawStaged);
    const untrackedFiles = untracked ? untracked.split('\n').filter(Boolean) : [];

    res.json({
      ok: true,
      branch,
      diff: d.text,
      stagedDiff: s.text,
      untrackedFiles,
      truncated: d.truncated || s.truncated
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// ── Git Log ──

app.get('/api/git/log', (req, res) => {
  const dir = req.query.path;
  if (!dir || typeof dir !== 'string') return res.status(400).json({ error: 'path required' });
  const count = Math.min(Math.max(parseInt(req.query.count) || 10, 1), 50);

  try {
    execSync('git rev-parse --is-inside-work-tree', { cwd: dir, stdio: 'pipe', timeout: 3000 });
  } catch {
    return res.status(400).json({ error: 'Not a git repository' });
  }

  try {
    const raw = execSync(`git log --oneline --no-decorate -n ${count}`, { cwd: dir, stdio: 'pipe', timeout: 5000 }).toString().trim();
    const commits = raw ? raw.split('\n').map(line => {
      const spaceIdx = line.indexOf(' ');
      return { hash: line.substring(0, spaceIdx), message: line.substring(spaceIdx + 1) };
    }) : [];
    res.json({ ok: true, commits });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// ── Git Generate Commit Message (AI-powered) ──

app.post('/api/git/generate-message', async (req, res) => {
  const dir = req.body?.path;
  if (!dir || typeof dir !== 'string') return res.status(400).json({ error: 'path required' });

  try {
    execSync('git rev-parse --is-inside-work-tree', { cwd: dir, stdio: 'pipe', timeout: 3000 });
  } catch {
    return res.status(400).json({ error: 'Not a git repository' });
  }

  // Gather diff data — separate try/catch per command so one failure doesn't skip the rest
  let diffText = '', stagedText = '', untrackedList = '', recentCommits = '';
  try { diffText = execSync('git diff --no-color', { cwd: dir, stdio: 'pipe', timeout: 8000, maxBuffer: 2 * 1024 * 1024 }).toString().substring(0, 4000); } catch {}
  try { stagedText = execSync('git diff --cached --no-color', { cwd: dir, stdio: 'pipe', timeout: 8000, maxBuffer: 2 * 1024 * 1024 }).toString().substring(0, 4000); } catch {}
  try { untrackedList = execSync('git ls-files --others --exclude-standard', { cwd: dir, stdio: 'pipe', timeout: 5000 }).toString().trim(); } catch {}
  try { recentCommits = execSync('git log --oneline --no-decorate -n 5', { cwd: dir, stdio: 'pipe', timeout: 3000 }).toString().trim(); } catch {}

  const allDiff = (diffText + '\n' + stagedText).trim();
  if (!allDiff && !untrackedList) {
    return res.json({ ok: true, message: '', source: 'heuristic', summary: 'No changes to commit' });
  }

  // Try Claude CLI
  let claudeAvailable = false;
  try {
    execSync(process.platform === 'win32' ? 'where claude' : 'which claude', { stdio: 'pipe', timeout: 3000 });
    claudeAvailable = true;
  } catch {}

  if (claudeAvailable) {
    try {
      const prompt = [
        'Generate a single-line git commit message for these changes.',
        'Match the style of recent commits shown below.',
        'Be specific about what changed. Output ONLY the commit message — no quotes, no prefix, no explanation.',
        '',
        '## Recent commits (for style reference)',
        recentCommits || '(none)',
        '',
        '## Diff',
        allDiff.substring(0, 3500),
        untrackedList ? '\n## New untracked files\n' + untrackedList.split('\n').slice(0, 20).join('\n') : '',
      ].join('\n');

      const { spawnSync: spawnS } = require('child_process');
      const result = spawnS('claude', ['-p', '--model', 'sonnet'], {
        input: prompt,
        cwd: dir,
        timeout: 30000,
        maxBuffer: 64 * 1024,
        stdio: ['pipe', 'pipe', 'pipe'],
        shell: true,
      });

      const output = (result.stdout || '').toString().trim();
      if (output && !result.error && result.status === 0) {
        // Clean up: remove quotes if Claude wrapped the message
        const cleaned = output.replace(/^["']|["']$/g, '').trim();
        if (cleaned) {
          return res.json({ ok: true, message: cleaned, source: 'claude' });
        }
      }
    } catch {}
  }

  // Fallback: heuristic (same logic as /api/git/diff-summary)
  try {
    let stat = '', stagedStat = '';
    try { stat = execSync('git diff --stat --stat-width=120', { cwd: dir, stdio: 'pipe', timeout: 5000, maxBuffer: 2 * 1024 * 1024 }).toString().trim(); } catch {}
    try { stagedStat = execSync('git diff --cached --stat --stat-width=120', { cwd: dir, stdio: 'pipe', timeout: 5000, maxBuffer: 2 * 1024 * 1024 }).toString().trim(); } catch {}
    const changedFiles = [];
    for (const line of (stat + '\n' + stagedStat).split('\n').filter(l => l.includes('|'))) {
      const m = line.match(/^\s*(.+?)\s*\|/);
      if (m) { const f = m[1].trim(); if (!changedFiles.includes(f)) changedFiles.push(f); }
    }
    const untrackedFiles = untrackedList ? untrackedList.split('\n').filter(Boolean) : [];
    const addedLines = (allDiff.match(/^\+[^+]/gm) || []).length;
    const removedLines = (allDiff.match(/^-[^-]/gm) || []).length;
    const totalFiles = changedFiles.length + untrackedFiles.length;

    let message = '';
    if (totalFiles === 0) {
      return res.json({ ok: true, message: '', source: 'heuristic', summary: 'No changes to commit' });
    }
    const dirs = new Set();
    for (const f of [...changedFiles, ...untrackedFiles]) {
      const parts = f.split('/');
      if (parts.length > 1) dirs.add(parts[0]);
    }
    if (totalFiles === 1) {
      const f = changedFiles[0] || untrackedFiles[0];
      const basename = f.split('/').pop();
      if (untrackedFiles.length === 1) message = 'Add ' + basename;
      else if (removedLines > addedLines * 2) message = 'Remove code from ' + basename;
      else message = 'Update ' + basename;
    } else if (totalFiles <= 4) {
      const names = [...changedFiles, ...untrackedFiles].map(f => f.split('/').pop());
      if (untrackedFiles.length === totalFiles) message = 'Add ' + names.join(', ');
      else message = 'Update ' + names.join(', ');
    } else {
      const scope = dirs.size === 1 ? [...dirs][0] : `${totalFiles} files`;
      if (untrackedFiles.length > changedFiles.length) message = 'Add and update ' + scope;
      else message = 'Update ' + scope;
    }

    const summary = `${changedFiles.length} modified, ${untrackedFiles.length} new — +${addedLines} -${removedLines} lines`;
    res.json({ ok: true, message, source: 'heuristic', summary });
  } catch (err) {
    res.status(500).json({ error: 'Failed to generate message: ' + err.message });
  }
});

